app.get('/manifest.json', (req, res) => {
  try {
    if (!_manifestBase) _manifestBase = JSON.parse(require('fs').readFileSync(path.join(__dirname, 'public', 'manifest.json'), 'utf8'));
    const m = Object.assign({}, _manifestBase);
    let a = String(req.query.a || ''), uName = String(req.query.u || '');
    const menu = String(req.query.menu || ''), fixed = req.query.fixed === '1', picked = req.query.picked === '1'; // #980
    // #826: si Safari pidió el manifest sin ?a (no tomó el cambio del <link>), el token sale de la cookie vip_inst (Path=/manifest.json).
    if (!a) {
      const ck = (String(req.headers.cookie || '').split(';').map((x) => x.trim()).find((x) => x.startsWith('vip_inst=')) || '').slice(9);
      const dot = ck.indexOf('.');
      if (dot > 0) { a = ck.slice(0, dot); if (!uName) { try { uName = decodeURIComponent(ck.slice(dot + 1)); } catch (_) {} } }
    }
    let su = '/?source=pwa';
    if (/^[A-Za-z0-9_-]{20,64}$/.test(a)) su += '&acceso=' + a;
    if (/^[A-Za-z0-9._-]{3,40}$/.test(uName)) su += '&u=' + encodeURIComponent(uName); // #826: si el acceso automático falla, el usuario ya viene escrito
    if (['full', 'basic', 'easy', 'girox'].includes(menu)) su += '&menu=' + menu + (fixed ? '&fixed=1' : '') + (picked ? '&picked=1' : '');
    m.start_url = su;
    res.setHeader('Vary', 'Cookie');
    res.setHeader('Content-Type', 'application/manifest+json; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
    res.json(m);
  } catch (e) { logger.warn(`[manifest] ${e.message}`); res.status(500).json({ error: 'manifest' }); }
});
app.use(express.static(path.join(__dirname, 'public'), {
  dotfiles: 'deny',
  index: false,
  // Default: cache static assets for 1 day. HTML, JS, CSS and service-worker
  // files override this below so that a redeploy is picked up immediately by
  // installed PWAs and browsers without waiting 24 hours.
  maxAge: '1d',
  setHeaders: (res, filePath) => {
    // #634: un js/css pedido con ?v=<versión> es inmutable (la versión nueva es otra URL): caché larga en navegador y SW.
    try { if ((filePath.endsWith('.js') || filePath.endsWith('.css')) && res.req && res.req.query && res.req.query.v) { res.setHeader('Cache-Control', 'public, max-age=31536000, immutable'); return; } } catch (_) {}
    // Never cache files that change with every deploy so installed PWAs always
    // get fresh code after a redeploy on AWS Elastic Beanstalk.
    const noCache =
      filePath.endsWith('.html') ||
      filePath.endsWith('.js') ||
      filePath.endsWith('.css') ||
      filePath.includes('firebase-messaging-sw') ||
      filePath.includes('user-sw') ||
      filePath.includes('admin-sw') ||
      filePath.includes('manifest.json');
    if (noCache) {
      res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
      res.setHeader('Pragma', 'no-cache');
      res.setHeader('Expires', '0');
    }
    // Serve manifest.json with the correct Content-Type for PWA installability.
    // Chrome requires application/manifest+json (or application/json) to recognise
    // the file as a Web App Manifest. Express static defaults to application/json
    // which Chrome accepts, but setting the canonical type is best practice.
    if (path.basename(filePath) === 'manifest.json') {
      res.setHeader('Content-Type', 'application/manifest+json; charset=utf-8');
    }
  }
}));

