// Generar número de cuenta
const generateAccountNumber = () => {
  return 'ACC' + Date.now().toString().slice(-8) + Math.random().toString(36).substr(2, 4).toUpperCase();
};

// Buscar usuario por teléfono
async function findUserByPhone(phone) {
  const user = await User.findOne({ $or: [{ phone }, { whatsapp: phone }] }).lean();
  if (user) {
    return { username: user.username, phone: user.phone, source: 'main' };
  }
  
  const externalUser = await ExternalUser.findOne({ $or: [{ phone }, { whatsapp: phone }] }).lean();
  if (externalUser) {
    return { username: externalUser.username, phone: externalUser.phone, source: 'external' };
  }
  
  return null;
}

// Cambiar contraseña por teléfono
async function changePasswordByPhone(phone, newPassword) {
  const user = await User.findOne({ $or: [{ phone }, { whatsapp: phone }] });
  
  if (!user) {
    return { success: false, error: 'Usuario no encontrado con ese número de teléfono' };
  }
  
  user.password = newPassword;
  user.passwordChangedAt = new Date();
  await user.save();
  
  return { success: true, username: user.username };
}

// Renderiza el texto de un mensaje automático editable desde la sección COMANDOS.
// Busca el Command por nombre; si existe y está activo usa su `response`, sino
// usa el `fallback` hardcodeado. Reemplaza variables {clave} por su valor.
//
// Convención de variables (igual que los comandos /sys_deposit existentes):
//   - Montos: el template escribe "${amount}" y acá reemplazamos "{amount}" por
//     el número → queda "$50000" (el $ es el signo de peso literal del template).
//   - Texto (username, bank, etc.): el template escribe "{username}" sin $ y se
//     reemplaza por el valor.
// Si el comando EXISTE (activo) pero su respuesta quedó VACÍA, se interpreta como
// "desactivado a propósito" → devuelve null para que el caller NO envíe el mensaje.
// Si el comando NO existe (instalación nueva, antes del seed) usa el fallback.
// Nunca lanza: ante error de DB devuelve el fallback ya renderizado.
// #773 (velocidad): los textos de COMANDOS se piden decenas de veces por minuto y cambian casi nunca ⇒ caché en memoria de 15 s
// (se vacía al guardar/borrar un comando desde el panel; en otra instancia de EB el cambio tarda hasta 15 s en verse).
const _cmdCache = new Map(); const CMD_CACHE_MS = 15000;
function _cmdCacheClear() { _cmdCache.clear(); }
async function _cmdLookup(name) {
  const hit = _cmdCache.get(name);
  if (hit && (Date.now() - hit.at) < CMD_CACHE_MS) return hit.cmd;
  const cmd = await Command.findOne({ name, isActive: true }).lean();
  _cmdCache.set(name, { cmd, at: Date.now() });
  return cmd;
}
async function renderSystemCommand(name, fallback, vars = {}) {
  let template = fallback;
  try {
    const cmd = await _cmdLookup(name);
    if (cmd) {
      // El comando existe: si lo vaciaron desde el panel, no se envía nada.
      if (!cmd.response || !String(cmd.response).trim()) return null;
      template = cmd.response;
    }
  } catch (e) {
    logger.warn(`[renderSystemCommand] ${name}: ${e.message} — usando fallback`);
  }
  if (template == null) return null;
  let out = template;
  for (const [k, v] of Object.entries(vars)) {
    out = out.replace(new RegExp('\\{' + k + '\\}', 'g'), v == null ? '' : String(v));
  }
  return out;
}

// Reemplazo de variables {k} en un template, sin ir a la base (para defaults).
function _renderVars(template, vars = {}) {
  let out = String(template == null ? '' : template);
  for (const [k, v] of Object.entries(vars)) {
    out = out.replace(new RegExp('\\{' + k + '\\}', 'g'), v == null ? '' : String(v));
  }
  return out;
}

// Arma el texto de la escalera de reembolsos VIGENTE, para la variable {escalera}
// de los mensajes automáticos (ej. /sys_welcome). Así la bienvenida NUNCA queda
// desactualizada cuando se cambian los rangos desde el panel (#118): se renderiza
// con la config real al momento de ENVIAR cada mensaje. Si las 2 escaleras
// (semanal/mensual) son iguales muestra una sola; si difieren, una por línea.
// (El reembolso DIARIO se eliminó el 2026-08-07 — quedan solo semanal y mensual.)
async function buildEscaleraText() {
  try {
    const tbp = await getRefundTiersByPeriod();
    const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('es-AR');
    const linea = (tiers) => tiers.map((t) => {
      const rango = t.max === null
        ? `más de ${money(t.min)}`
        : (t.min === 0 ? `hasta ${money(t.max)}` : `${money(t.min + 1)} a ${money(t.max)}`);
      return `${rango} → ${t.pct}%`;
    }).join(' · ');
    const key = (tiers) => JSON.stringify(tiers.map((t) => [t.pct, t.max]));
    const iguales = key(tbp.daily) === key(tbp.weekly) && key(tbp.weekly) === key(tbp.monthly);
    if (iguales) {
      return '• Reembolso DIARIO, SEMANAL (lun-mar) y MENSUAL (desde el día 7) según tu pérdida del período:\n' +
        tbp.weekly.map((t) => {
          const rango = t.max === null
            ? `más de ${money(t.min)}`
            : (t.min === 0 ? `hasta ${money(t.max)}` : `${money(t.min + 1)} a ${money(t.max)}`);
          return `   ${t.emoji} Si perdés ${rango} → te devolvemos el ${t.pct}%`;
        }).join('\n');
    }
    return '• Reembolsos según tu pérdida del período:\n' +
      `   📅 DIARIO (todos los días, sobre lo de ayer): ${linea(tbp.daily)}\n` +
      `   🗓️ SEMANAL (lun-mar): ${linea(tbp.weekly)}\n` +
      `   📆 MENSUAL (desde el día 7): ${linea(tbp.monthly)}`;
  } catch (e) {
    logger.warn(`[escalera] no se pudo armar el texto: ${e.message}`);
    return '• Reembolso DIARIO, SEMANAL y MENSUAL según tu pérdida del período';
  }
}

// Igual que renderSystemCommand pero a partir de un Command ya cargado (los flujos
// que ya hacían Command.findOne directo). Devuelve null si el comando existe pero su
// respuesta está vacía (desactivado a propósito); usa el fallback si no existe.
function resolveSysContent(cmd, fallback) {
  if (cmd) {
    if (!cmd.response || !String(cmd.response).trim()) return null;
    return cmd.response;
  }
  return fallback;
}

// Tras una carga (manual o automática), ofrece al cliente el "100% de recuperación"
// para que entre a la Comunidad. NO se envía si el cliente ya está etiquetado
// 'comunidad' (ya está) o 'no comunidad' (ya dijo que no quiere) — anti-spam.
// Texto editable desde COMANDOS (/sys_recover_100); si se vacía, no se envía.
async function maybeSendRecoveryMessage(user) {
  try {
    if (!user) return;
    const tags = Array.isArray(user.tags) ? user.tags.map(t => String(t).toLowerCase()) : [];
    if (tags.includes('comunidad') || tags.includes('no comunidad')) return;
    const content = await renderSystemCommand(
      '/sys_recover_100',
      '' /* #599: sin texto por defecto */,
      {}
    );
    if (!content) return;
    const msg = await Message.create({
      id: uuidv4(), senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin',
      receiverId: user.id, receiverRole: 'user', content, type: 'system', timestamp: new Date(), read: false
    });
    const data = { id: msg.id, senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin', receiverId: user.id, receiverRole: 'user', content, timestamp: new Date(), type: 'system' };
    io.to(`user_${user.id}`).emit('new_message', data);
    io.to(`chat_${user.id}`).emit('new_message', data);
    notifyAdmins('new_message', { message: data, userId: user.id, username: user.username });
  } catch (e) {
    logger.warn(`[recovery-msg] ${e.message}`);
  }
}

// ============================================
// #283 (owner 2026-10-17): CARGA GRATIS por instalar la app — retención en la PRIMERA carga
// ============================================
// Al acreditarse la PRIMERA carga de un cliente que NO tiene la app instalada se le ofrece una
// carga sin cargo (pct% de esa primera carga, con tope) a cambio de instalar la app. Dos caminos:
//   · "Instalar ahora y reclamar" → instala, abre la app y reclama al instante.
//   · "Ahora quiero jugar" → queda PENDIENTE: botón grande abajo en la app hasta que instale y reclame.
// Se acredita SOLO al reclamar desde la app instalada (token FCM standalone, igual que la ruleta),
// como regalo (bono 0) vía creditGift, reference `vip-igift-<userId>` (una vez en la vida).
// Config['installGift'] = { enabled, pct, capArs, days } (panel → COMANDOS → Bonos automáticos).
// #974 (owner 2026-10-24): el extra por instalar es un MONTO FIJO (fixedArs, $5.000) y no un % de la carga: al que carga poco le da más (es el que
// más necesita el empujón) y al que carga mucho deja de regalarle una fortuna. fixedArs = 0 ⇒ vuelve al % con tope. Nunca más que la carga.
const INSTALL_GIFT_DEFAULT = { enabled: true, pct: 50, capArs: 20000, days: 7, fixedArs: 5000 }; // #290: 50% EXTRA (owner) · #974 fijo
const INSTALL_GIFT_OFFER_DEFAULT = "🎁 ¡{username}, instalando la app te regalamos *${monto} EXTRA en fichas*!\n\nEs un regalo por tu primera carga de ${carga}. Tenés {dias} días.\n\n👉 Podés instalarla ahora y cargarlo al instante, o seguir jugando y cargarlo después: te queda un botón abajo en la app. No perdés el ritmo.";
const INSTALL_GIFT_CREDITED_DEFAULT = "🎁 ¡Listo {username}! Te cargamos *${monto} extra* en {plataforma} por instalar la app. ✅\n\n¡A jugar! 🎰";
async function getInstallGiftConfig() {
  let raw = null;
  try { raw = await getConfig('installGift', null); } catch (_) { raw = null; }
  const r = raw && typeof raw === 'object' ? raw : {};
  const num = (v, d, min, max) => { const n = Number(v); return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : d; };
  return {
    enabled: r.enabled == null ? INSTALL_GIFT_DEFAULT.enabled : r.enabled === true,
    pct: Math.round(num(r.pct, INSTALL_GIFT_DEFAULT.pct, 0, 500)),
    capArs: Math.round(num(r.capArs, INSTALL_GIFT_DEFAULT.capArs, 0, 10000000)),
    days: Math.round(num(r.days, INSTALL_GIFT_DEFAULT.days, 1, 365)),
    fixedArs: Math.round(num(r.fixedArs, INSTALL_GIFT_DEFAULT.fixedArs, 0, 10000000)) // #974
  };
}
function installGiftAmount(baseAmount, cfg) {
  const b = Math.max(0, Number(baseAmount) || 0);
  if (cfg.fixedArs > 0) return Math.round(Math.min(b, cfg.fixedArs)); // #974: monto fijo (nunca más que la carga)
  const capped = cfg.capArs > 0 ? Math.min(b, cfg.capArs) : b;
  return Math.round(capped * cfg.pct / 100);
}
// Cómo se describe el extra al cliente: "$5.000" (fijo) o "50%" (porcentaje).
function installGiftLabel(cfg) { return cfg.fixedArs > 0 ? '$' + Math.round(cfg.fixedArs).toLocaleString('es-AR') : cfg.pct + '%'; }
// #974 (owner): "sin bono de bienvenida si el teléfono o el dispositivo ya se usó en otra cuenta" (la cuenta no se bloquea: sólo el regalo).
// Devuelve el motivo (texto) o null. Mira teléfono normalizado (10 dígitos), ID del celular (deviceIds) y tokens de push compartidos.
async function _welcomeAbuseOf(userIn) {
  try {
    const u = await User.findOne({ id: userIn.id }).select('id username phone deviceIds fcmToken fcmTokens noWelcomeGifts').lean(); if (!u) return null;
    if (u.noWelcomeGifts === true) return 'se registró desde la página sin invitación (registro abierto sin regalos de bienvenida)'; // #975
    const or = []; const tel = String(u.phone || '').replace(/\D/g, '').slice(-10);
    if (Array.isArray(u.deviceIds) && u.deviceIds.length) or.push({ deviceIds: { $in: u.deviceIds } });
    const toks = [].concat(u.fcmToken ? [u.fcmToken] : [], (u.fcmTokens || []).map((t) => t && t.token).filter(Boolean));
    if (toks.length) or.push({ $or: [{ fcmToken: { $in: toks } }, { 'fcmTokens.token': { $in: toks } }] });
    if (tel.length === 10) or.push({ phone: { $regex: tel.slice(-8) } });
    if (!or.length) return null;
    const others = await User.find({ id: { $ne: u.id }, role: 'user', $or: or }).select('username phone deviceIds fcmToken fcmTokens').limit(20).lean();
    const hits = [];
    for (const o of others) {
      const otel = String(o.phone || '').replace(/\D/g, '').slice(-10);
      if (tel.length === 10 && otel === tel) hits.push('mismo teléfono que ' + o.username);
      else if (Array.isArray(u.deviceIds) && u.deviceIds.length && (o.deviceIds || []).some((d) => u.deviceIds.includes(d))) hits.push('mismo celular que ' + o.username);
      else if (toks.length && (toks.includes(o.fcmToken) || (o.fcmTokens || []).some((t) => t && toks.includes(t.token)))) hits.push('mismas notificaciones que ' + o.username);
    }
    return hits.length ? hits.slice(0, 3).join(', ') : null;
  } catch (e) { logger.warn('[welcome-abuse] ' + e.message); return null; }
}
function _installGiftExpired(ig) { return !!(ig && ig.expiresAt && new Date(ig.expiresAt).getTime() < Date.now()); }
// Devuelve true si se OFRECIÓ (el que llama puede omitir el cartel genérico "instalá la app").
async function maybeOfferInstallGift(userIn, { amount, platform = null, source = '' } = {}) {
  try {
    if (!userIn || !userIn.id) return false;
    const cfg = await getInstallGiftConfig();
    if (!cfg.enabled || !(cfg.pct > 0)) return false;
    const user = await User.findOne({ id: userIn.id }).lean();
    if (!user) return false;
    const st = user.installGift && user.installGift.status;
    if (st && st !== 'none') return false;            // ya ofrecida / reclamada / vencida
    const _abuse = await _welcomeAbuseOf(user); if (_abuse) { logger.warn(`[install-gift] ${user.username}: sin extra por instalar — ${_abuse}`); _emitAdminOnlyChatNote(user.id, user.username, `⚠️ SIN EXTRA POR INSTALAR LA APP: ${_abuse}. Si es un cliente legítimo, cargáselo a mano desde Bonificación.`).catch(() => {}); return false; } // #974
    if (_rouletteHasAppInstalled(user)) return false; // ya tiene la app: no hay nada que incentivar
    // Sólo la PRIMERA carga real (la recién acreditada ya está en Transaction).
    const n = await Transaction.countDocuments({
      $or: [{ userId: user.id }, { username: user.username }],
      type: 'deposit',
      'metadata.source': { $nin: ['install_bonus', 'welcome_gift', 'payout_refund'] }
    });
    if (n > 1) return false;
    const gift = installGiftAmount(amount, cfg);
    if (!(gift > 0)) return false;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + cfg.days * 86400000);
    const base = Math.round(Number(amount) || 0);
    const reserved = await User.findOneAndUpdate(
      { id: user.id, $or: [{ 'installGift.status': 'none' }, { 'installGift.status': { $exists: false } }] },
      { $set: { installGift: { status: 'offered', amount: gift, baseAmount: base, pct: cfg.fixedArs > 0 ? null : cfg.pct, offeredAt: now, expiresAt, deferredAt: null, claimedAt: null, claimTxId: null, platform: platforms.normalizeId(platform) || null, source: String(source || '').slice(0, 30), lastError: null } } }
    );
    if (!reserved) return false;
    const vars = { username: user.username, monto: gift.toLocaleString('es-AR'), pct: cfg.fixedArs > 0 ? '' : cfg.pct, dias: cfg.days, carga: base.toLocaleString('es-AR') };
    const text = (await renderSystemCommand('/sys_install_gift_offer', INSTALL_GIFT_OFFER_DEFAULT, vars)) || _renderVars('🎁 Instalando la app te regalamos ${monto} extra en fichas.', vars);
    const md = { kind: 'install_gift_offer', amount: gift, baseAmount: base, pct: cfg.fixedArs > 0 ? null : cfg.pct, expiresAt: expiresAt.toISOString() };
    await _sendUserSystemMessage(user, text, { metadata: md, push: { title: `🎁 $${vars.monto} extra por instalar la app`, body: `Instalá la app y cargá $${vars.monto} extra en fichas.` } });
    await _emitAdminOnlyChatNote(user.id, user.username,
      `🎁 ${cfg.pct}% EXTRA por instalar la app OFRECIDO: $${vars.monto} (${cfg.pct}% de su primera carga de $${vars.carga}; tope $${cfg.capArs.toLocaleString('es-AR')}). Vence en ${cfg.days} días. Se acredita SOLA cuando reclama desde la app instalada: no hay que hacer nada.`
    ).catch(() => {});
    logger.info(`[install-gift] ofrecida user=${user.username} gift=$${gift} base=$${base} via=${source || '?'}`);
    return true;
  } catch (e) {
    logger.warn(`[install-gift] offer ${userIn && userIn.username}: ${e.message}`);
    return false;
  }
}

// Agregar usuario externo
async function addExternalUser(userData) {
  try {
    const { v4: uuidv4 } = require('uuid');
    await ExternalUser.findOneAndUpdate(
      { username: userData.username },
      {
        username: userData.username,
        phone: userData.phone || null,
        whatsapp: userData.whatsapp || null,
        lastSeen: new Date(),
        $inc: { messageCount: 1 },
        $setOnInsert: { 
          id: uuidv4(),
          firstSeen: new Date() 
        }
      },
      { upsert: true, new: true }
    );
  } catch (error) {
    console.error('Error agregando usuario externo:', error);
  }
}

// Registrar actividad de usuario (para fueguito)
async function recordUserActivity(userId, type, amount) {
  try {
    const today = new Date().toDateString();
    
    await UserActivity.findOneAndUpdate(
      { userId, date: today },
      {
        $inc: { [type === 'deposit' ? 'deposits' : 'withdrawals']: amount },
        lastActivity: new Date()
      },
      { upsert: true, new: true }
    );
  } catch (error) {
    console.error('Error registrando actividad:', error);
  }
}

// Verificar si tiene actividad hoy
async function hasActivityToday(userId) {
  try {
    const today = new Date().toDateString();
    const activity = await UserActivity.findOne({ userId, date: today });
    
    if (!activity) return false;
    return (activity.deposits > 0 || activity.withdrawals > 0);
  } catch (error) {
    console.error('Error verificando actividad:', error);
    return false;
  }
}

// Funciones para fecha Argentina
function getArgentinaDateString(date = new Date()) {
  const argentinaTime = new Date(date.toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
  return argentinaTime.toDateString();
}

function getArgentinaYesterday() {
  const now = new Date();
  const argentinaNow = new Date(now.toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
  argentinaNow.setDate(argentinaNow.getDate() - 1);
  return argentinaNow.toDateString();
}

// ============================================
// COMPROBANTES — detección de reutilización con IA (anti-estafa)
// ============================================
// Normaliza una huella de comprobante para comparar duplicados (sólo alfanumérico).
function _normComprobanteKey(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

// Crea y emite un mensaje de sistema adminOnly (sólo lo ven los admins en el
// chat; el cliente NO lo recibe). Reusa el mismo patrón que la alerta de bonus.
async function _emitAdminOnlyChatNote(userId, username, content) {
  try {
    const msg = await Message.create({
      id: uuidv4(),
      senderId: 'admin',
      senderUsername: 'Sistema',
      senderRole: 'admin',
      receiverId: userId,
      receiverRole: 'user',
      content,
      type: 'system',
      adminOnly: true,
      timestamp: new Date(),
      read: false
    });
    const data = {
      id: msg.id, senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin',
      receiverId: userId, receiverRole: 'user', content, timestamp: new Date(),
      type: 'system', adminOnly: true
    };
    // Sólo a la sala del chat (admins viéndolo) + a todos los admins. NO a user_<id>.
    io.to(`chat_${userId}`).emit('new_message', data);
    notifyAdmins('new_message', { message: data, userId, username });
  } catch (e) {
    logger.warn(`[comprobante] no se pudo emitir aviso admin: ${e.message}`);
  }
}

// Mensaje de SISTEMA al cliente (lo ve el cliente Y los admins en el chat), con
// `metadata` opcional que la PWA usa para renderizar botones (ej. la pregunta
// "¿dónde querés jugar?" de multi-plataforma: metadata.kind='platform_choice').
// Devuelve el Message creado (o null si falló). Si `push` viene ({title, body}),
// manda FCM sólo si el cliente está offline (sendPushIfOffline).
async function _sendUserSystemMessage(user, content, { metadata = null, senderUsername = 'Sistema', push = null } = {}) {
  try {
    const msg = await Message.create({
      id: uuidv4(), senderId: 'admin', senderUsername, senderRole: 'admin',
      receiverId: user.id, receiverRole: 'user', content, type: 'system',
      metadata: metadata || null, timestamp: new Date(), read: false
    });
    const data = {
      id: msg.id, senderId: 'admin', senderUsername, senderRole: 'admin',
      receiverId: user.id, receiverRole: 'user', content, timestamp: msg.timestamp,
      type: 'system', metadata: metadata || null
    };
    io.to(`user_${user.id}`).emit('new_message', data);
    io.to(`chat_${user.id}`).emit('new_message', data);
    notifyAdmins('new_message', { message: data, userId: user.id, username: user.username });
    if (push && push.title) {
      sendPushIfOffline(user, push.title, push.body || '', push.data || {}).catch((e) => {
        logger.warn(`[FCM] sendPushIfOffline (${push.title}) falló para ${user.username}: ${e.message}`);
      });
    }
    return msg;
  } catch (e) {
    logger.warn(`[sys-msg] no se pudo enviar a ${user && user.username}: ${e.message}`);
    return null;
  }
}

// ============================================================
// #376 (owner 2026-10-18): CARGAS PENDIENTES — red de seguridad de la carga automática.
// Cada comprobante válido entra en una COLA de revisión (Comprobante.reviewStatus='pending'):
//   · el cliente recibe "recibimos tu comprobante, se acredita sola" (/sys_receipt_received);
//   · si la auto-carga hgcash lo acredita → se cierra solo (reviewStatus='confirmed', 'auto');
//   · si pasan N minutos sin acreditarse (Config['depositReview'].escalateMinutes, default 8) o el banco automático
//     está apagado / en sombra → ESCALA: el cliente ve "carga pendiente, un agente la está revisando"
//     (/sys_deposit_pending_review) y el panel la muestra en "⏳ Cargas pendientes" para CONFIRMAR (= la misma carga
//     manual de siempre; el cliente la ve como automática) o RECHAZAR (/sys_deposit_rejected).
//   · un comprobante DUPLICADO (misma imagen o mismo N° de operación) NO entra en la cola: el cliente recibe
//     /sys_receipt_duplicate ("ese comprobante ya fue usado").
// Los retiros ya tenían su stand-by (PendingPayout.pending_review → sección Pagos → pagar / rechazar).
// ============================================================
// #808 (owner): comprobante que NO se pudo leer bien ⇒ pedirle al cliente que lo reenvíe con todos los datos visibles (editable en COMANDOS).
// #825 (owner 2026-10-22): "cuando mandan el comprobante sin estar completo, decirles que se necesita que se vean los datos: titular, CUIT,
// horario y monto, todo lo que usás para leerlo; si sigue fallando, entra a Soporte automáticamente del lado interno para hacerlo manual".
// 1er comprobante ilegible/incompleto ⇒ /sys_receipt_unreadable con la lista de datos. 2do en 60 min ⇒ NO se le vuelve a pedir: pasa solo a
// un agente (/sys_receipt_to_agent al cliente; el comprobante entra a Cargas pendientes ya escalado; el chat se abre en Abiertos con nota).
const RECEIPT_UNREADABLE_DEFAULT = '⚠️ No pudimos leer tu comprobante. Mandá la captura ENTERA, que se vean titular, CUIT, fecha y hora, monto y N° de operación.';
const RECEIPT_UNREADABLE_OLD_808 = '⚠️ No pudimos leer bien tu comprobante. Reenvialo de forma correcta, con TODOS los datos visibles: monto, fecha y hora, nombre de quien envía, CBU/alias de destino y N° de operación.\n\n📸 Si los datos no se ven, el pago será rechazado.';
const RECEIPT_TO_AGENT_DEFAULT = '🙋 No pudimos leer tu comprobante de forma automática, así que ya se lo pasamos a un agente para que lo revise a mano. No hace falta que hagas nada: te avisamos acá apenas se acredite.';
async function _askReceiptResend(userId, username, why, compId) {
  try {
    const since60 = new Date(Date.now() - 60 * 60 * 1000);
    // Ya escalado en la última hora ⇒ no insistir (el agente lo tiene).
    const esc = await Message.findOne({ receiverId: userId, type: 'system', 'metadata.kind': 'receipt_to_agent', timestamp: { $gte: since60 } }).select('_id').lean();
    if (esc) { await _receiptQueueForAgent(userId, username, compId, why, false); return; }
    const prev = await Message.findOne({ receiverId: userId, type: 'system', 'metadata.kind': 'receipt_unreadable', timestamp: { $gte: since60 } }).select('timestamp').lean();
    if (prev) {
      // SEGUNDA vez que falla ⇒ a un agente, automático.
      if (Date.now() - new Date(prev.timestamp).getTime() < 20 * 1000) return; // misma tanda de imágenes: no cuenta como reintento
      const txt = await renderSystemCommand('/sys_receipt_to_agent', RECEIPT_TO_AGENT_DEFAULT, {});
      if (txt) await _sendUserSystemMessage({ id: userId, username }, txt, { metadata: { kind: 'receipt_to_agent', why: String(why || '').slice(0, 60), channel: 'support' } });
      await _receiptQueueForAgent(userId, username, compId, why, true);
      return;
    }
    const txt = await renderSystemCommand('/sys_receipt_unreadable', RECEIPT_UNREADABLE_DEFAULT, {});
    if (txt) await _sendUserSystemMessage({ id: userId, username }, txt, { metadata: { kind: 'receipt_unreadable', why: String(why || '').slice(0, 60), channel: 'support' }, push: { title: '📸 Reenviá tu comprobante', body: 'Necesitamos ver titular, CUIT, fecha y hora, monto y N° de operación.' } });
    if (why !== 'not_comprobante') _chatAutoCloseIfHandled(userId, 'comprobante ilegible: se pidió reenviar').catch(() => {}); // #895
  } catch (e) { logger.warn(`[comprobante] pedido de reenvío: ${e.message}`); }
}
// #895 (owner 2026-10-23): "todo lo que es duplicado y problema de la gente que hace mal la cosa y que se informa en el chat, que quede
// CERRADO; si la gente abre Soporte, que sí se abra". El comprobante viaja como imagen del chat y reabre el chat; cuando el SISTEMA ya lo
// resolvió (carga acreditada sola, comprobante repetido, ilegible, menor al mínimo, a la espera del banco) se vuelve a cerrar. NO se cierra si
// el cliente escribió TEXTO que nadie respondió (eso es abrir Soporte), ni si el chat está en Pagos (sólo pasa de 'open' a 'closed').
async function _chatAutoCloseIfHandled(userId, why) {
  try {
    if (!userId) return;
    const cs = await ChatStatus.findOne({ userId }).select('status').lean();
    if (!cs || cs.status !== 'open') return;
    const lastText = await Message.findOne({ senderId: userId, type: 'text', timestamp: { $gte: new Date(Date.now() - 24 * 3600 * 1000) } }).sort({ timestamp: -1 }).select('timestamp').lean();
    if (lastText) {
      const lastAgent = await Message.findOne({ receiverId: userId, senderId: { $ne: userId }, type: { $in: ['text', 'image', 'file'] }, adminOnly: { $ne: true }, timestamp: { $gte: lastText.timestamp } }).select('_id').lean();
      if (!lastAgent) return; // escribió y nadie le respondió ⇒ es Soporte: queda abierto
    }
    const r = await ChatStatus.updateOne({ userId, status: 'open' }, { $set: { status: 'closed', closedAt: new Date(), closedBy: 'auto', assignedTo: null } });
    if (r && r.modifiedCount) {
      try { await delayClockResolve(userId, { responded: true, agentId: 'system', agentUsername: 'automático', via: 'auto' }); } catch (_) {}
      try { notifyAdmins('chat_closed', { userId, by: 'sistema', adminId: 'system' }); } catch (_) {}
      logger.info(`[chat] cerrado solo (${why}) user=${userId}`);
    }
  } catch (e) { logger.warn(`[chat] auto-cierre: ${e.message}`); }
}
// Deja el comprobante en Cargas pendientes YA escalado (sin otro mensaje al cliente) y abre el chat en Abiertos con una nota interna.
async function _receiptQueueForAgent(userId, username, compId, why, first) {
  try {
    // El comprobante del flujo "incompleto" se guarda unos instantes DESPUÉS de esta llamada ⇒ esperar un poco.
    await new Promise((r) => setTimeout(r, 4000));
    let c = compId ? await Comprobante.findOne({ id: compId }).lean() : null;
    if (!c) c = await Comprobante.findOne({ userId, createdAt: { $gte: new Date(Date.now() - 10 * 60 * 1000) }, autoCharged: { $ne: true } }).sort({ createdAt: -1 }).lean();
    if (c && c.reviewStatus !== 'confirmed' && c.reviewStatus !== 'rejected') {
      await Comprobante.updateOne({ id: c.id }, { $set: { reviewStatus: 'pending', reviewQueuedAt: c.reviewQueuedAt || new Date(), reviewEscalatedAt: new Date(), reviewEscalateReason: 'comprobante ilegible / incompleto (2 intentos)' } });
      _emitDepositReviewUpdate(userId, { action: 'escalated', id: c.id, username, amount: c.amount || 0 });
    }
    if (!first) return;
    // #895: el chat NO se abre (lo resuelve el agente desde Cargas pendientes); queda la nota interna para cuando lo mire.
    await _emitAdminOnlyChatNote(userId, username, `📸 COMPROBANTE ILEGIBLE 2 VECES (${String(why || '').slice(0, 40)}) — pasó solo a manual. Revisalo en "Cargas pendientes": si se ve, confirmalo con el monto; si no, pedile acá los datos (titular, CUIT, fecha y hora, monto, N° de operación).`);
    _chatAutoCloseIfHandled(userId, 'comprobante ilegible ⇒ Cargas pendientes').catch(() => {});
    logger.info(`[comprobante] ${username}: 2 comprobantes ilegibles ⇒ a un agente`);
  } catch (e) { logger.warn(`[comprobante] pase a agente: ${e.message}`); }
}
const RECEIPT_RECEIVED_DEFAULT = '✅ Recibimos tu comprobante{amount}. En breve tu carga será realizada: te avisamos acá apenas se acredite.'; // #811
const RECEIPT_DUPLICATE_DEFAULT = '⚠️ Ese comprobante ya fue usado{amount}. Cada transferencia se acredita UNA sola vez. Si creés que es un error, contanos acá en Soporte y lo revisamos.';
const DEPOSIT_PENDING_REVIEW_DEFAULT = '⏳ Tu carga{amount} sigue pendiente: un agente la está verificando ahora mismo. No hace falta que hagas nada, te avisamos acá en cuanto se acredite.';
const DEPOSIT_REJECTED_DEFAULT = '❌ No pudimos acreditar tu carga{amount}: {motivo}. Si tenés dudas, escribinos acá en Soporte.';
const DEPOSIT_REJECT_REASONS = { no_llego: 'la transferencia no entró en nuestra cuenta', duplicado: 'ese comprobante ya había sido acreditado', ilegible: 'el comprobante no se lee completo (mandalo de nuevo, entero)', monto: 'el monto no coincide con lo que entró', otro: 'no pudimos validarla' };
async function getDepositReviewConfig() {
  const raw = await getConfig('depositReview', null);
  const m = Number(raw && raw.escalateMinutes);
  return { escalateMinutes: Number.isFinite(m) && m >= 0 && m <= 240 ? m : 8 };
}
function _amtStr(a) { const n = Number(a); return Number.isFinite(n) && n > 0 ? ' de $' + n.toLocaleString('es-AR') : ''; }
function _emitDepositReviewUpdate(userId, extra) {
  try { io.to(`user_${userId}`).emit('deposit_review_update', extra || {}); } catch (_) {}
  try { notifyAdmins('deposit_review', Object.assign({ userId }, extra || {})); } catch (_) {}
}
// #820 RECUPERACIÓN AUTOMÁTICA de cargas (corre en el tick de cada minuto):
//  1) lo que quedó 'claiming' más de 10 min (reinicio de la instancia a mitad de la carga, excepción) vuelve a 'pending'. Es seguro: el
//     reintento usa la misma reference `vip-hg-*` (1girox responde duplicate si ya se había acreditado) y el candado HgcashCharge.
//  2) cada 3 min, los comprobantes pendientes de la última ventana (`windowMinutes`) vuelven a buscar su transferencia: cubre el aviso
//     del banco que llega tarde, el reintento tras una falla de la plataforma y el caso "comprobante antes que el banco" fuera de la
//     ventana corta. Si ya estaba escalado y la transferencia aparece, se acredita sola y la tarjeta de Cargas pendientes se cierra.
let _hgcashRecoveryAt = 0;
async function _hgcashRecoveryPass() {
  try {
    const stale = new Date(Date.now() - 10 * 60 * 1000);
    const m = await BankMovement.updateMany({ matchStatus: 'claiming', updatedAt: { $lt: stale } }, { $set: { matchStatus: 'pending' } });
    const c = await Comprobante.updateMany({ bankMatchStatus: 'claiming', autoCharged: { $ne: true }, updatedAt: { $lt: stale } }, { $set: { bankMatchStatus: 'pending' } });
    const nm = m.modifiedCount || m.nModified || 0, nc = c.modifiedCount || c.nModified || 0;
    if (nm || nc) logger.warn(`[hgcash] recuperación: ${nm} movimiento(s) y ${nc} comprobante(s) trabados en 'claiming' vuelven a pendiente`);
    if (Date.now() - _hgcashRecoveryAt < 3 * 60 * 1000) return;
    _hgcashRecoveryAt = Date.now();
    const cfg = await getHgcashConfig();
    if (!cfg.enabled) return;
    const since = new Date(Date.now() - (cfg.windowMinutes || 60) * 60 * 1000);
    const pend = await Comprobante.find({ isComprobante: true, autoCharged: { $ne: true }, status: { $ne: 'duplicate' }, reviewStatus: 'pending',
      bankMatchStatus: { $in: ['none', 'pending'] }, amount: { $gt: 0 }, createdAt: { $gte: since, $lte: new Date(Date.now() - 60 * 1000) } }).sort({ createdAt: 1 }).limit(30).lean();
    for (const comp of pend) await hgcashMatchFromComprobante(comp);
  } catch (e) { logger.warn(`[hgcash] recuperación: ${e.message}`); }
}
// #908 (owner 2026-10-24): "un usuario mandó 4 veces el mismo comprobante y aparecieron 3 fichas en Cargas pendientes". Dos comprobantes
// PENDIENTES del mismo cliente son "el mismo envío" si comparten la imagen (imageHash), la huella de datos (dedupeKey) o el monto sin un
// N° de operación que los distinga (los dos sin número, o el mismo). Al resolver uno (carga automática, confirmación o rechazo) los demás
// se cierran solos como 'duplicate' sin avisarle al cliente otra vez. Si de verdad son transferencias distintas, el agente usa "Es otra
// carga distinta" en la ficha (cada envío conserva su id y se confirma aparte).
function _sameReceiptOr(c) {
  const or = [];
  if (c.imageHash) or.push({ imageHash: c.imageHash });
  if (c.dedupeKey) or.push({ dedupeKey: c.dedupeKey });
  if (Number(c.amount) > 0) or.push(Object.assign({ amount: c.amount }, c.operationNumber ? { $or: [{ operationNumber: null }, { operationNumber: c.operationNumber }] } : {}));
  else or.push({ amount: null });
  return or;
}
function _sameReceipt(a, b) {
  if (!a || !b || String(a.userId) !== String(b.userId)) return false;
  if (a.imageHash && a.imageHash === b.imageHash) return true;
  if (a.dedupeKey && a.dedupeKey === b.dedupeKey) return true;
  const aa = Number(a.amount) || 0, ba = Number(b.amount) || 0;
  if (!aa && !ba) return true; // los dos sin monto legible: el mismo comprobante borroso mandado otra vez
  if (!aa || !ba || !_amountsEqual(aa, ba)) return false;
  return !(a.operationNumber && b.operationNumber && String(a.operationNumber).trim() !== String(b.operationNumber).trim());
}
async function _depositReviewCloseRepeats(c, by, how) {
  try {
    if (!c || !c.userId) return 0;
    const t = new Date(c.createdAt || Date.now()).getTime();
    const r = await Comprobante.updateMany({ userId: c.userId, id: { $ne: c.id }, reviewStatus: 'pending', autoCharged: { $ne: true }, bankMatchStatus: { $nin: ['claiming', 'awaiting_platform'] },
      createdAt: { $gte: new Date(t - 24 * 3600 * 1000), $lte: new Date(t + 24 * 3600 * 1000) }, $or: _sameReceiptOr(c) },
      { $set: { reviewStatus: 'rejected', reviewResolution: 'duplicate', reviewedBy: by || 'auto', reviewedAt: new Date(), reviewNote: `Repetido: el mismo comprobante ya se ${how || 'resolvió'} (${c.id})`.slice(0, 200) } });
    const n = r.modifiedCount || r.nModified || 0;
    if (n) { logger.info(`[deposit-review] ${n} envío(s) repetido(s) de ${c.username || c.userId} cerrados (${how})`); _emitDepositReviewUpdate(c.userId, { action: 'repeats_closed', id: c.id, count: n }); }
    return n;
  } catch (e) { logger.warn(`[deposit-review] cerrar repetidos: ${e.message}`); return 0; }
}
// Escala un comprobante pendiente: aviso al cliente + nota interna + panel.
async function _depositReviewEscalate(c, why) {
  try {
    const r = await Comprobante.findOneAndUpdate(
      { id: c.id, reviewStatus: 'pending', reviewEscalatedAt: null },
      { $set: { reviewEscalatedAt: new Date(), reviewEscalateReason: String(why || '').slice(0, 80) } }, { new: true }).lean();
    if (!r) return false;
    const txt = await renderSystemCommand('/sys_deposit_pending_review', DEPOSIT_PENDING_REVIEW_DEFAULT, { amount: _amtStr(c.amount) });
    if (txt) await _sendUserSystemMessage({ id: c.userId, username: c.username }, txt, { metadata: { kind: 'deposit_pending', comprobanteId: c.id, amount: c.amount || 0, escalated: true } });
    await _emitAdminOnlyChatNote(c.userId, c.username, `⏳ CARGA PENDIENTE${_amtStr(c.amount)} — ${why || 'sin acreditación automática'}. Revisala en "Cargas pendientes": confirmar (carga) o rechazar.`);
    _emitDepositReviewUpdate(c.userId, { action: 'escalated', id: c.id, username: c.username, amount: c.amount });
    logger.info(`[deposit-review] escalado ${c.id} user=${c.username} $${c.amount} (${why})`);
    return true;
  } catch (e) { logger.warn(`[deposit-review] escalar falló: ${e.message}`); return false; }
}
// Cron (cada minuto): escala lo que lleva demasiado sin acreditarse y cierra lo que ya se cargó por otro camino.
async function _depositReviewTick() {
  try {
    const cfg = await getDepositReviewConfig();
    await Comprobante.updateMany({ reviewStatus: 'pending', autoCharged: true },
      { $set: { reviewStatus: 'confirmed', reviewResolution: 'auto', reviewedBy: 'auto', reviewedAt: new Date() } });
    const since = new Date(Date.now() - 72 * 3600 * 1000);
    const limit = new Date(Date.now() - cfg.escalateMinutes * 60 * 1000);
    const due = await Comprobante.find({ reviewStatus: 'pending', reviewEscalatedAt: null, autoCharged: { $ne: true }, bankMatchStatus: { $nin: ['claiming', 'awaiting_platform'] }, createdAt: { $gte: since, $lte: limit } }).limit(50).lean();
    for (const c of due) await _depositReviewEscalate(c, `sin acreditación automática en ${cfg.escalateMinutes} min`);
    await _hgcashRecoveryPass();
  } catch (e) { logger.warn(`[deposit-review] tick: ${e.message}`); }
}
// Una carga manual del agente (misma persona, mismo monto) cierra el comprobante pendiente más viejo que coincide.
async function _depositReviewConsume(userId, amount, by) {
  try {
    const cands = await Comprobante.find({ userId, reviewStatus: 'pending', autoCharged: { $ne: true } }).sort({ createdAt: 1 }).limit(10).lean();
    // #820: SÓLO el del mismo monto (antes, si quedaba uno solo, lo cerraba aunque fuera de otro monto ⇒ una carga real desaparecía de la cola).
    const c = cands.find((x) => _amountsEqual(x.amount, amount));
    if (!c) return false;
    const r = await Comprobante.findOneAndUpdate({ id: c.id, reviewStatus: 'pending' },
      { $set: { reviewStatus: 'confirmed', reviewResolution: 'manual', reviewedBy: by || 'agente', reviewedAt: new Date(), bankMatchStatus: 'manual_charged', autoCharged: true } }, { new: true }).lean();
    if (r) _emitDepositReviewUpdate(userId, { action: 'confirmed', id: c.id });
    return !!r;
  } catch (_) { return false; }
}

// Analiza una imagen enviada por un cliente: detecta si es comprobante, lo
// registra (colección Comprobante) y avisa SÓLO a los admins si es duplicado o
// no. Pensado para correr fire-and-forget: NUNCA frena la entrega del mensaje.
async function analyzeComprobanteFromMessage({ userId, username, content, messageId }) {
  try {
    if (!comprobanteAi.isEnabled()) {
      // #614 (owner): SIN IA (sin ANTHROPIC_API_KEY, p. ej. en Render) el comprobante no se perdía pero el cliente no recibía nada y
      // el panel no lo veía en la cola. Ahora igual entra a la cola de Cargas pendientes (sin datos leídos) y el cliente recibe el
      // acuse "recibimos tu comprobante".
      try {
        const base = { id: uuidv4(), userId, username, messageId, isComprobante: true, aiConfidence: 0, amount: null, status: 'no_key', model: 'sin-ia', createdAt: new Date() };
        await Comprobante.create({ ...base, reviewStatus: 'pending', reviewQueuedAt: new Date() });
        await _emitAdminOnlyChatNote(userId, username, '🧾 Comprobante recibido (sin lectura automática: la IA de comprobantes no está configurada en este entorno). Verificalo a mano en Cargas pendientes.');
        const ackTxt = await renderSystemCommand('/sys_receipt_received', RECEIPT_RECEIVED_DEFAULT, { amount: '' });
        if (ackTxt) await _sendUserSystemMessage({ id: userId, username }, ackTxt, { metadata: { kind: 'deposit_pending', comprobanteId: base.id, amount: 0 } });
        _chatAutoCloseIfHandled(userId, 'comprobante recibido (sin IA)').catch(() => {}); // #895
        _emitDepositReviewUpdate(userId, { action: 'queued', id: base.id, username, amount: 0 });
      } catch (e) { logger.warn(`[comprobante] sin IA: ${e.message}`); }
      return;
    }
    const result = await comprobanteAi.analyzeComprobante(content);

    // La IA no pudo analizar (error técnico): registrar y salir en silencio.
    if (!result.ok) {
      const _cidE = uuidv4();
      try {
        await Comprobante.create({
          id: _cidE, userId, username, messageId,
          isComprobante: false, status: 'error',
          errorReason: String(result.error || '').slice(0, 300),
          rawText: result.rawText || null, model: comprobanteAi.getModel(), createdAt: new Date()
        });
      } catch (_) {}
      _askReceiptResend(userId, username, 'error', _cidE); // #808 · #825
      return;
    }

    // No es comprobante (captura de error, foto cualquiera): registrar liviano, sin avisar.
    if (!result.isComprobante) {
      const _cidN = uuidv4();
      try {
        await Comprobante.create({
          id: _cidN, userId, username, messageId,
          isComprobante: false, aiConfidence: result.confidence || 0,
          status: 'not_comprobante', rawText: result.rawText || null,
          model: result.model, createdAt: new Date()
        });
      } catch (_) {}
      _askReceiptResend(userId, username, 'not_comprobante', _cidN); // #808: si era un comprobante, que lo reenvíe bien · #825
      return;
    }

    // Huella de la IMAGEN (SHA-256). Detecta re-envíos de la misma imagen al 100%,
    // sin depender de la lectura OCR (que puede variar entre envíos). Sólo para
    // imágenes base64 (data:) — capturas; para URLs https no hay bytes a mano.
    let imageHash = null;
    try {
      if (typeof content === 'string' && content.startsWith('data:')) {
        const m = content.match(/;base64,(.*)$/s);
        if (m) imageHash = crypto.createHash('sha256').update(m[1]).digest('hex');
      }
    } catch (_) {}

    // Es comprobante → armar huella para dedupe (N° de operación; si no, combo).
    let opKey = _normComprobanteKey(result.operationNumber);
    // Defensa anti falso-duplicado: si el "N° de operación" es en realidad un CBU/cuenta
    // o un CUIT/CUIL, NO lo usamos como huella — esos datos se REPITEN entre transferencias
    // distintas y marcan duplicados falsos. Caso real: la IA leía el CUIT del destino
    // (ej. 30-71876498-6) como "N° de operación" → todos los comprobantes a ese destino
    // chocaban entre sí y se reportaban como "ya utilizado por" el primero que lo mandó.
    const _destDig = _digits(result.destCbu);
    const _origDig = _digits(result.originCbu);
    const _rawOp = String(result.operationNumber || '').replace(/\s/g, '');
    // CUIT/CUIL = 11 dígitos con prefijo válido (20/23/24/27/30/33/34), con o sin guiones.
    const _looksLikeCuit = /^(20|23|24|27|30|33|34)-?\d{8}-?\d$/.test(_rawOp) || /^(20|23|24|27|30|33|34)\d{9}$/.test(opKey);
    if (opKey && (
      (_destDig && opKey === _destDig) ||
      (_origDig && opKey === _origDig) ||
      /^\d{18,}$/.test(opKey) ||
      _looksLikeCuit
    )) {
      opKey = '';
    }
    let dedupeKey = opKey || null;
    // Fallback: combo que incluye el NOMBRE de origen (más único que el CBU repetido).
    if (!dedupeKey && result.amount && (result.originHolder || result.originCbu || result.paymentDate)) {
      dedupeKey = _normComprobanteKey(`${result.amount}|${result.originHolder || ''}|${result.originCbu || ''}|${result.paymentDate || ''}`);
    }

    const base = {
      id: uuidv4(), userId, username, messageId,
      isComprobante: true, aiConfidence: result.confidence || 0,
      operationNumber: result.operationNumber || null,
      amount: result.amount, originHolder: result.originHolder || null,
      originCbu: result.originCbu || null,
      destHolder: result.destHolder || null, destCbu: result.destCbu || null,
      bank: result.bank || null,
      paymentDate: result.paymentDate || null, rawText: result.rawText || null,
      dedupeKey, imageHash, model: result.model, createdAt: new Date()
    };

    // #808: comprobante reconocido pero con datos clave ilegibles (sin monto, o sin titular y sin N° de operación) ⇒ pedir reenvío.
    // Sigue el flujo igual (queda en la cola para revisión manual), así no se pierde si el agente lo puede leer.
    // #825: también sin fecha/hora (se usa para ubicar la transferencia).
    if (!(Number(result.amount) > 0) || (!result.originHolder && !result.operationNumber) || !result.paymentDate) _askReceiptResend(userId, username, 'incomplete', base.id);
    const montoStr = result.amount ? `$${Number(result.amount).toLocaleString('es-AR')}` : 's/monto';
    const opStr = result.operationNumber ? `op. N°${result.operationNumber}` : 's/N° operación';
    const dataDesc = `${opStr} · ${montoStr}${result.paymentDate ? ' · ' + result.paymentDate : ''}`;

    // Buscar un comprobante ANTERIOR duplicado: por IMAGEN idéntica (imageHash) O por
    // huella de datos (dedupeKey). El hash de imagen se chequea SIEMPRE (aunque no haya
    // N° de operación), así un re-envío de la misma imagen se detecta igual.
    const dupOr = [];
    if (imageHash) dupOr.push({ imageHash });
    if (dedupeKey) dupOr.push({ dedupeKey });
    let original = null;
    if (dupOr.length) {
      try {
        original = await Comprobante.findOne({ isComprobante: true, $or: dupOr })
          .sort({ createdAt: 1 }).lean();
      } catch (e) {
        logger.warn(`[comprobante] error buscando duplicado: ${e.message}`);
      }
    }

    if (original) {
      const sameUser = String(original.userId) === String(userId);
      try {
        await Comprobante.create({
          ...base, status: 'duplicate',
          duplicateOfUserId: original.userId || null,
          duplicateOfUsername: original.username || null,
          duplicateOfComprobanteId: original.id || null
        });
      } catch (_) {}
      if (sameUser) {
        await _emitAdminOnlyChatNote(userId, username,
          `🧾 Comprobante REPETIDO (${dataDesc}). El propio cliente ya lo había enviado antes. Revisá antes de cargar.`);
      } else {
        await _emitAdminOnlyChatNote(userId, username,
          `🚨 COMPROBANTE YA UTILIZADO POR: @${original.username || original.userId}\n${dataDesc}\n⚠️ Ya lo había enviado otro usuario. NO cargar sin verificar.`);
      }
      // #376 (owner): avisarle también al CLIENTE que ese comprobante ya fue usado (antes sólo lo veía el admin).
      try {
        const dupTxt = await renderSystemCommand('/sys_receipt_duplicate', RECEIPT_DUPLICATE_DEFAULT, { amount: _amtStr(result.amount) });
        if (dupTxt) await _sendUserSystemMessage({ id: userId, username }, dupTxt, { metadata: { kind: 'receipt_duplicate', amount: result.amount || 0 } });
      } catch (_) {}
      _chatAutoCloseIfHandled(userId, 'comprobante repetido').catch(() => {}); // #895
      return;
    }

    // No es duplicado. Si tenemos alguna huella (datos o imagen) → verificado OK.
    // Si no hay NINGUNA (ni N° de operación ni hash de imagen) → avisar verificá a mano.
    const hasDedup = !!dedupeKey || !!imageHash;
    const status = dedupeKey ? 'unique' : 'no_key';
    try { await Comprobante.create({ ...base, status, reviewStatus: 'pending', reviewQueuedAt: new Date() }); } catch (_) {} // #376: entra en la cola
    if (hasDedup) {
      await _emitAdminOnlyChatNote(userId, username,
        `✅ Comprobante verificado — no es duplicado (${dataDesc}).`);
    } else {
      await _emitAdminOnlyChatNote(userId, username,
        `🧾 Comprobante recibido (${dataDesc}). ⚠️ No se pudieron extraer datos para chequear duplicado — verificá a mano.`);
    }
    // Banco automático: si fue al CBU con API, intentar matchear + cargar.
    hgcashMatchFromComprobante({ ...base, status }).catch(() => {});
    // #376: acuse al cliente. Si el banco automático está apagado o en sombra no va a acreditarse solo → escala YA
    // (el cliente ve "carga pendiente, un agente la revisa" y el panel la lista); si está en auto, el cron escala
    // sólo si pasan los minutos configurados sin acreditación.
    try {
      const hg = await getHgcashConfig();
      if (!hg.enabled || hg.mode !== 'auto') {
        await _depositReviewEscalate({ ...base, status }, !hg.enabled ? 'banco automático apagado' : 'banco automático en modo sombra');
      } else {
        const ackTxt = await renderSystemCommand('/sys_receipt_received', RECEIPT_RECEIVED_DEFAULT, { amount: _amtStr(result.amount) });
        if (ackTxt) await _sendUserSystemMessage({ id: userId, username }, ackTxt, { metadata: { kind: 'deposit_pending', comprobanteId: base.id, amount: result.amount || 0 } });
        _emitDepositReviewUpdate(userId, { action: 'queued', id: base.id, username, amount: result.amount || 0 });
        _chatAutoCloseIfHandled(userId, 'comprobante recibido: lo acredita el banco automático').catch(() => {}); // #895 (si no entra, va a Cargas pendientes)
      }
    } catch (e) { logger.warn(`[deposit-review] acuse: ${e.message}`); }
  } catch (e) {
    // Defensa total: este análisis NUNCA debe romper nada del chat.
    logger.warn(`[comprobante] analyzeComprobanteFromMessage falló: ${e.message}`);
  }
}

// ============================================
// BANCO AUTOMÁTICO (hgcash / Urbana) — carga automática por match de comprobante
// ============================================
// Config en Config['hgcash']:
//   { enabled, cbu, accountId, mode ('shadow'|'auto'), windowMinutes, currency }
//   enabled=false → TODO apagado. mode='shadow' → matchea y avisa pero NO carga.
// El secreto de firma del webhook va en process.env.HGCASH_WEBHOOK_SECRET (SSM).
// Nota: el payload real de hgcash NO trae CBUs (sólo fromName/toName/amount/status/
// externalID). Por eso el matcheo es por monto + NOMBRE de origen + ventana de tiempo,
// con guard de ambigüedad. `accountName` = el toName de tu cuenta hgcash (ej. el titular)
// para confirmar que el comprobante fue a tu banco con API. `acceptStatuses` = estados del
// movimiento que cuentan como acreditado (hgcash manda status:"done").
// windowMinutes: ventana para el matcheo DESDE el comprobante (el cliente manda el
//   comprobante y se busca su transferencia pendiente — el disparador principal).
// raceWindowMinutes: ventana CORTA para el matcheo DESDE la transferencia (solo cubre
//   el caso raro en que el comprobante llega segundos ANTES que el webhook). Mantenerla
//   chica evita que una transferencia nueva cargue contra un comprobante viejo/sobrante.
const HGCASH_DEFAULTS = { enabled: false, cbu: '', accountId: '', accountName: '', mode: 'shadow', windowMinutes: 60, raceWindowMinutes: 10, currency: 'ARS', acceptStatuses: ['done'], duplicateGuardMinutes: 8, minChargeARS: 2000 };

async function getHgcashConfig() {
  const cfg = await getConfig('hgcash', null);
  const merged = Object.assign({}, HGCASH_DEFAULTS, cfg || {});
  if (!Array.isArray(merged.acceptStatuses) || merged.acceptStatuses.length === 0) merged.acceptStatuses = ['done'];
  return merged;
}

// Sólo dígitos (para comparar CBUs sin importar formato/espacios).
function _digits(s) { return String(s || '').replace(/\D/g, ''); }

// Igualdad de montos en centavos (evita errores de coma flotante).
function _amountsEqual(a, b) {
  if (a === null || a === undefined || b === null || b === undefined) return false;
  return Math.round(Number(a) * 100) === Math.round(Number(b) * 100);
}

// Normaliza un nombre para comparar (mayúsculas, sin acentos, sin puntuación, espacios simples).
function _normName(s) {
  return String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
}

// ¿Coinciden dos nombres? Igual normalizado, o uno contiene al otro (≥5 chars).
function _nameMatch(a, b) {
  const na = _normName(a), nb = _normName(b);
  if (!na || !nb || na.length < 5 || nb.length < 5) return false;
  if (na === nb || na.includes(nb) || nb.includes(na)) return true;
  // #820: mismo nombre en OTRO orden ("JUAN PEREZ" vs "PEREZ JUAN", o con un segundo nombre en el medio). Todas las palabras (≥3 letras)
  // del nombre más corto tienen que estar en el otro, y tienen que ser al menos 2 (una sola palabra no alcanza para confirmar).
  const wa = na.split(' ').filter((w) => w.length >= 3), wb = nb.split(' ').filter((w) => w.length >= 3);
  const [short, long] = wa.length <= wb.length ? [wa, new Set(wb)] : [wb, new Set(wa)];
  return short.length >= 2 && short.every((w) => long.has(w));
}

// ¿El estado del movimiento cuenta como acreditado?
function _statusAccredited(status, cfg) {
  const list = (cfg.acceptStatuses || ['done']).map(s => String(s).toLowerCase());
  return list.includes(String(status || '').toLowerCase());
}

// ¿El comprobante apunta a NUESTRA cuenta hgcash? (por CBU si lo hubiera, o por nombre de cuenta)
function _comprobanteToOurBank(comprobante, cfg) {
  const cfgCbu = _digits(cfg.cbu);
  if (cfgCbu && _digits(comprobante.destCbu) === cfgCbu) return true;
  if (cfg.accountName && _nameMatch(comprobante.destHolder, cfg.accountName)) return true;
  return false;
}

// ¿El destino confirma nuestra cuenta, O el comprobante no muestra destino?
// Muchos comprobantes no muestran el CBU/nombre de destino. Como el webhook de
// hgcash es prueba REAL de que la plata entró a NUESTRA cuenta, aceptamos el match
// también cuando el comprobante no trae datos de destino (con el guard de
// ambigüedad + monto + nombre de origen + ventana, el riesgo es mínimo).
function _destOkOrUnknown(comprobante, cfg) {
  if (_comprobanteToOurBank(comprobante, cfg)) return true;
  return !comprobante.destHolder && !comprobante.destCbu;
}

// ¿El destino del comprobante es consistente con el del movimiento (o no se sabe)?
// Usa el destino REAL del movimiento (toName/toCBU de la cuenta hgcash que recibió),
// así funciona para CUALQUIER cuenta hgcash sin depender de la config. Si el
// comprobante no muestra destino, se acepta (el movimiento ya prueba que entró a
// nuestra cuenta).
function _destConsistentOk(comprobante, movement, cfg) {
  if (!comprobante.destHolder && !comprobante.destCbu) return true;
  if (movement) {
    if (comprobante.destCbu && movement.toCBU && _digits(comprobante.destCbu) === _digits(movement.toCBU)) return true;
    if (comprobante.destHolder && movement.toName && _nameMatch(comprobante.destHolder, movement.toName)) return true;
  }
  if (_comprobanteToOurBank(comprobante, cfg)) return true;
  return false;
}

// ¿Este comprobante corresponde a ESTE movimiento entrante? Debe coincidir el MONTO y,
// además, UNO de estos (en orden de fuerza):
//   (1) N° de transacción del comprobante == coelsaCode/externalID del movimiento.
//       Es DEFINITIVO y funciona para cualquier banco (no necesita el nombre del que envía).
//   (2) Nombre de ORIGEN del comprobante == fromName del movimiento, con destino consistente.
// Si no se cumple ninguno → no es match (queda manual).
function _comprobanteMatchesMovement(comprobante, movement, cfg) {
  if (!_amountsEqual(comprobante.amount, movement.amount)) return false;

  // (1) Match definitivo por número de transacción / coelsa.
  const opKey = _normComprobanteKey(comprobante.operationNumber);
  if (opKey && opKey.length >= 6) {
    const coelsa = _normComprobanteKey(movement.coelsaCode);
    const ext = _normComprobanteKey(movement.externalId);
    if (coelsa && coelsa === opKey) return true;
    if (ext && opKey.length >= 8 && ext.includes(opKey)) return true;
  }

  // (2) Fallback por nombre de origen + destino consistente.
  if (comprobante.originHolder && movement.fromName &&
      _nameMatch(comprobante.originHolder, movement.fromName) &&
      _destConsistentOk(comprobante, movement, cfg)) {
    return true;
  }
  return false;
}

// Maneja un fallo de auto-carga (JUGAYGANA caído, etc.) de forma REINTENTABLE:
// cuenta el intento y, si no superó el tope (3), devuelve el movimiento a 'pending'
// para que un nuevo comprobante pueda reintentar. Pasado el tope, lo deja en 'error'
// (carga manual). El comprobante vuelve a 'pending' para no quedar consumido.
const HGCASH_MAX_CHARGE_ATTEMPTS = 3;
async function hgcashHandleChargeFailure(movement, comprobante, errMsg, dataDesc, user) {
  let attempts = (movement.chargeAttempts || 0) + 1;
  try {
    const upd = await BankMovement.findOneAndUpdate(
      { movementId: movement.movementId },
      { $inc: { chargeAttempts: 1 }, $set: { chargeError: String(errMsg || '').slice(0, 300) } },
      { new: true }
    );
    if (upd && typeof upd.chargeAttempts === 'number') attempts = upd.chargeAttempts;
  } catch (_) {}
  const terminal = attempts >= HGCASH_MAX_CHARGE_ATTEMPTS;
  await BankMovement.updateOne({ movementId: movement.movementId }, { $set: { matchStatus: terminal ? 'error' : 'pending' } });
  // #820: guardar a qué transferencia correspondía ⇒ si un agente la confirma desde Cargas pendientes, usa la MISMA reference (no duplica
  // si 1girox en realidad la había acreditado, p. ej. tras un timeout).
  await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'pending', matchedMovementId: movement.movementId } });
  // #811 (owner): "si falla por la API, que entre en confirmación de forma manual" ⇒ agotados los reintentos, el comprobante pasa a
  // "Esperando agente" en Cargas pendientes (el cliente recibe /sys_deposit_pending_review: "un agente la está verificando").
  if (terminal && user) { try { await _depositReviewEscalate({ id: comprobante.id, userId: user.id, username: user.username, amount: Number(movement.amount) || comprobante.amount || 0 }, 'falló la acreditación en la plataforma'); } catch (_) {} }
  if (user) {
    const prefijo = terminal ? `Se agotaron los ${HGCASH_MAX_CHARGE_ATTEMPTS} intentos automáticos. ` : '';
    await _emitAdminOnlyChatNote(user.id, user.username,
      `🏦 MATCH hgcash — ${dataDesc}\n⚠️ La AUTO-CARGA FALLÓ en la plataforma (${errMsg || 's/detalle'}). ${prefijo}Confirmala desde Cargas pendientes (usa la MISMA referencia: si la plataforma ya la había acreditado, no se duplica). Evitá cargarla a mano por otro lado.`);
  }
}

// Cuando un operador carga MANUAL a un usuario, si había un movimiento hgcash
// matcheado a ese usuario por el MISMO monto (que no se pudo auto-cargar), lo
// marcamos como `manual_charged` y consumimos el comprobante. Así esa transferencia
// /foto NO vuelve a auto-cargar cuando JUGAYGANA se recupere (evita doble carga).
async function hgcashConsumeOnManualDeposit(userId, username, amount) {
  try {
    const cfg = await getHgcashConfig();
    if (!cfg.enabled) return false;
    if (!userId || !(Number(amount) > 0)) return false;

    // Candidatos: movimientos matcheados a ese usuario, todavía no cargados.
    // Incluye 'needs_review' (frenados por la red de seguridad) para que, si el
    // agente confirma y carga a mano, ese movimiento quede consumido y no quede
    // colgado como pendiente en el panel.
    // 'awaiting_platform' (multi-plataforma): el agente cargó a mano mientras el
    // cliente todavía no había elegido → también se consume (y se cierra la pregunta).
    const cands = await BankMovement.find({
      matchedUserId: userId,
      matchStatus: { $in: ['pending', 'error', 'needs_review', 'awaiting_platform'] }
    }).sort({ createdAt: -1 }).limit(10).lean();
    const target = cands.find(m => _amountsEqual(m.amount, amount));
    if (!target) return false;

    // Claim atómico (evita choque con un reintento automático).
    const claimed = await BankMovement.findOneAndUpdate(
      { movementId: target.movementId, matchStatus: { $in: ['pending', 'error', 'needs_review', 'awaiting_platform'] } },
      { $set: { matchStatus: 'manual_charged', chargedAt: new Date(), platformChoiceBy: target.matchStatus === 'awaiting_platform' ? 'manual_deposit' : target.platformChoiceBy || null } },
      { new: true }
    );
    if (!claimed) return false;
    if (target.matchStatus === 'awaiting_platform') { try { await _resolvePlatformChoiceMessage(target, 'manual'); } catch (_) {} }

    if (target.matchedComprobanteId) {
      await Comprobante.updateOne({ id: target.matchedComprobanteId },
        { $set: { bankMatchStatus: 'manual_charged', autoCharged: true, reviewStatus: 'confirmed', reviewResolution: 'manual', reviewedBy: 'agente', reviewedAt: new Date() } }); // #376
    }
    await _emitAdminOnlyChatNote(userId, username,
      `🏦 Transferencia hgcash marcada como CARGADA MANUAL ($${Number(target.amount).toLocaleString('es-AR')}). Ese comprobante no se va a auto-cargar de nuevo.`);
    logger.info(`[hgcash] movimiento ${target.movementId} → manual_charged (carga manual de ${username})`);
    return true;
  } catch (e) {
    logger.warn(`[hgcash] consume on manual deposit falló: ${e.message}`);
    return false;
  }
}

// Guarda el accountId de nuestra cuenta hgcash en la config si todavía no está
// (lo necesitamos para los pagos salientes / cash-out).
async function ensureHgcashAccountIdSaved(accountId) {
  try {
    const cfg = await getHgcashConfig();
    if (!cfg.accountId && accountId) {
      await setConfig('hgcash', Object.assign({}, cfg, { accountId: String(accountId) }));
      logger.info(`[hgcash] accountId auto-guardado: ${accountId}`);
    }
  } catch (_) {}
}

// Avisa al cliente (y a los admins) que su retiro fue pagado. El texto es editable
// desde COMANDOS (/sys_payout_paid); si se vacía ese comando, no se envía nada.
async function notifyPayoutPaid(payout) {
  try { if (payout && payout.userId) outboundWebhook.notify('retiro', { id: payout.userId }, { amount: Number(payout.amount), payoutId: payout.id, occurredAt: payout.paidAt || new Date() }); } catch (_) {} // #562 webhooks salientes (D)
  try {
    const content = await renderSystemCommand(
      '/sys_payout_paid',
      '💸✅ ¡Tu retiro de ${amount} fue enviado a tu cuenta! Puede tardar unos minutos en acreditarse.',
      { amount: Number(payout.amount).toLocaleString('es-AR') }
    );
    if (!content) return; // comando vaciado a propósito → no enviar
    const msg = await Message.create({
      id: uuidv4(), senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin',
      receiverId: payout.userId, receiverRole: 'user', content, type: 'system', timestamp: new Date(), read: false
    });
    const data = { id: msg.id, senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin', receiverId: payout.userId, receiverRole: 'user', content, timestamp: new Date(), type: 'system' };
    io.to(`user_${payout.userId}`).emit('new_message', data);
    io.to(`chat_${payout.userId}`).emit('new_message', data);
    notifyAdmins('new_message', { message: data, userId: payout.userId, username: payout.username });
  } catch (e) {
    logger.warn(`[hgcash-pay] notifyPayoutPaid falló: ${e.message}`);
  }
}

// Resuelve el id de la TRANSACCIÓN real (para el comprobante PDF) a partir del payout.
// Usa el hgTxId si ya lo tenemos; si no, lo pide a la API con el id del REQUEST
// (que guardamos en hgTransactionId) y lo cachea. Devuelve null si todavía no está.
async function resolvePayoutTxId(payout) {
  if (!payout) return null;
  if (payout.hgTxId) return payout.hgTxId;
  const reqId = payout.hgTransactionId; // ojo: este campo guarda el id del REQUEST del cash-out
  if (!reqId) return null;
  try {
    const r = await hgcashPay.getTransactionIdForRequest(reqId);
    if (r.ok && r.transactionId) {
      const txId = String(r.transactionId);
      try { await PendingPayout.updateOne({ id: payout.id }, { $set: { hgTxId: txId } }); } catch (_) {}
      return txId;
    }
  } catch (_) {}
  return null;
}

// Envía AUTOMÁTICAMENTE el comprobante PDF del pago al cliente cuando el retiro se
// confirma (DONE). El mensaje lleva un link PERMANENTE nuestro (/api/payout-receipt/:id)
// que en cada click resuelve un signedUrl fresco de hgcash (la URL firmada vence en 1h,
// por eso no la mandamos directa). Idempotente: marca receiptSentAt y reclama atómico
// para no enviar dos veces (webhook DONE + pago inmediato).
async function maybeSendPayoutReceipt(payout) {
  try {
    if (!hgcashPay.isEnabled()) return;
    let cur = await PendingPayout.findOne({ id: payout.id }).lean();
    if (!cur || cur.receiptSentAt) return;

    // El id de transacción puede tardar unos segundos en asociarse: reintentar.
    let txId = await resolvePayoutTxId(cur);
    for (let i = 0; i < 3 && !txId; i++) {
      await new Promise(r => setTimeout(r, 4000));
      cur = await PendingPayout.findOne({ id: payout.id }).lean();
      if (!cur || cur.receiptSentAt) return;
      txId = await resolvePayoutTxId(cur);
    }
    if (!txId) { logger.warn(`[hgcash-pay] sin txId para comprobante payout=${payout.id} (se omite el envío)`); return; }

    // Reclamo atómico del envío (no duplicar entre webhook y pago inmediato).
    const claimed = await PendingPayout.findOneAndUpdate(
      { id: payout.id, receiptSentAt: null },
      { $set: { receiptSentAt: new Date() } }, { new: true }
    );
    if (!claimed) return; // otro proceso ya lo envió

    // Helper para emitir un mensaje del sistema al cliente (chat + socket + admins).
    const _sendClientMsg = async (content, type) => {
      const msg = await Message.create({
        id: uuidv4(), senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin',
        receiverId: payout.userId, receiverRole: 'user', content, type, timestamp: new Date(), read: false
      });
      const data = { id: msg.id, senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin', receiverId: payout.userId, receiverRole: 'user', content, timestamp: new Date(), type };
      io.to(`user_${payout.userId}`).emit('new_message', data);
      io.to(`chat_${payout.userId}`).emit('new_message', data);
      notifyAdmins('new_message', { message: data, userId: payout.userId, username: payout.username });
    };

    // 1) Mandar el comprobante COMO FOTO (rasterizar la 1ª página del PDF). Best-effort:
    //    si falla (dep opcional ausente, error de descarga/render, imagen muy grande),
    //    se manda sólo el link. Nunca rompe el flujo de pago.
    let photoSent = false;
    try {
      const pdf = await hgcashPay.fetchReceiptPdf(txId);
      if (pdf.ok && pdf.buffer && pdf.buffer.length) {
        const png = await pdfImage.pdfBufferToPng(pdf.buffer);
        if (png && png.length && png.length < 4 * 1024 * 1024) {
          await _sendClientMsg(`data:image/png;base64,${png.toString('base64')}`, 'image');
          photoSent = true;
        }
      }
    } catch (e) {
      logger.warn(`[hgcash-pay] comprobante como foto falló (se manda link): ${e.message}`);
    }

    // 2) Link al PDF oficial (siempre). Si no se pudo mandar la foto, este es el comprobante principal.
    const link = `${getPublicBaseUrl()}/api/payout-receipt/${payout.id}`;
    const linkMsg = photoSent
      ? `🧾 Comprobante oficial (PDF): ${link}`
      : `🧾✅ Comprobante de tu pago de $${Number(payout.amount).toLocaleString('es-AR')}:\n${link}`;
    await _sendClientMsg(linkMsg, 'system');
    logger.info(`[hgcash-pay] comprobante enviado a ${payout.username} payout=${payout.id} txId=${txId} foto=${photoSent}`);
  } catch (e) {
    logger.warn(`[hgcash-pay] maybeSendPayoutReceipt falló: ${e.message}`);
  }
}

// Procesa el webhook de estado de un cash-out (pago saliente). Matchea por externalID
// (que es nuestro payout.id) o por el id de la transacción hgcash.
async function handlePayoutStatusWebhook(p) {
  try {
    const status = String(p.status || '').toUpperCase();
    const ext = p.externalID ? String(p.externalID) : null;
    const hgId = p.id ? String(p.id) : null;
    const extBase = ext ? String(ext).replace(/-r\d+$/, '') : ext; // #820: reintentos con externalID `<id>-rN`
    const query = ext ? { id: extBase } : (hgId ? { hgTransactionId: hgId } : null);
    if (!query) return;
    const payout = await PendingPayout.findOne(query);
    // #820: aviso de un intento ANTERIOR (otro externalID) que llega tarde ⇒ no pisa el intento actual.
    if (payout && ext && String(ext) !== payout.id + (payout.extSuffix || '') && !(hgId && payout.hgTransactionId && String(hgId) === String(payout.hgTransactionId))) {
      logger.warn(`[hgcash-pay] webhook de un intento viejo ignorado: ext=${ext} actual=${payout.id + (payout.extSuffix || '')} status=${status}`);
      if (status === 'DONE') await _emitAdminOnlyChatNote(payout.userId, payout.username, `🚨 URGENTE: el banco confirmó como PAGADO un intento ANTERIOR del retiro de $${Number(payout.amount).toLocaleString('es-AR')} (${ext}). Revisá en hgcash que no haya salido dos veces.`).catch(() => {});
      return;
    }
    if (!payout) {
      logger.warn(`[hgcash-pay] webhook de pago sin payout local: ext=${ext} hgId=${hgId} status=${status}`);
      return;
    }
    // Guardar el hgTransactionId si todavía no lo teníamos.
    if (hgId && !payout.hgTransactionId) {
      await PendingPayout.updateOne({ id: payout.id }, { $set: { hgTransactionId: hgId } });
    }
    // El webhook 'transaction_associated' trae el id de la TRANSACCIÓN real (≠ request)
    // → lo guardamos para poder pedir el comprobante PDF.
    if (p.transactionId && !payout.hgTxId) {
      await PendingPayout.updateOne({ id: payout.id }, { $set: { hgTxId: String(p.transactionId) } });
      payout.hgTxId = String(p.transactionId);
    }

    if (status === 'DONE') {
      if (payout.status === 'paid') return; // idempotente
      // #820: el banco pagó algo que ya estaba RECHAZADO (fichas devueltas) o pagado por otro banco ⇒ posible pago doble: alertar, no pisar.
      if (payout.status === 'cancelled' || payout.paidVia === 'other_bank') {
        await PendingPayout.updateOne({ id: payout.id }, { $set: { hgStatus: status } });
        await _emitAdminOnlyChatNote(payout.userId, payout.username, `🚨 URGENTE: hgcash confirmó PAGADO el retiro de $${Number(payout.amount).toLocaleString('es-AR')}, pero en el panel estaba ${payout.status === 'cancelled' ? 'RECHAZADO (con las fichas devueltas)' : 'pagado por OTRO banco'}. Revisá: el cliente pudo cobrar dos veces.`).catch(() => {});
        try { io.to('admins').emit('security_alert', { username: payout.username, message: `Posible pago doble: retiro $${payout.amount} de ${payout.username}`, at: new Date() }); } catch (_) {}
        return;
      }
      // Claim atómico: webhook y poller pueden llegar juntos ⇒ un solo aviso al cliente.
      const upd = await PendingPayout.updateOne({ id: payout.id, status: { $ne: 'paid' } }, { $set: { status: 'paid', hgStatus: status, paidAt: new Date() } });
      if (!(upd.modifiedCount || upd.nModified)) return;
      _bankPayoutOk().catch(() => {}); // #442
      await notifyPayoutPaid(payout);
      maybeSendPayoutReceipt(payout).catch(() => {}); // comprobante PDF automático (con reintentos)
      logger.info(`[hgcash-pay] PAGADO payout=${payout.id} user=${payout.username} $${payout.amount}`);
    } else if (status === 'ERROR' || status === 'CANCELLED') {
      const reason = p.errorCode || p.error || status;
      await PendingPayout.updateOne({ id: payout.id }, { $set: { status: 'failed', hgStatus: status, error: String(reason).slice(0, 300) } });
      _bankPayoutFailed(reason, payout).catch(() => {}); // #442/#443
      // Si las fichas ya se descontaron (flujo nuevo confirmado), aclararlo: NO devolver.
      const yaDescontado = (payout.deductAtPay === true && payout.debitConfirmed === true);
      await _emitAdminOnlyChatNote(payout.userId, payout.username,
        `💸 ⚠️ El PAGO automático FALLÓ en hgcash (${reason}) — $${Number(payout.amount).toLocaleString('es-AR')} a ${payout.titular || payout.cbu}. ` +
        (yaDescontado ? 'Las fichas YA fueron descontadas: NO devuelvas. Pagá manual ("otro banco") o reintentá.' : 'Revisá y pagá manual.'));
      logger.warn(`[hgcash-pay] FALLÓ payout=${payout.id} status=${status} reason=${reason}`);
    } else {
      // PENDING / AWAITING_REVIEW / PROCESSING → sólo actualizar hgStatus.
      await PendingPayout.updateOne({ id: payout.id }, { $set: { hgStatus: status } });
    }
  } catch (e) {
    logger.warn(`[hgcash-pay] handlePayoutStatusWebhook falló: ${e.message}`);
  }
}

// Avisa al panel (en vivo) que hubo un cambio en los movimientos hgcash, para que
// refresque la tabla sin recargar. Fire-and-forget; nunca rompe nada.
function _emitHgcashUpdate(kind) {
  try { notifyAdmins('hgcash_movement', { kind: kind || 'update', at: Date.now() }); } catch (_) {}
}

// Acredita la carga (modo 'auto') o sólo avisa (modo 'shadow'). Reclama de forma
// ATÓMICA el movimiento Y el comprobante para que nunca se cargue dos veces.
async function hgcashAutoCarga({ movement, comprobante, mode }) {
  const shadow = mode !== 'auto';

  // 1) Reclamar el movimiento (pending → claiming).
  const movClaim = await BankMovement.findOneAndUpdate(
    { movementId: movement.movementId, matchStatus: 'pending' },
    { $set: { matchStatus: 'claiming' } }, { new: true }
  );
  if (!movClaim) return; // ya lo tomó otro proceso

  // 2) Reclamar el comprobante (no cargado/tomado todavía).
  const compClaim = await Comprobante.findOneAndUpdate(
    { id: comprobante.id, autoCharged: { $ne: true }, reviewStatus: { $nin: ['confirmed', 'rejected'] }, bankMatchStatus: { $nin: ['claiming', 'auto_charged', 'shadow_matched'] } }, // #820
    { $set: { bankMatchStatus: 'claiming', toApiBank: true } }, { new: true }
  );
  if (!compClaim) {
    // El comprobante ya fue tomado por otro movimiento → devolver el movimiento.
    await BankMovement.updateOne({ movementId: movement.movementId }, { $set: { matchStatus: 'pending' } });
    return;
  }

  const user = await User.findOne({ id: comprobante.userId });
  if (!user) {
    await BankMovement.updateOne({ movementId: movement.movementId }, { $set: { matchStatus: 'error', chargeError: 'usuario no encontrado' } });
    await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'pending' } });
    return;
  }

  // Registrar a quién matcheó el movimiento (sirve para reconciliar y para que una
  // carga MANUAL a este usuario consuma el movimiento aunque la auto-carga falle).
  try {
    await BankMovement.updateOne({ movementId: movement.movementId },
      { $set: { matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id } });
  } catch (_) {}

  const amount = movement.amount;
  const opDesc = `op. hgcash ${movement.coelsaCode || movement.externalId || movement.movementId}`;
  const dataDesc = `$${Number(amount).toLocaleString('es-AR')} · ${movement.fromName || movement.fromCBU || 's/origen'} · ${opDesc}`;

  // Modo sombra: NO cargar, sólo avisar al admin que el match está listo.
  if (shadow) {
    await BankMovement.updateOne({ movementId: movement.movementId }, {
      $set: { matchStatus: 'shadow_matched', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id }
    });
    await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'shadow_matched', matchedMovementId: movement.movementId } });
    await _emitAdminOnlyChatNote(user.id, user.username,
      `🏦 MATCH hgcash (MODO SOMBRA) — ${dataDesc}\n✅ La transferencia coincide con el comprobante. Lista para cargar (auto-carga DESACTIVADA — cargá vos).`);
    logger.info(`[hgcash] shadow match user=${user.username} amount=$${amount} movement=${movement.movementId}`);
    return;
  }

  // ── MÍNIMO DE CARGA ──────────────────────────────────────────────────────
  // Si la transferencia es MENOR al mínimo del casino, NO se carga automático.
  // El comprobante quedó verificado igual: se avisa al agente para que le pida al
  // cliente la diferencia y, cuando llegue, se cargue la suma a mano. Se deja el
  // movimiento en needs_review (lo consume la carga manual; no se pierde plata).
  try {
    const _minCfg = await getHgcashConfig();
    // #686 (owner): el mínimo que manda es la CARGA MÍNIMA de la app (Config['minDepositArs'], $5.000), nunca menos que el de hgcash
    let _appMin = 0; try { _appMin = Number(await getMinDepositArs()) || 0; } catch (_) {}
    const minCharge = Math.max(Number(_minCfg.minChargeARS) > 0 ? Number(_minCfg.minChargeARS) : 2000, _appMin);
    if (Number(amount) < minCharge) {
      // #803 (owner): "cuando se rechaza un pago por no llegar al mínimo no se carga y se le DEVUELVE la plata al cliente con el aviso
      // de que la carga mínima es de $5.000, todo automático". Kill switch: BELOW_MIN_AUTO_REFUND=0. Si la devolución falla (sin CBU
      // de origen, hgcash caído) sigue el camino de siempre: aviso de Soporte + movimiento en revisión para devolver a mano.
      if (process.env.BELOW_MIN_AUTO_REFUND !== '0' && hgcashPay.isEnabled()) {
        try {
          const toCBU = String(movement.fromCBU || '').replace(/\D/g, '');
          if (toCBU.length === 22) {
            await BankMovement.updateOne({ movementId: movement.movementId }, { $set: { matchStatus: 'needs_review', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id, chargeError: `monto $${Number(amount)} menor al mínimo $${minCharge}` } });
            await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'needs_review', matchedMovementId: movement.movementId } });
            const mvNow = await BankMovement.findOne({ movementId: movement.movementId }).lean();
            const rr = await _refundBelowMinMovement(mvNow, { by: 'auto', amount: Number(amount), minDep: minCharge, toCBU });
            if (rr.ok) { _chatAutoCloseIfHandled(user.id, 'carga menor al mínimo: devuelta sola').catch(() => {}); return; } // #895
            logger.warn(`[hgcash] devolución automática bajo mínimo falló mov=${movement.movementId}: ${rr.error} — queda para devolver a mano`);
          }
        } catch (e) { logger.warn(`[hgcash] devolución automática bajo mínimo excepción: ${e.message}`); }
      }
      // #686 (owner): avisarle AL CLIENTE automáticamente que contacte a Soporte (texto editable en COMANDOS: /sys_below_min)
      try {
        const txt = await renderSystemCommand('/sys_below_min', BELOW_MIN_DEFAULT, { monto: Number(amount).toLocaleString('es-AR'), min: minCharge.toLocaleString('es-AR') });
        if (txt) await _sendUserSystemMessage(user, txt, { metadata: { kind: 'below_min', movementId: movement.movementId, amount: Number(amount), min: minCharge }, push: { title: '⚠️ Tu carga es menor al mínimo', body: `Recibimos $${Number(amount).toLocaleString('es-AR')}; con menos de $${minCharge.toLocaleString('es-AR')} tu carga NO va a ser acreditada. Escribinos por Soporte.`, data: { tag: 'below_min' } } });
      } catch (e) { logger.warn(`[hgcash] aviso bajo mínimo al cliente falló: ${e.message}`); }
      await BankMovement.updateOne({ movementId: movement.movementId },
        { $set: { matchStatus: 'needs_review', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id, chargeError: `monto $${Number(amount)} menor al mínimo $${minCharge}` } });
      await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'needs_review', matchedMovementId: movement.movementId } });
      await _emitAdminOnlyChatNote(user.id, user.username,
        `🏦 ✅ Comprobante CORRECTO (${dataDesc}) — PERO el monto es menor al mínimo de carga ($${minCharge.toLocaleString('es-AR')}). NO se cargó automático.\n👉 Pedile al cliente que envíe la diferencia para llegar al mínimo y cargá la suma a mano.`);
      logger.info(`[hgcash] bajo mínimo user=${user.username} $${amount} < $${minCharge} mov=${movement.movementId}`);
      _chatAutoCloseIfHandled(user.id, 'carga menor al mínimo: avisado').catch(() => {}); // #895 (queda en Cargas pendientes para devolver)
      return;
    }
  } catch (minErr) {
    logger.warn(`[hgcash] chequeo de mínimo falló (sigue la carga): ${minErr.message}`);
  }

  // ── MULTI-PLATAFORMA (2026-10-16): ¿DÓNDE QUIERE JUGAR? ──────────────────
  // Con 2+ plataformas habilitadas (Config['platforms']) la carga NO se acredita
  // todavía: se le pregunta al cliente con botones en el chat y el movimiento queda
  // `awaiting_platform`. Elige → POST /api/platform-choice → _hgcashCreditToPlatform.
  // No responde en `askTimeoutMin` → _platformChoiceTick lo carga en la última
  // plataforma que eligió (o la default). Con una sola plataforma (o askMode
  // 'never'/'first_time' con elección previa) se carga directo como siempre.
  let _decision;
  try {
    _decision = await platforms.decideForDeposit(user);
  } catch (decErr) {
    logger.warn(`[platforms] decideForDeposit falló (${decErr.message}) → carga directa en ${platforms.DEFAULT_ID}`);
    _decision = { ask: false, platform: platforms.DEFAULT_ID, reason: 'error' };
  }
  if (_decision.ask) {
    await _platformAskUser({ movement: movClaim || movement, comprobante, user, decision: _decision, dataDesc });
    return;
  }
  await _hgcashCreditToPlatform({ movement: movClaim || movement, comprobante, user, platformId: _decision.platform, by: _decision.reason || 'single' });
}

// ════════════════════════════════════════════════════════════════════════════
// MULTI-PLATAFORMA — pregunta "¿dónde querés jugar?", derivación por link y
// resolución de la elección (2026-10-16). Ver src/platforms/ y docs/PLATFORMS.md.
// ════════════════════════════════════════════════════════════════════════════

// Multiplicador del bono adjunto a la carga, según la plataforma. Para girox sale
// de su GET /config (getGiroxBonusMultiplier); otras plataformas: 0 hasta que su
// adaptador exponga algo mejor (el adaptador ignora `wagering` si no lo soporta).
// #839 (owner: "el bono está mal: en Girox figura sólo la carga; que funcione y cargue el bono de forma real"). Carga + bono en UNA
// función para la carga automática y la manual:
//  1) Va como siempre (bono adjunto a la carga, mismo `reference`).
//  2) Si 1girox rechaza la carga POR EL BONO (422 bonus_out_of_range: el 100% sin tope de la 1ª carga puede pasar `bonus.fixed_max`), se
//     repite la carga SIN bono con la MISMA reference (en un 422 la plataforma no movió plata) y `no_bonus` (que no herede reglas del panel):
//     antes la carga entera fallaba y el cliente que transfirió se quedaba sin fichas.
//  3) Si la carga entró pero el bono no (rechazo o `bonus.status:'failed'`), el bono se acredita APARTE con `creditGift` y el rollover de la
//     carga (reference `<ref>-bono`, idempotente): llega como Bono o, si la plataforma no lo deja, como carga con rollover. Antes se perdía.
//  Devuelve el resultado de la carga + `bonusFailed` (sólo si NO llegó por ningún camino) y `bonusVia` ('attached' | 'separate').
async function _depositWithBonus(adapter, username, amount, description, reference, bonusAmount) {
  const bonus = Math.round(Number(bonusAmount) || 0);
  // #882/#883 (owner): "carga común de plata ×3 rollover, sin bono; la de bono ×5": TODA carga real (hgcash y manual del panel) queda con
  // rollover ×depositRolloverX (3) y el bono con el global (×5). Si 1girox rechaza el multiplicador de la carga (422 en 'multiplier') se
  // prueba ×2 y después sin rollover propio, con la MISMA reference (en un 422 no movió plata): la carga nunca se pierde por esto.
  // (Las devoluciones de retiro rechazado NO pasan por acá: vuelven libres.)
  let depMult = await _depositRolloverXFor(adapter);
  const _wg = (extra) => Object.assign(depMult > 0 ? { multiplier: depMult } : {}, extra);
  // #899 (owner: "desde el panel lo manual no está cargando"): CUALQUIER 422 (validación: 1girox no movió plata) con el rollover de la carga
  // puesto se reintenta sin él (×2 y después sin rollover, misma reference) — antes sólo si el error nombraba "multiplier", y un
  // `feature_disabled` / `invalid_rollover` dejaba la carga sin hacer. El 422 del BONO (bonus_out_of_range) sigue su camino aparte.
  const _multRejected = (x) => !x.success && x.httpStatus === 422 && x.code !== 'bonus_out_of_range' && !/bonus_out_of_range|bonus out of range/i.test(String(x.error || ''));
  if (!(bonus > 0)) {
    let r0 = await adapter.depositToUser(username, amount, description, reference, _wg({ noBonus: true }));
    for (const fb of [2, 1, 0]) { /* #903 (owner): ×3 → ×2 → ×1 (y sólo si 1girox no acepta ninguno, sin rollover propio + alerta) */ if (!(_multRejected(r0) && depMult > 0 && depMult !== fb)) break; logger.warn(`[deposit] ${username}: 1girox rechazó el rollover ×${depMult} de la carga ⇒ pruebo ×${fb}`); depMult = fb; r0 = await adapter.depositToUser(username, amount, description, reference, _wg({ noBonus: true })); }
    if (r0.success) r0.depositRolloverX = depMult;
    if (r0.success && depMult === 0 && (await _depositRolloverXFor(adapter)) > 0) { logger.error(`[deposit] ⚠️ ${username}: la carga entró SIN rollover propio (1girox no aceptó ×3/×2/×1). Pedirle a 1girox que habilite el rollover en la red. ref=${reference}`); try { mongoose.connection.collection('hgcash_webhook_diag').updateOne({ _id: _schedArtKey(new Date()) }, { $inc: { cargasSinRollover: 1 }, $set: { lastSinRollover: { at: new Date(), username, reference } } }, { upsert: true }).catch(() => {}); } catch (_) {} }
    return r0;
  }
  const mult = await _bonusMultiplierFor(adapter);
  let r = await adapter.depositToUser(username, amount, description, reference, _wg({ bonusAmount: bonus, bonusMultiplier: mult }));
  // si rechaza el ×N de la carga: se prueba ×2 (siempre aceptado) y recién después sin rollover propio — misma reference, un 422 no movió plata
  for (const fb of [2, 1, 0]) { /* #903 (owner): ×3 → ×2 → ×1 (y sólo si 1girox no acepta ninguno, sin rollover propio + alerta) */ if (!(_multRejected(r) && depMult > 0 && depMult !== fb)) break; logger.warn(`[auto-bonus] ${username}: 1girox rechazó el rollover ×${depMult} de la carga (${r.code || r.error}) ⇒ pruebo ×${fb}`); depMult = fb; r = await adapter.depositToUser(username, amount, description, reference, _wg({ bonusAmount: bonus, bonusMultiplier: mult })); }
  let needSeparate = false;
  if (!r.success && (r.code === 'bonus_out_of_range' || (r.httpStatus === 422 && /bon(o|us)/i.test(String(r.error || ''))))) {
    logger.warn(`[auto-bonus] ${username}: 1girox rechazó la carga por el bono $${bonus} (${r.code || r.error}) ⇒ carga sin bono + bono aparte`);
    r = await adapter.depositToUser(username, amount, description, reference, _wg({ noBonus: true }));
    for (const fb of [2, 1, 0]) { /* #903 (owner): ×3 → ×2 → ×1 (y sólo si 1girox no acepta ninguno, sin rollover propio + alerta) */ if (!(_multRejected(r) && depMult > 0 && depMult !== fb)) break; depMult = fb; r = await adapter.depositToUser(username, amount, description, reference, _wg({ noBonus: true })); }
    needSeparate = !!r.success;
  } else if (r.success && r.bonusFailed) needSeparate = true;
  if (r.success) r.depositRolloverX = depMult;
  if (r.success && depMult === 0 && (await _depositRolloverXFor(adapter)) > 0) { logger.error(`[deposit] ⚠️ ${username}: la carga entró SIN rollover propio (1girox no aceptó ×3/×2/×1 en la carga). Pedirle a 1girox que habilite el rollover en la red. ref=${reference}`); try { mongoose.connection.collection('hgcash_webhook_diag').updateOne({ _id: _schedArtKey(new Date()) }, { $inc: { cargasSinRollover: 1 }, $set: { lastSinRollover: { at: new Date(), username, reference } } }, { upsert: true }).catch(() => {}); } catch (_) {} }
  if (r.success && !needSeparate) { r.bonusVia = 'attached'; return r; }
  if (needSeparate) {
    r.bonusFailed = true;
    if (typeof adapter.creditGift === 'function') {
      try {
        const g = await adapter.creditGift(username, bonus, { description: `Bono de la carga de $${Number(amount).toLocaleString('es-AR')}`, reference: `${reference}-bono`, rolloverX: mult });
        if (g && g.success) { r.bonusFailed = false; r.bonusVia = 'separate'; r.bonusCreditedAs = g.creditedAs || null; logger.info(`[auto-bonus] ${username}: bono $${bonus} acreditado APARTE (${g.creditedAs || 'ok'})`); }
        else logger.error(`[auto-bonus] ${username}: el bono $${bonus} tampoco entró aparte: ${g && g.error}`);
      } catch (e) { logger.error(`[auto-bonus] ${username}: bono aparte excepción: ${e.message}`); }
    }
  }
  return r;
}
async function _bonusMultiplierFor(adapter) {
  if (!adapter || adapter.id === 'girox' || adapter === girox) return getGiroxBonusMultiplier();
  return 0;
}
// #882: rollover de la CARGA cuando lleva bono. Config['depositRolloverX'] (default 3; 0 = sin rollover en la carga). Si la plataforma sólo
// acepta ciertos multiplicadores, el permitido más cercano hacia arriba (o el mayor), como el del bono.
async function getDepositRolloverX() { try { const v = Number(await getConfig('depositRolloverX', 1)); /* #976 (owner): ×1 (antes ×3) */ return Number.isFinite(v) && v >= 0 ? Math.min(50, Math.round(v)) : 3; } catch (_) { return 3; } }
async function _depositRolloverXFor(adapter) {
  if (adapter && !(adapter.id === 'girox' || adapter === girox)) return 0;
  const cv = await getDepositRolloverX(); if (!(cv > 0)) return 0;
  try {
    // la lista de la CARGA es config.rollover.multipliers (la del bono es otra); el panel de 1girox ofrece 0/1/2/3/5/10
    const cfg = await girox.getPlatformConfig(); const raw = cfg.success && cfg.config && cfg.config.rollover && cfg.config.rollover.multipliers;
    const allowed = Array.isArray(raw) ? raw.map(Number).filter((n) => Number.isFinite(n) && n > 0).sort((a, b) => a - b) : [];
    // #903 (owner): "si no funciona ×3, ponele ×2 mínimo; si no, ×1" ⇒ el permitido más ALTO que no pase del configurado (≥ 1); si no hay, el menor ≥ 1.
    if (allowed.length && !allowed.includes(cv)) { const down = allowed.filter((n) => n <= cv && n >= 1); if (down.length) return down[down.length - 1]; const up = allowed.filter((n) => n >= 1); return up.length ? up[0] : 0; }
  } catch (_) {}
  return cv;
}

// Le PREGUNTA al cliente dónde quiere jugar: deja el movimiento/comprobante en
// `awaiting_platform` y manda un mensaje de sistema con botones (metadata
// kind='platform_choice' → la PWA los renderiza; el agente ve el mismo texto en el
// chat y puede resolverlo él desde el panel). Push si está offline.
async function _platformAskUser({ movement, comprobante, user, decision, dataDesc }) {
  const amount = Number(movement.amount);
  const options = (decision.options || []).map((o) => ({ id: o.id, name: o.name, emoji: o.emoji }));
  const timeoutMin = Number(decision.timeoutMin) || 10;
  const expiresAt = new Date(Date.now() + timeoutMin * 60 * 1000);
  await BankMovement.updateOne({ movementId: movement.movementId }, {
    $set: {
      matchStatus: 'awaiting_platform', matchedUserId: user.id, matchedUsername: user.username,
      matchedComprobanteId: comprobante.id, platform: null, platformAskedAt: new Date(), platformChosenAt: null, platformChoiceBy: null
    }
  });
  await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'awaiting_platform', matchedMovementId: movement.movementId } });

  const optsTxt = options.map((o) => `${o.emoji} ${o.name}`).join(' / ');
  const content = await renderSystemCommand('/sys_platform_choice',
    '💰 ¡Recibimos tu transferencia de ${amount}! ✅\n\n🎮 ¿Dónde querés jugar? Tocá una opción 👇\n{options}\n\n⏱ Si no elegís en {timeout} minutos, te la cargamos en {default}.',
    { amount: amount.toLocaleString('es-AR'), options: optsTxt, timeout: timeoutMin, default: platforms.labelOf(await platforms.resolveDefaultFor(user)) });
  const metadata = { kind: 'platform_choice', movementId: movement.movementId, amount, options, expiresAt: expiresAt.toISOString() };
  const msg = content
    ? await _sendUserSystemMessage(user, content, { metadata, push: { title: '💰 Recibimos tu transferencia', body: `$${amount.toLocaleString('es-AR')} · Entrá y elegí dónde querés jugar`, data: { tag: 'platform_choice' } } })
    : null;
  if (msg) { try { await BankMovement.updateOne({ movementId: movement.movementId }, { $set: { platformChoiceMsgId: msg.id } }); } catch (_) {} }

  await _emitAdminOnlyChatNote(user.id, user.username,
    `🏦 ✅ Transferencia OK (${dataDesc}) — 🎮 ESPERANDO que el cliente elija dónde jugar (${optsTxt}). ` +
    `Si no elige en ${timeoutMin} min se carga sola en ${platforms.labelOf(await platforms.resolveDefaultFor(user))}. ` +
    `Podés elegir por él desde el banner del chat.`);
  try { notifyAdmins('platform_choice_pending', { userId: user.id, username: user.username, movementId: movement.movementId, amount, options, expiresAt }); } catch (_) {}
  _emitHgcashUpdate('esperando_plataforma');
  logger.info(`[platforms] pregunta enviada user=${user.username} $${amount} mov=${movement.movementId} opciones=${options.map((o) => o.id).join(',')} timeout=${timeoutMin}min`);
}

// El cliente eligió una plataforma SIN API conectada (hoy: Ganamos) → NO se carga
// acá. Se lo manda al link externo de esa plataforma (Config['platforms'].items.<id>
// .externalUrl) y el movimiento queda `redirected` (consumido: nadie lo carga por
// error). Cuando la API se conecte, este camino deja de usarse solo.
async function _platformRedirectUser({ movement, comprobante, user, platformId, by, dataDesc }) {
  const amount = Number(movement.amount);
  const all = await platforms.listAll();
  const p = all.find((x) => x.id === platformId) || { id: platformId, name: platformId, emoji: '🎮', externalUrl: '' };
  const url = p.externalUrl || '';
  await BankMovement.updateOne({ movementId: movement.movementId }, {
    $set: { matchStatus: 'redirected', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id,
      platform: platformId, platformChosenAt: new Date(), platformChoiceBy: String(by || 'user').slice(0, 60), redirectedUrl: url || null, chargedAt: null }
  });
  await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'redirected', matchedMovementId: movement.movementId } });
  try { await User.updateOne({ id: user.id }, { $set: { lastPlatform: platformId } }); } catch (_) {}
  try { await _resolvePlatformChoiceMessage(movement, platformId); } catch (_) {}

  const label = `${p.emoji} ${p.name}`;
  const content = await renderSystemCommand('/sys_platform_redirect',
    url
      ? '{platform} ¡Buenísimo! Para jugar en {name} entrá acá 👉 {url}\n\nAhí te cargan tu transferencia de ${amount}. 🎮'
      : '{platform} ¡Buenísimo! Elegiste {name}. En un momento un agente te contacta para cargarte tu transferencia de ${amount}. 🎮',
    { platform: p.emoji, name: p.name, url, amount: amount.toLocaleString('es-AR') });
  const metadata = url ? { kind: 'platform_link', platform: platformId, name: p.name, emoji: p.emoji, url } : null;
  if (content) {
    await _sendUserSystemMessage(user, content, { metadata, push: { title: `${label} · Entrá a jugar`, body: url ? `Tocá para entrar a ${p.name}` : `Elegiste ${p.name}`, data: { tag: 'platform_redirect', url } } });
  }
  await _emitAdminOnlyChatNote(user.id, user.username,
    `🏦 ➡️ Transferencia (${dataDesc}) DERIVADA a ${label}${url ? ' — se le mandó el link ' + url : ' — ⚠️ sin link configurado: contactalo'}. ` +
    `${p.name} NO tiene API conectada: acá NO se cargó nada (el movimiento queda consumido como "derivado"). Si hay que cargarla en esta sala igual, hacelo MANUAL.`);
  _emitHgcashUpdate('derivado');
  logger.info(`[platforms] derivado user=${user.username} $${amount} mov=${movement.movementId} → ${platformId} url=${url || '-'} by=${by}`);
}

// Marca el mensaje con botones como RESUELTO (metadata.chosen) para que la PWA deje
// de mostrar las opciones aunque recargue, y avisa por socket al cliente.
async function _resolvePlatformChoiceMessage(movement, platformId) {
  const msgId = movement && movement.platformChoiceMsgId;
  let mid = msgId;
  if (!mid && movement && movement.movementId) {
    const fresh = await BankMovement.findOne({ movementId: movement.movementId }).select('platformChoiceMsgId matchedUserId').lean();
    mid = fresh && fresh.platformChoiceMsgId;
  }
  if (!mid) return;
  const m = await Message.findOneAndUpdate({ id: mid }, { $set: { 'metadata.chosen': platformId, 'metadata.chosenAt': new Date().toISOString() } }, { new: true }).lean();
  if (m) {
    io.to(`user_${m.receiverId}`).emit('platform_choice_resolved', { messageId: mid, movementId: movement.movementId, platform: platformId });
    io.to(`chat_${m.receiverId}`).emit('platform_choice_resolved', { messageId: mid, movementId: movement.movementId, platform: platformId });
  }
}

// Resuelve la elección de un movimiento `awaiting_platform` (cliente / agente /
// timeout). Claim atómico (awaiting_platform → claiming) para que dos instancias (o
// un doble toque) no carguen dos veces. Devuelve { ok, platform, redirected, url } o
// { ok:false, code: 'not_pending' | 'not_yours' | 'invalid_platform' | 'error' }.
async function _resolvePlatformChoice({ movementId, platformId, by, requireUserId = null }) {
  const pid = platforms.normalizeId(platformId);
  if (!pid) return { ok: false, code: 'invalid_platform' };
  const enabled = await platforms.listEnabled();
  const plat = enabled.find((p) => p.id === pid);
  if (!plat && by === 'user') return { ok: false, code: 'invalid_platform' }; // el cliente sólo elige entre las ofrecidas
  const q = { movementId: String(movementId || ''), matchStatus: 'awaiting_platform' };
  if (requireUserId) q.matchedUserId = requireUserId;
  const mov = await BankMovement.findOneAndUpdate(q,
    { $set: { matchStatus: 'claiming', platform: pid, platformChosenAt: new Date(), platformChoiceBy: String(by || 'user').slice(0, 60) } },
    { new: true }).lean();
  if (!mov) {
    const exists = await BankMovement.findOne({ movementId: String(movementId || '') }).select('matchStatus matchedUserId platform').lean();
    if (!exists) return { ok: false, code: 'not_pending' };
    if (requireUserId && exists.matchedUserId !== requireUserId) return { ok: false, code: 'not_yours' };
    return { ok: false, code: 'not_pending', status: exists.matchStatus, platform: exists.platform || null };
  }
  const comprobante = mov.matchedComprobanteId ? await Comprobante.findOne({ id: mov.matchedComprobanteId }).lean() : null;
  const user = await User.findOne({ id: mov.matchedUserId });
  if (!user || !comprobante) {
    await BankMovement.updateOne({ movementId: mov.movementId }, { $set: { matchStatus: 'error', chargeError: !user ? 'usuario no encontrado' : 'comprobante no encontrado' } });
    return { ok: false, code: 'error' };
  }
  try {
    await _hgcashCreditToPlatform({ movement: mov, comprobante, user, platformId: pid, by });
  } catch (e) {
    logger.error(`[platforms] resolver elección mov=${movementId} → ${pid} falló: ${e.message}`);
    return { ok: false, code: 'error' };
  }
  const after = await BankMovement.findOne({ movementId: mov.movementId }).select('matchStatus redirectedUrl platform').lean();
  return { ok: true, platform: pid, redirected: !!(after && after.matchStatus === 'redirected'), url: (after && after.redirectedUrl) || null, status: after && after.matchStatus };
}

// Cron (60 s, cada instancia): preguntas vencidas → se cargan solas en la última
// plataforma elegida por el cliente (o la default). Idempotente por el claim atómico
// de _resolvePlatformChoice (awaiting_platform → claiming).
async function _platformChoiceTick() {
  try {
    const s = await platforms.getSettings();
    const limit = new Date(Date.now() - (Number(s.askTimeoutMin) || 10) * 60 * 1000);
    const due = await BankMovement.find({ matchStatus: 'awaiting_platform', platformAskedAt: { $lte: limit } })
      .select('movementId matchedUserId amount matchedUsername').limit(20).lean();
    for (const m of due) {
      try {
        const u = m.matchedUserId ? await User.findOne({ id: m.matchedUserId }).select('id username lastPlatform').lean() : null;
        const pid = await platforms.resolveDefaultFor(u);
        const r = await _resolvePlatformChoice({ movementId: m.movementId, platformId: pid, by: 'timeout' });
        logger.info(`[platforms] timeout mov=${m.movementId} user=${m.matchedUsername} → ${pid}: ${r.ok ? (r.redirected ? 'derivado' : 'cargado') : r.code}`);
      } catch (e) {
        logger.warn(`[platforms] timeout mov=${m.movementId}: ${e.message}`);
      }
    }
  } catch (e) {
    logger.warn(`[platforms] tick falló: ${e.message}`);
  }
}

// ── CARGA A UNA PLATAFORMA CONCRETA (segunda mitad de la auto-carga) ────────
// Se llama con la plataforma YA decidida (directo, elección del cliente, del agente
// o timeout). El movimiento tiene que estar reclamado (`claiming`). Si la plataforma
// NO tiene API conectada (ej. Ganamos hoy) → `_platformRedirectUser` (link externo,
// NO se mueve plata acá). Si la tiene → candado por coelsa + red de seguridad +
// depósito por el ADAPTADOR de esa plataforma (misma reference `vip-hg-*`).
async function _hgcashCreditToPlatform({ movement, comprobante, user, platformId, by = 'direct' }) {
  const amount = movement.amount;
  const opDesc = `op. hgcash ${movement.coelsaCode || movement.externalId || movement.movementId}`;
  const dataDesc = `$${Number(amount).toLocaleString('es-AR')} · ${movement.fromName || movement.fromCBU || 's/origen'} · ${opDesc}`;
  const pid = platforms.normalizeId(platformId) || platforms.DEFAULT_ID;
  const adapter = platforms.getAdapter(pid) || girox;
  const platLabel = platforms.labelOf(pid);

  // Registrar la decisión (sirve para el panel y para reconciliar).
  try {
    await BankMovement.updateOne({ movementId: movement.movementId },
      { $set: { platform: pid, platformChosenAt: new Date(), platformChoiceBy: String(by || 'direct').slice(0, 60) } });
  } catch (_) {}

  // Plataforma SIN API conectada → el cliente se maneja afuera (link externo).
  if (typeof adapter.isConnected === 'function' && !adapter.isConnected()) {
    await _platformRedirectUser({ movement, comprobante, user, platformId: pid, by, dataDesc });
    return;
  }

  // ── IDEMPOTENCIA POR TRANSFERENCIA REAL (coelsa) ─────────────────────────
  // Candado ATÓMICO entre instancias: la MISMA transferencia (mismo coelsaCode)
  // se acredita UNA sola vez, sin importar cuántos movimientos/comprobantes haya.
  // Si hgcash reenvía el movimiento con otro id (o hay 2 docs del mismo recibo),
  // el segundo intento choca con el índice único y NO se carga de nuevo.
  const chargeKey = String(movement.coelsaCode || movement.externalId || '').trim();
  let chargeLocked = false;
  if (chargeKey) {
    try {
      await HgcashCharge.create({
        chargeKey, userId: user.id, username: user.username,
        amount: Number(amount), movementId: movement.movementId, comprobanteId: comprobante.id, platform: pid
      });
      chargeLocked = true;
    } catch (lockErr) {
      if (lockErr && lockErr.code === 11000) {
        // Esta transferencia YA fue acreditada → NO recargar (duplicado real).
        await BankMovement.updateOne({ movementId: movement.movementId },
          { $set: { matchStatus: 'duplicate', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id, chargeError: `duplicado: coelsa ${chargeKey} ya acreditada` } });
        await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'duplicate' } });
        await _emitAdminOnlyChatNote(user.id, user.username,
          `🏦 ⚠️ Movimiento DUPLICADO de la misma transferencia (coelsa ${chargeKey}) — NO se cargó de nuevo (ya estaba acreditado).`);
        logger.warn(`[hgcash] DUPLICADO bloqueado coelsa=${chargeKey} user=${user.username} mov=${movement.movementId}`);
        return;
      }
      // Otro error de DB: no bloqueamos la carga por eso (la red de seguridad de abajo igual protege).
      logger.warn(`[hgcash] no se pudo crear el candado de carga (coelsa=${chargeKey}): ${lockErr.message}`);
    }
  }

  // ── RED DE SEGURIDAD ─────────────────────────────────────────────────────
  // ¿Ya hubo una carga del MISMO monto a este usuario hace pocos minutos (manual
  // o automática)? Cubre el caso "el agente cargó a mano y DESPUÉS llega el aviso
  // del banco" (no hay coelsa que linkee la manual) y cualquier duplicado sin
  // coelsa confiable. No carga sola: la deja para revisión manual (nunca pierde
  // plata, sólo pide confirmar si son 2 transferencias reales).
  try {
    const _hgCfg = await getHgcashConfig();
    const guardMin = Number(_hgCfg.duplicateGuardMinutes) >= 0 ? Number(_hgCfg.duplicateGuardMinutes) : 8;
    if (guardMin > 0) {
      const sinceGuard = new Date(Date.now() - guardMin * 60 * 1000);
      const recent = await Transaction.findOne({
        userId: user.id, type: 'deposit', amount: Number(amount), timestamp: { $gte: sinceGuard }
      }).lean();
      if (recent) {
        if (chargeLocked) { try { await HgcashCharge.deleteOne({ chargeKey }); } catch (_) {} }
        await BankMovement.updateOne({ movementId: movement.movementId },
          { $set: { matchStatus: 'needs_review', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id, chargeError: `posible duplicado: ya hubo carga de $${Number(amount)} hace <${guardMin}min` } });
        await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'needs_review' } });
        await _emitAdminOnlyChatNote(user.id, user.username,
          `🏦 ⚠️ POSIBLE DUPLICADO — a este cliente ya se le cargó $${Number(amount).toLocaleString('es-AR')} hace pocos minutos. NO se cargó automático.\nVerificá si son DOS transferencias REALES (dos comprobantes con N° distinto) y, si corresponde, cargá a mano.`);
        logger.warn(`[hgcash] HOLD posible duplicado user=${user.username} $${amount} mov=${movement.movementId}`);
        return;
      }
    }
  } catch (guardErr) {
    logger.warn(`[hgcash] red de seguridad falló (sigue la carga): ${guardErr.message}`);
  }

  // Modo auto: cargar de verdad en la plataforma.
  let charged = false; // true una vez que la acreditación se confirmó (evita reintentos que dupliquen)
  try {
    // Idempotencia en 1girox: la reference sale del identificador del MOVIMIENTO
    // BANCARIO (el coelsa del candado, o el id del movimiento). Es estable entre
    // reintentos y única por transferencia → si un reintento repite la carga, la
    // plataforma responde duplicate:true y NO acredita dos veces. Es la misma
    // garantía que ya daba `chargeKey` en nuestra base, ahora también del otro lado.
    const _ref = `vip-hg-${chargeKey || movement.movementId}`;
    // BONO AUTOMÁTICO (#210): el bono en % pendiente entra junto con la carga.
    const _reuse = await _cbuReuseCheck(user, movement); // #509
    const _auto = await resolveAutoBonus(user, Number(amount), 'auto-hgcash', { noWelcome: !!_reuse });
    const result = await _depositWithBonus(adapter, user.username, Number(amount), 'Carga automática (hgcash)', _ref, _auto.bonus); // #839
    if (!result.success) {
      if (_auto.claimed) await _auto.revert();
      if (chargeLocked) { try { await HgcashCharge.deleteOne({ chargeKey }); } catch (_) {} }
      await hgcashHandleChargeFailure(movement, comprobante, result.error || 'fallo deposit', dataDesc, user);
      return;
    }

    await BankMovement.updateOne({ movementId: movement.movementId }, {
      $set: { matchStatus: 'auto_charged', matchedUserId: user.id, matchedUsername: user.username, matchedComprobanteId: comprobante.id, chargedAt: new Date() }
    });
    await Comprobante.updateOne({ id: comprobante.id }, { $set: { bankMatchStatus: 'auto_charged', matchedMovementId: movement.movementId, autoCharged: true, reviewStatus: 'confirmed', reviewResolution: 'auto', reviewedBy: 'auto', reviewedAt: new Date() } }); // #376
    _emitDepositReviewUpdate(user.id, { action: 'confirmed', id: comprobante.id });
    charged = true; // ya acreditó: cualquier error posterior NO debe disparar reintento
    _depositReviewCloseRepeats(comprobante, 'auto', 'acreditó solo').catch(() => {}); // #908
    // Multi-plataforma: recordar dónde cargó (fallback de la próxima pregunta / timeout).
    try { await User.updateOne({ id: user.id }, { $set: { lastPlatform: pid } }); } catch (_) {}
    try { await _resolvePlatformChoiceMessage(movement, pid); } catch (_) {}
    // Carga OK pero el bono adjunto falló → el bono vuelve a quedar pendiente.
    const _hgBonusApplied = _auto.bonus > 0 && !result.bonusFailed;
    if (_auto.claimed && !_hgBonusApplied) { await _auto.revert(); logger.error(`[auto-bonus] hgcash user=${user.username}: la carga entró pero el bono adjunto $${_auto.bonus} FALLÓ — vuelve a pendiente`); }
    if (_hgBonusApplied) { try { await adapter.claimPendingBonus(user.username); } catch (_) {} }

    try { await recordUserActivity(user.id, 'deposit', Number(amount)); } catch (_) {}
    const txId = uuidv4(); // #562: id del depósito (event_id estable del webhook)
    await Transaction.create({
      id: txId, type: 'deposit', platform: pid, amount: Number(amount),
      bonus: _hgBonusApplied ? _auto.bonus : 0,
      username: user.username, userId: user.id,
      description: `Carga automática hgcash (${opDesc})${_hgBonusApplied ? ' + bono automático ' + _auto.label : ''}`,
      adminUsername: 'auto-hgcash', adminRole: 'system',
      transactionId: result.data?.transfer_id || result.data?.transferId,
      metadata: { source: 'auto_hgcash', movementId: movement.movementId, comprobanteId: comprobante.id, platform: pid, platformChoiceBy: by },
      timestamp: new Date()
    });
    // Bonificación como Transaction PROPIA (type 'bonus'), igual que la carga manual:
    // sin esto el dashboard de Transacciones mostraba Bonificaciones $0 / Total regalos
    // $0 aunque en 1girox el bono figuraba (owner 2026-09-30, caso gxFranco896).
    if (_hgBonusApplied) {
      await Transaction.create({
        id: uuidv4(), type: 'bonus', platform: pid, amount: Number(_auto.bonus),
        username: user.username, userId: user.id,
        description: `Bonificación incluida en carga automática hgcash de $${Number(amount).toLocaleString('es-AR')} — automática: ${_auto.label}`,
        adminUsername: 'auto-hgcash', adminRole: 'system',
        transactionId: result.data?.transfer_id || result.data?.transferId,
        metadata: { source: _auto.source || 'auto_bonus', movementId: movement.movementId, autoBonus: { pct: _auto.pct, rule: _auto.rule } },
        timestamp: new Date()
      }).catch((e) => logger.warn(`[auto-bonus] hgcash: no se pudo registrar la Transaction del bono (${user.username}): ${e.message}`));
    }

    // Mensaje al cliente (usa /sys_deposit si está; si no, fallback).
    let newBalance = null;
    try {
      const balRes = await adapter.getUserBalanceWithRetry(user.username);
      if (balRes.success) newBalance = balRes.balance;
    } catch (_) {}
    const balStr = newBalance !== null ? `$${newBalance}` : 'actualizándose 🔄';
    const depositCmd = await Command.findOne({ name: _hgBonusApplied ? '/sys_deposit_bonus' : '/sys_deposit', isActive: true });
    const depositTpl = resolveSysContent(depositCmd, _hgBonusApplied
      ? `🔒💰 Depósito de $${Number(amount).toLocaleString('es-AR')} (incluye $${Number(_auto.bonus).toLocaleString('es-AR')} de bonificación) acreditado con éxito. ✅\n💸 Tu nuevo saldo es ${balStr} 💸`
      : `🔒💰 Depósito de $${Number(amount).toLocaleString('es-AR')} acreditado con éxito. ✅\n💸 Tu nuevo saldo es ${balStr} 💸`);
    if (depositTpl) { // null = comando vaciado a propósito → no enviar mensaje al cliente
      const clientMsg = depositTpl.replace(/\{amount\}/g, Number(amount)).replace(/\{bonus\}/g, _hgBonusApplied ? _auto.bonus : 0).replace(/\{pct\}/g, _hgBonusApplied ? _auto.pct : 0).replace(/\{balance\}/g, newBalance !== null ? newBalance : 'actualizándose');
      // #275: metadata para el cartel "Jugar ahora" de la PWA (abre la plataforma adentro de la app).
      const _depMeta = { kind: 'deposit_credited', platform: pid, amount: Number(amount), bonus: _hgBonusApplied ? Number(_auto.bonus) : 0 };
      const sysMsg = await Message.create({
        id: uuidv4(), senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin',
        receiverId: user.id, receiverRole: 'user', content: clientMsg, type: 'system', timestamp: new Date(), read: false, metadata: _depMeta
      });
      const msgData = { id: sysMsg.id, senderId: 'admin', senderUsername: 'Sistema', senderRole: 'admin', receiverId: user.id, receiverRole: 'user', content: clientMsg, timestamp: new Date(), type: 'system', metadata: _depMeta };
      io.to(`user_${user.id}`).emit('new_message', msgData);
      io.to(`chat_${user.id}`).emit('new_message', msgData);
      notifyAdmins('new_message', { message: msgData, userId: user.id, username: user.username });
    }
    // Por ROOM (no el Map local): con multi-instancia, el Map solo ve los
    // sockets de ESTA instancia — el room cruza instancias vía el adapter Redis.
    if (newBalance !== null) io.to(`user_${user.id}`).emit('balance_updated', { balance: newBalance });

    // SLA: la auto-carga ES la respuesta al cliente → frena el reloj de demoras
    // (antes quedaba como "sin respuesta" porque la carga es automática, no un agente).
    try { await delayClockResolve(user.id, { responded: true, agentId: 'auto-hgcash', agentUsername: 'auto-hgcash', via: 'auto_carga', queueHint: 'cargas' }); } catch (_) {}
    // Oferta de recuperación 100% (no se envía si está etiquetado comunidad/no comunidad).
    await maybeSendRecoveryMessage(user);
    // #283: en la PRIMERA carga de un cliente sin la app → oferta de carga GRATIS por instalarla.
    if (!_reuse && !_isFlagged(user)) await maybeOfferInstallGift(user, { amount, platform: pid, source: 'hgcash' }); // #509

    await _emitAdminOnlyChatNote(user.id, user.username, `🏦 ✅ CARGA AUTOMÁTICA hgcash — ${dataDesc}. Acreditado en ${platLabel}${by && by !== "single" && by !== "direct" ? " (elección: " + by + ")" : ""}.`);
    if (_hgBonusApplied) await _emitAdminOnlyChatNote(user.id, user.username, _autoBonusNoteText(_auto, Number(amount), 0, 'carga automática hgcash')).catch(() => {});
    // #562 webhooks salientes (B): auto-carga por banco
    try {
      const _hgFTD = await _isFirstDeposit(user.id);
      outboundWebhook.notify('carga', user, { amount: Number(amount), firstDeposit: _hgFTD, transactionId: txId });
      try { io.to(`user_${user.id}`).emit('deposit_credited', { amount: Number(amount), firstDeposit: !!_hgFTD }); } catch (_) {} // #712: cartel "Buena suerte" en el casino
    } catch (_) {}
    _emitHgcashUpdate('cargado');
    _chatAutoCloseIfHandled(user.id, 'carga acreditada sola').catch(() => {}); // #895
    logger.info(`[hgcash] auto-carga OK user=${user.username} amount=$${amount} movement=${movement.movementId} platform=${pid} by=${by}`);
  } catch (e) {
    if (charged) {
      // La carga YA se acreditó; el error fue en un paso posterior (mensaje/transacción).
      // NO reintentar (sería doble carga). Solo dejamos constancia.
      logger.error(`[hgcash] carga OK pero falló paso posterior user=${user.username}: ${e.message}`);
    } else {
      // La carga no llegó a confirmarse → liberar el candado y dejarlo reintentable.
      if (chargeLocked) { try { await HgcashCharge.deleteOne({ chargeKey }); } catch (_) {} }
      await hgcashHandleChargeFailure(movement, comprobante, e.message, dataDesc, user);
      logger.error(`[hgcash] auto-carga excepción user=${user.username}: ${e.message}`);
    }
  }
}

// Desde un MOVIMIENTO entrante (webhook): SOLO red de seguridad para el caso raro en
// que el comprobante llegó segundos ANTES que el aviso del banco. Usa una ventana
// CORTA (raceWindowMinutes) para NO cargar contra comprobantes viejos/sobrantes — el
// disparador principal es el comprobante (hgcashMatchFromComprobante). Match por
// MONTO + NOMBRE de origen. Si hay varios candidatos (ambigüedad) → NO carga.
async function hgcashMatchFromMovement(movement) {
  try {
    const cfg = await getHgcashConfig();
    if (!cfg.enabled) return;
    if (!movement || movement.direction !== 'Inbound' || movement.matchStatus !== 'pending') return;
    if (!_statusAccredited(movement.status, cfg)) return; // todavía no acreditado (status != done)
    if (cfg.currency && movement.currency && String(movement.currency).toUpperCase() !== String(cfg.currency).toUpperCase()) return;

    // Ventana CORTA: solo comprobantes enviados en los últimos raceWindowMinutes.
    const raceMin = Math.min(cfg.windowMinutes || 60, cfg.raceWindowMinutes || 10);
    const since = new Date(Date.now() - raceMin * 60 * 1000);
    const candidates = await Comprobante.find({
      isComprobante: true,
      autoCharged: { $ne: true },
      status: { $ne: 'duplicate' }, // un comprobante re-enviado/duplicado NO es objetivo de carga
      bankMatchStatus: { $in: ['none', 'pending'] },
      reviewStatus: { $nin: ['confirmed', 'rejected'] }, // #820: lo que ya resolvió un agente no se vuelve a cargar
      createdAt: { $gte: since }
    }).sort({ createdAt: -1 }).limit(80).lean();

    const matches = candidates.filter(c => _comprobanteMatchesMovement(c, movement, cfg));
    if (matches.length === 0) {
      // Diagnóstico: por qué no matcheó (para ver en los logs de Render).
      const resumen = candidates.slice(0, 8).map(c => `$${c.amount}/op:${c.operationNumber || '?'}/"${c.originHolder || '?'}"`).join(' , ');
      logger.info(`[hgcash] movimiento SIN match: $${movement.amount} de "${movement.fromName}" coelsa=${movement.coelsaCode || '-'} (status=${movement.status}). ${candidates.length} comprobantes en ventana: ${resumen}`);
      return; // queda pending; un comprobante posterior puede matchearlo
    }
    if (matches.length > 1) {
      logger.warn(`[hgcash] AMBIGUO: ${matches.length} comprobantes coinciden con movimiento ${movement.movementId} ($${movement.amount} de ${movement.fromName}). No se auto-carga.`);
      notifyAdmins('hgcash_ambiguous', { movementId: movement.movementId, amount: movement.amount, fromName: movement.fromName, count: matches.length });
      return;
    }
    await hgcashAutoCarga({ movement, comprobante: matches[0], mode: cfg.mode });
  } catch (e) {
    logger.warn(`[hgcash] match desde movimiento falló: ${e.message}`);
  }
}

// Desde un COMPROBANTE recién recibido: si fue a NUESTRA cuenta hgcash, buscar un
// movimiento entrante que coincida por MONTO + NOMBRE de origen + ventana de tiempo.
async function hgcashMatchFromComprobante(comprobante) {
  try {
    const cfg = await getHgcashConfig();
    if (!cfg.enabled) return;
    if (!comprobante || !comprobante.isComprobante || comprobante.autoCharged) return;

    // Buscamos un movimiento entrante que corresponda (por N° de transacción/coelsa,
    // o por nombre de origen + destino). NO dependemos de la config de cuenta: el
    // match se valida contra el movimiento real (sirve para cualquier banco/cuenta).
    const since = new Date(Date.now() - (cfg.windowMinutes || 60) * 60 * 1000);
    const candidates = await BankMovement.find({
      direction: 'Inbound', matchStatus: 'pending', createdAt: { $gte: since }
    }).sort({ createdAt: -1 }).limit(80).lean();

    const matches = candidates.filter(m =>
      _statusAccredited(m.status, cfg) &&
      _comprobanteMatchesMovement(comprobante, m, cfg)
    );
    if (matches.length === 0) {
      logger.info(`[hgcash] comprobante SIN movimiento aún: $${comprobante.amount} op=${comprobante.operationNumber || '-'} de "${comprobante.originHolder || '?'}" — ${candidates.length} movimientos pendientes en ventana`);
      return; // todavía no llegó el movimiento; el webhook lo matcheará al llegar
    }
    if (matches.length > 1) {
      logger.warn(`[hgcash] AMBIGUO: ${matches.length} movimientos coinciden con comprobante ${comprobante.id}. No se auto-carga.`);
      await _emitAdminOnlyChatNote(comprobante.userId, comprobante.username,
        `🏦 Hay ${matches.length} transferencias que coinciden con este comprobante (mismo monto y nombre en la ventana). Verificá y cargá a mano.`);
      return;
    }
    await hgcashAutoCarga({ movement: matches[0], comprobante, mode: cfg.mode });
  } catch (e) {
    logger.warn(`[hgcash] match desde comprobante falló: ${e.message}`);
  }
}

// Webhook de hgcash: movimientos de cuenta (acreditaciones entrantes). SIN
// authMiddleware (lo llama el banco). Valida firma HMAC sobre el body CRUDO,
// guarda el movimiento (dedupe por id), responde 2xx rápido y matchea en
// segundo plano. NUNCA carga si la config está apagada (modo sombra por defecto).
// ============================================
// #320 CREDENCIALES hgcash desde el PANEL (token de API + secreto del webhook)
// ============================================
// Owner: que un cambio de cuenta hgcash (se cae una, cambia el titular) lo pueda hacer un
// admin desde el panel, sin entrar a AWS SSM. Se guardan CIFRADAS (AES-256-GCM, clave
// derivada de JWT_SECRET, que ya vive en SSM) en Config['hgcashCredentials']; un dump de la
// base no las expone. Cada instancia las carga en memoria al arrancar y cada 60 s.
// Prioridad: panel > SSM. El webhook acepta la firma con CUALQUIERA de los dos secretos
// (panel o SSM) → durante el cambio de cuenta no se pierde ningún aviso.
// ⚠️ Si JWT_SECRET cambia, lo guardado no se puede descifrar → se usa SSM (y el panel avisa).
let _hgcashPanelSecret = null;
let _hgcashCredMeta = null; // { tokenLast4, secretLast4, updatedBy, updatedAt, decryptError }
// ¿Es la PRIMERA carga real del cliente (FTD)? Se llama DESPUÉS de crear el
// Transaction del depósito, así que la primera carga = exactamente 1 depósito
// real. Excluye devoluciones de retiro (payout_refund), que no son cargas
// genuinas. Lo usan los webhooks salientes (#197): el destino recibe 'carga' con
// firstDeposit como 'primera_carga'. `opts.unrecorded` = el flujo que llama NO
// escribe Transaction (self-service): entonces FTD = ningún depósito previo.
// Ante error → false (no marcar FTD de más).
async function _isFirstDeposit(userId, opts) {
  try {
    const n = await Transaction.countDocuments({
      userId: String(userId),
      type: 'deposit',
      'metadata.source': { $ne: 'payout_refund' }
    });
    return opts && opts.unrecorded ? n === 0 : n === 1;
  } catch (e) {
    logger.warn(`[webhooks] _isFirstDeposit falló: ${e.message}`);
    return false;
  }
}

// ===== #197 Webhooks salientes (Config['outboundWebhooks']) — réplica del #334/#346 del gemelo =====
// Lista de destinos; el secreto se guarda cifrado (misma clave que las credenciales
// de hgcash, #192: _credEncrypt/_credDecrypt) y se descifra sólo en memoria para firmar.
const OUTBOUND_WEBHOOKS_KEY = 'outboundWebhooks';
const OUTBOUND_WEBHOOKS_MAX = 10;
const OUTBOUND_WEBHOOKS_TTL_MS = 60 * 1000;
let _outboundWebhooksCache = null;
function _normalizeOutboundDest(d, cur) {
  const c = cur || {};
  const events = d.events && typeof d.events === 'object' ? d.events : (c.events || {});
  const fields = d.fields && typeof d.fields === 'object' ? d.fields : (c.fields || {});
  const url = d.url !== undefined ? String(d.url || '').trim() : (c.url || '');
  return {
    id: c.id || d.id || ('wh_' + crypto.randomBytes(5).toString('hex')),
    name: d.name !== undefined ? String(d.name || '').trim().slice(0, 60) : (c.name || ''),
    url,
    secretEnc: (typeof d.secret === 'string' && d.secret.trim()) ? _credEncrypt(d.secret.trim()) : (c.secretEnc || null),
    enabled: typeof d.enabled === 'boolean' ? d.enabled : (c.enabled !== false),
    scope: d.scope === 'publishers' ? 'publishers' : (d.scope === 'all' ? 'all' : (c.scope || 'all')),
    publishers: Array.isArray(d.publishers) ? d.publishers.map((p) => String(p || '').trim()).filter(Boolean).slice(0, 50) : (c.publishers || []),
    events: {
      registro: events.registro !== false,           // siempre por defecto
      primera_carga: events.primera_carga !== false, // siempre por defecto
      carga: events.carga === true,                  // OPCIONAL
      retiro: events.retiro === true                 // OPCIONAL
    },
    fields: { atribucion: fields.atribucion === true, contacto: fields.contacto === true }, // OPCIONALES
    // Cómo se autentica el aviso ante el receptor. Siempre van los headers
    // X-Webhook-*; `auth` agrega lo que pide cada plataforma:
    //   hmac_ts   (default) X-Webhook-Signature = HMAC(ts.body)  — nuestro esquema
    //   hmac_body <header> = <prefix>HMAC-SHA256 hex del body solo (estilo GitHub/Shopify)
    //   bearer    Authorization: Bearer <secreto>
    //   header    <header>: <secreto>  (API key fija)
    auth: (() => {
      const a = d.auth && typeof d.auth === 'object' ? d.auth : (c.auth || {});
      const mode = ['hmac_ts', 'hmac_body', 'bearer', 'header'].includes(a.mode) ? a.mode : 'hmac_ts';
      const header = String(a.header || '').trim().replace(/[^A-Za-z0-9-]/g, '').slice(0, 60);
      const prefix = String(a.prefix || '').trim().slice(0, 20);
      return { mode, header: header || null, prefix: prefix || null };
    })(),
    createdAt: c.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
}
async function _getOutboundWebhooks(opts) {
  const now = Date.now();
  if (!(opts && opts.fresh) && _outboundWebhooksCache && (now - _outboundWebhooksCache.at) < OUTBOUND_WEBHOOKS_TTL_MS) return _outboundWebhooksCache.value;
  const raw = await getConfig(OUTBOUND_WEBHOOKS_KEY, null);
  const list = raw && Array.isArray(raw.destinations) ? raw.destinations : [];
  const value = list.map((d) => {
    let secret = null, decryptError = false;
    if (d.secretEnc) { try { secret = _credDecrypt(d.secretEnc); } catch (_) { decryptError = true; } }
    return Object.assign({}, d, { secret, decryptError });
  });
  _outboundWebhooksCache = { at: now, value };
  return value;
}
async function _saveOutboundWebhooks(list, by) {
  const clean = list.map((d) => { const o = Object.assign({}, d); delete o.secret; delete o.decryptError; return o; });
  await Config.set(OUTBOUND_WEBHOOKS_KEY, { destinations: clean }, by);
  _outboundWebhooksCache = null;
}
function _outboundDestPublic(d, stats, pending) {
  const o = Object.assign({}, d);
  delete o.secretEnc; delete o.secret;
  o.hasSecret = !!d.secretEnc;
  o.stats = stats || null;
  o.pending = pending || 0;
  return o;
}


function _credKey() {
  const base = process.env.JWT_SECRET || JWT_SECRET || '';
  if (!base) return null;
  return crypto.createHash('sha256').update(base + ':hgcash-credentials:v1').digest();
}
function _credEncrypt(plain) {
  const key = _credKey(); if (!key) throw new Error('JWT_SECRET no disponible para cifrar');
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv('aes-256-gcm', key, iv);
  const enc = Buffer.concat([c.update(String(plain), 'utf8'), c.final()]);
  return [iv.toString('base64'), c.getAuthTag().toString('base64'), enc.toString('base64')].join('.');
}
function _credDecrypt(blob) {
  const key = _credKey(); if (!key || !blob) return null;
  const [iv, tag, data] = String(blob).split('.');
  const d = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'base64'));
  d.setAuthTag(Buffer.from(tag, 'base64'));
  return Buffer.concat([d.update(Buffer.from(data, 'base64')), d.final()]).toString('utf8');
}
async function _loadHgcashCredentials() {
  try {
    const v = await getConfig('hgcashCredentials', null);
    if (!v || (!v.tokenEnc && !v.secretEnc)) {
      hgcashPay.setTokenOverride(null); _hgcashPanelSecret = null; _hgcashCredMeta = null; return;
    }
    let token = null, secret = null, decryptError = false;
    try { token = v.tokenEnc ? _credDecrypt(v.tokenEnc) : null; } catch (_) { decryptError = true; }
    try { secret = v.secretEnc ? _credDecrypt(v.secretEnc) : null; } catch (_) { decryptError = true; }
    hgcashPay.setTokenOverride(token);
    _hgcashPanelSecret = secret || null;
    _hgcashCredMeta = { tokenLast4: v.tokenLast4 || null, secretLast4: v.secretLast4 || null, updatedBy: v.updatedBy || null, updatedAt: v.updatedAt || null, decryptError };
    if (decryptError) logger.error('[hgcash] credenciales del panel NO se pudieron descifrar (¿cambió JWT_SECRET?) — se usa SSM');
  } catch (e) { logger.warn(`[hgcash] no se pudieron leer las credenciales del panel: ${e.message}`); }
}
setTimeout(() => { _loadHgcashCredentials(); }, 8 * 1000);
setInterval(() => { _loadHgcashCredentials(); }, 60 * 1000);
// #310 (owner 2026-10-17): API de 1girox (Base URL + X-Api-Key) desde el PANEL, igual que hgcash. Cifradas con la
// misma clave derivada de JWT_SECRET en Config['giroxCredentials']; panel > env/SSM. Sirve para entornos (Render,
// clon) donde no se pueden tocar las variables: se carga la key y en ≤ 60 s todas las instancias la usan.
let _giroxCredMeta = null;
async function _loadGiroxCredentials() {
  try {
    const v = await getConfig('giroxCredentials', null);
    if (!v || !v.keyEnc || !v.baseUrl) { girox.setCredentialsOverride(null); _giroxCredMeta = null; return; }
    let key = null, decryptError = false;
    try { key = _credDecrypt(v.keyEnc); } catch (_) { decryptError = true; }
    girox.setCredentialsOverride(key ? { baseUrl: v.baseUrl, apiKey: key } : null);
    _giroxCredMeta = { baseUrl: v.baseUrl, keyLast4: v.keyLast4 || null, updatedBy: v.updatedBy || null, updatedAt: v.updatedAt || null, decryptError };
    if (decryptError) logger.error('[girox] la API key del panel NO se pudo descifrar (¿cambió JWT_SECRET?) — se usa env/SSM');
  } catch (e) { logger.warn(`[girox] no se pudieron leer las credenciales del panel: ${e.message}`); }
}
setTimeout(() => { _loadGiroxCredentials(); }, 6 * 1000);
// #807 (owner: "en todos hacelo, lo del publicista"): toda campaña sin link de resultados recibe uno al arrancar. Idempotente (sólo las
// que tienen statsToken null; desactivar uno a mano lo deja en null y vuelve a crearse en el próximo arranque ⇒ para cortarle el acceso a
// un publicista usar "Generar uno nuevo", que invalida el anterior).
setTimeout(async () => {
  try {
    const list = await Campaign.find({ $or: [{ statsToken: null }, { statsToken: { $exists: false } }] }).select('code').lean();
    for (const c of list) await Campaign.updateOne({ code: c.code, $or: [{ statsToken: null }, { statsToken: { $exists: false } }] }, { $set: { statsToken: crypto.randomBytes(18).toString('base64url') } });
    if (list.length) logger.info(`[stats-link] ${list.length} campañas recibieron su link de resultados`);
  } catch (e) { logger.warn('[stats-link] alta masiva: ' + e.message); }
}, 15 * 1000);
setInterval(() => { _loadGiroxCredentials(); }, 60 * 1000);
// #351: % de comisión de referidos desde el panel (Config['referralCommissionPct']); mismo ritmo.
setTimeout(() => { require('./src/utils/referralRate').refreshFromConfig().catch(() => {}); }, 7 * 1000);
setInterval(() => { require('./src/utils/referralRate').refreshFromConfig().catch(() => {}); }, 60 * 1000);
function _hgcashWebhookSecrets() {
  // #216 (owner 2026-10-13, réplica de PAUTANUEVAsantino #323): si hay secreto en el PANEL se
  // acepta SOLO ese — el de SSM deja de valer, así los avisos de la cuenta hgcash VIEJA
  // (firmados con el secreto viejo de AWS) se rechazan. Sin secreto en el panel → el de SSM.
  if (_hgcashPanelSecret) return [_hgcashPanelSecret];
  return [process.env.HGCASH_WEBHOOK_SECRET || null].filter(Boolean);
}

// ============================================
// FAN-OUT del webhook hgcash → autoreembolsos
// ============================================
// hgcash permite UNA sola URL de webhook por cuenta. vipcargas la recibe y la
// reenvía al proyecto hermano (autoreembolsos, misma cuenta hgcash; cada uno
// matchea sus propios comprobantes, no hay doble carga). Se reenvía el body
// CRUDO (bytes exactos) con la firma ORIGINAL (X-HG-Webhook-Signature) para que
// el destino valide el mismo HMAC con el secret compartido. Fire-and-forget con
// 1 reintento a los 15s: si el destino está caído o lento, el procesamiento
// local NO se ve afectado en nada (ni demora la respuesta 200 a hgcash).
// URL configurable por env/SSM: HGCASH_FANOUT_URL (leída lazy — SSM carga en el
// bootstrap async). Poner 'off' para desactivar el reenvío sin deploy de código.
function _hgcashFanoutUrl() {
  const v = String(process.env.HGCASH_FANOUT_URL || '').trim();
  if (v.toLowerCase() === 'off') return null;
  return v || 'https://www.autoreembolsos.com/api/hgcash/webhook';
}

// #326 (owner 2026-10-06): los destinos del reenvío se cargan desde el PANEL
// (Banco automático → "🔁 Reenviar los avisos a otras páginas"), sin tocar SSM.
// Config['hgcashFanout'] = { urls: [...] } (hasta 5). Si ese Config EXISTE manda
// el panel (lista vacía = no reenviar a nadie); si no existe, sigue valiendo
// HGCASH_FANOUT_URL como antes. Cache de 30 s por instancia.
// Anti-círculo: (1) un aviso que YA llegó reenviado (trae X-Forwarded-By) no se
// vuelve a reenviar — la página que tiene el webhook en hgcash es la única que
// reparte, y lista a TODAS las demás; (2) nunca se reenvía a la URL propia.
const HGCASH_FANOUT_KEY = 'hgcashFanout';
const HGCASH_FANOUT_MAX = 5;
const HGCASH_FANOUT_TTL_MS = 30000;
let _hgcashFanoutCache = null; // { at, value: { source, urls } }
const _hgcashFanoutStats = new Map(); // url → { ok, fail, lastAt, lastOk, lastError } (por instancia, desde el arranque)

function _fanoutUrlKey(u) {
  try {
    const p = new URL(String(u));
    return `${p.protocol}//${p.host.toLowerCase()}${p.pathname.replace(/\/+$/, '')}`;
  } catch (_) { return String(u || '').trim().toLowerCase().replace(/\/+$/, ''); }
}
function _hgcashOwnWebhookUrl() {
  return `${getPublicBaseUrl()}/api/hgcash/webhook`;
}
// Valida una URL de destino cargada desde el panel. Tira Error con mensaje para el admin.
function _normalizeFanoutUrl(raw) {
  const v = String(raw || '').trim();
  if (!v) throw new Error('Hay una línea vacía.');
  if (v.length > 300) throw new Error('Una de las direcciones es demasiado larga.');
  let p;
  try { p = new URL(v); } catch (_) { throw new Error(`"${v.slice(0, 60)}" no es una dirección válida (tiene que empezar con https://).`); }
  if (p.protocol !== 'https:') throw new Error(`"${p.host}": la dirección tiene que empezar con https://`);
  if (p.username || p.password) throw new Error(`"${p.host}": la dirección no puede llevar usuario ni contraseña.`);
  const host = p.hostname.toLowerCase();
  if (host === 'localhost' || /^(127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|0\.)/.test(host) || host.startsWith('[') || !host.includes('.')) {
    throw new Error(`"${host}": tiene que ser el dominio público de la otra página.`);
  }
  if (!p.pathname || p.pathname === '/') p.pathname = '/api/hgcash/webhook'; // pegaron solo el dominio
  p.hash = '';
  return p.toString();
}
async function _getHgcashFanout(opts) {
  const now = Date.now();
  if (!(opts && opts.fresh) && _hgcashFanoutCache && (now - _hgcashFanoutCache.at) < HGCASH_FANOUT_TTL_MS) {
    return _hgcashFanoutCache.value;
  }
  const raw = await getConfig(HGCASH_FANOUT_KEY, null);
  let value;
  if (raw && Array.isArray(raw.urls)) {
    value = { source: 'panel', urls: raw.urls.map((u) => String(u || '').trim()).filter(Boolean).slice(0, HGCASH_FANOUT_MAX) };
  } else {
    const envUrl = _hgcashFanoutUrl();
    value = { source: 'env', urls: envUrl ? [envUrl] : [] };
  }
  _hgcashFanoutCache = { at: now, value };
  return value;
}
function _fanoutStat(url, ok, err) {
  const st = _hgcashFanoutStats.get(url) || { ok: 0, fail: 0, lastAt: null, lastOk: null, lastError: null };
  if (ok) st.ok++; else { st.fail++; st.lastError = String(err || '').slice(0, 160); }
  st.lastAt = new Date(); st.lastOk = !!ok;
  _hgcashFanoutStats.set(url, st);
}

function _fanoutHgcashWebhook(req) {
  try {
    // Ya viene reenviado por otra página → no se reparte de nuevo (anti-círculo).
    if (req.get('X-Forwarded-By')) return;
    // Body y firma se capturan YA (sincrónico); los destinos se resuelven aparte.
    const rawBody = req.rawBody ? req.rawBody : Buffer.from(JSON.stringify(req.body || {}), 'utf8');
    const headers = {
      'Content-Type': req.get('Content-Type') || 'application/json',
      'X-Forwarded-By': 'vipcargas'
    };
    const sig = req.get('X-HG-Webhook-Signature');
    if (sig) headers['X-HG-Webhook-Signature'] = sig;
    _getHgcashFanout().then((cfg) => {
      const own = _fanoutUrlKey(_hgcashOwnWebhookUrl());
      for (const url of cfg.urls) {
        if (_fanoutUrlKey(url) === own) continue; // nunca a nosotros mismos
        _fanoutSendOne(url, rawBody, headers);
      }
    }).catch((e) => logger.warn(`[hgcash-fanout] no se pudieron leer los destinos: ${e.message}`));
  } catch (e) {
    logger.warn(`[hgcash-fanout] error preparando reenvío: ${e.message}`);
  }
}
function _fanoutSendOne(url, rawBody, headers) {
  const axios = require('axios');
  // maxRedirects:0 a propósito: un redirect (http→https, www↔apex) rompería la
  // entrega del POST — mejor que falle y quede visible en los logs y en el panel.
  const send = () => axios.post(url, rawBody, { headers, timeout: 8000, maxRedirects: 0 });
  send().then(() => _fanoutStat(url, true)).catch((e1) => {
    logger.warn(`[hgcash-fanout] ${url}: primer intento falló (${e1.message}) — reintento en 15s`);
    const t = setTimeout(() => {
      send().then(() => _fanoutStat(url, true)).catch((e2) => {
        _fanoutStat(url, false, e2.message);
        logger.warn(`[hgcash-fanout] reenvío a ${url} falló definitivamente: ${e2.message}`);
      });
    }, 15000);
    if (t.unref) t.unref();
  });
}

// #896 (owner: "revisemos por qué no funciona la carga automática"): registro de CADA aviso del banco (llegó / aceptado / rechazado y por
// qué), un documento por día ART en la colección `hgcash_webhook_diag`, para el diagnóstico del panel. Nunca frena el webhook.
function _hgWebhookDiag(result, req, extra) {
  try {
    const dk = _schedArtKey(new Date());
    const inc = { total: 1 }; inc['r.' + result] = 1;
    mongoose.connection.collection('hgcash_webhook_diag').updateOne({ _id: dk }, { $inc: inc, $set: Object.assign({ lastAt: new Date(), lastResult: result, lastIp: String(req.ip || '').slice(0, 60), lastFwdBy: String(req.get('X-Forwarded-By') || '').slice(0, 80) || null }, result === 'ok' ? { lastOkAt: new Date() } : { lastBadAt: new Date(), lastBadResult: result }, extra || {}) }, { upsert: true }).catch(() => {});
  } catch (_) {}
}
// #902 (owner: "¿por qué no detecta la carga directo? necesito que cargue todo directo"): RESPALDO del webhook. Si el aviso del banco no
// llega (URL o secreto mal en hgcash), cada minuto se le pregunta a la API del banco qué entró en las últimas 3 h y lo que falta se guarda
// como BankMovement y se cruza con los comprobantes igual que un aviso (`hgcashMatchFromMovement`). Sólo movimientos ENTRANTES con código
// único del banco (COELSA o externalID): si después llega también el aviso, la carga no se repite (HgcashCharge.chargeKey es único y la
// reference a 1girox es la misma). Kill switch: HGCASH_POLL_DISABLED=1.
let _hgPollRunning = false;
async function _hgcashPollTick() {
  if (_hgPollRunning || process.env.HGCASH_POLL_DISABLED === '1') return;
  _hgPollRunning = true;
  const diag = (set, inc) => { try { mongoose.connection.collection('hgcash_webhook_diag').updateOne({ _id: _schedArtKey(new Date()) }, Object.assign({ $set: set }, inc ? { $inc: inc } : {}), { upsert: true }).catch(() => {}); } catch (_) {} };
  try {
    const cfg = await getHgcashConfig(); if (!cfg.enabled) return;
    const hg = require('./src/services/hgcashService'); if (!hg.isEnabled()) return;
    let accId = cfg.accountId;
    if (!accId) { const acc = await hg.getAccounts(); if (acc.ok && (acc.data || []).length) { const a = acc.data.find((x) => !x.currency || /ARS/i.test(String(x.currency))) || acc.data[0]; accId = a.id; } }
    if (!accId) { diag({ lastPollAt: new Date(), lastPollError: 'sin cuenta del banco' }); return; }
    const lm = await hg.listMovements({ accountId: accId, from: new Date(Date.now() - 3 * 3600 * 1000), to: new Date() });
    if (!lm.ok) { diag({ lastPollAt: new Date(), lastPollError: String(lm.error || 'error').slice(0, 200) }); return; }
    let added = 0;
    for (const it of lm.items) {
      if (it.direction !== 'in') continue;
      const p = it.raw || {};
      const coelsa = p.coelsaCode || p.coelsa || null, ext = p.externalID || p.externalId || null, id = String(p.id || it.id || '');
      if (!id || (!coelsa && !ext)) continue;
      const or = [{ movementId: id }]; if (coelsa) or.push({ coelsaCode: coelsa }); if (ext) or.push({ externalId: ext });
      if (await BankMovement.exists({ $or: or })) continue;
      const amountNum = it.amount || (p.amount != null ? (Number(String(p.amount).replace(/[^\d.-]/g, '')) || null) : null);
      const doc = { movementId: id, externalId: ext, coelsaCode: coelsa, amount: amountNum, amountRaw: p.amount != null ? String(p.amount) : null, currency: p.currency || null, direction: 'Inbound',
        status: p.status || it.status || null, type: p.type || null, accountId: p.accountId || accId, fromName: p.fromName || null, fromCBU: p.fromCBU || null, fromCUIT: p.fromCUIT || null,
        toName: p.toName || null, toCBU: p.toCBU || null, toCUIT: p.toCUIT || null, date: it.date || (p.date ? new Date(p.date) : null), timezone: p.timezone || null, topic: 'POLL', eventType: 'poll', raw: p };
      try { await BankMovement.create({ ...doc, matchStatus: 'pending', createdAt: new Date() }); } catch (e) { if (e && e.code === 11000) continue; throw e; }
      added++;
      logger.info(`[hgcash] consulta al banco: entrada nueva $${amountNum} de "${doc.fromName || '?'}" coelsa=${coelsa || '-'} (el aviso no había llegado)`);
      const fresh = await BankMovement.findOne({ movementId: id }).lean();
      if (fresh) hgcashMatchFromMovement(fresh).catch((e) => logger.warn('[hgcash] consulta: match ' + e.message));
    }
    if (added) _emitHgcashUpdate('movimiento');
    diag({ lastPollAt: new Date(), lastPollError: null, lastPollSeen: lm.items.length }, added ? { pollAdded: added } : null);
  } catch (e) { logger.warn('[hgcash] consulta al banco: ' + e.message); diag({ lastPollAt: new Date(), lastPollError: String(e.message).slice(0, 200) }); }
  finally { _hgPollRunning = false; }
}
setTimeout(() => { _hgcashPollTick().catch(() => {}); setInterval(() => { _hgcashPollTick().catch(() => {}); }, 60 * 1000); }, 90 * 1000);
app.post('/api/hgcash/webhook', async (req, res) => {
  try {
    const secrets = _hgcashWebhookSecrets(); // #320: panel y/o SSM
    if (secrets.length) {
      const sigHeader = req.get('X-HG-Webhook-Signature') || '';
      const raw = req.rawBody ? req.rawBody.toString('utf8') : JSON.stringify(req.body || {});
      const provided = sigHeader.toLowerCase().startsWith('sha256=') ? sigHeader.slice(7).toLowerCase() : sigHeader.toLowerCase();
      const okSig = secrets.some((sec) => safeCompare(crypto.createHmac('sha256', sec).update(raw, 'utf8').digest('hex'), provided));
      if (!okSig) {
        // #277: ~2.000 rechazos/día en los logs del 13-14/09 sin saber de dónde
        // vienen. Se loguea el origen (IP, X-Forwarded-By del fan-out de otro
        // proyecto, UA, id/monto del payload) para identificar al emisor.
        try {
          const b = req.body || {};
          logger.warn(`[hgcash] webhook con firma inválida — rechazado (ip=${req.ip} fwdBy=${req.get('X-Forwarded-By') || '-'} ua=${String(req.get('User-Agent') || '-').slice(0, 40)} id=${b.id || b.movementId || '-'} amount=${b.amount != null ? b.amount : '-'} type=${b.type || b.eventType || b.topic || '-'} sig=${provided ? 'sí' : 'NO'})`);
        } catch (_) { logger.warn('[hgcash] webhook con firma inválida — rechazado'); }
        _hgWebhookDiag('firma_invalida', req);
        return res.status(401).json({ error: 'firma inválida' });
      }
    } else {
      // Fail-closed en producción: sin secreto no se puede validar la firma → NO se
      // procesa el webhook (evita inyección de movimientos/cargas falsas). En dev se permite.
      // #413 (seguridad): fail-closed SIEMPRE (antes sólo con NODE_ENV=production): sin secreto no se acredita nada.
      logger.error('[hgcash] webhook RECHAZADO: falta el secreto (panel → Banco automático, o HGCASH_WEBHOOK_SECRET en SSM)');
      _hgWebhookDiag('sin_secreto', req);
      return res.status(503).json({ error: 'webhook no configurado' });
    }

    // Fan-out al proyecto hermano (autoreembolsos): recién DESPUÉS de validar la
    // firma (solo se reenvían webhooks auténticos) y ANTES de cualquier filtro
    // local (el destino recibe TODO — movimientos y estados de pago — y decide
    // qué es suyo). Fire-and-forget: no bloquea nada de lo que sigue.
    _fanoutHgcashWebhook(req);

    const p = req.body || {};
    if (!p.id) { _hgWebhookDiag('sin_id', req); return res.status(400).json({ error: 'payload sin id' }); }
    _hgWebhookDiag(String(p.topic || '').toUpperCase() === 'TRANSACTION_REQUEST' ? 'ok_pago' : 'ok', req, String(p.direction || '') === 'Inbound' ? { lastInboundAt: new Date() } : {});

    // Webhook de ESTADO de un PAGO saliente (cash-out): topic TRANSACTION_REQUEST.
    // Lo manejamos aparte (no es un movimiento entrante).
    if (String(p.topic || '').toUpperCase() === 'TRANSACTION_REQUEST') {
      res.status(200).json({ ok: true });
      handlePayoutStatusWebhook(p).catch(() => {});
      return;
    }

    // Auto-capturar el accountId de NUESTRA cuenta hgcash (para los pagos salientes)
    // la primera vez que llega un movimiento, si todavía no está en la config.
    if (p.accountId) { ensureHgcashAccountIdSaved(p.accountId).catch(() => {}); }

    const amountNum = (p.amount !== undefined && p.amount !== null)
      ? (Number(String(p.amount).replace(/[^\d.-]/g, '')) || null) : null;
    const doc = {
      movementId: String(p.id),
      externalId: p.externalID || null,
      coelsaCode: p.coelsaCode || null,
      amount: amountNum, amountRaw: (p.amount !== undefined && p.amount !== null) ? String(p.amount) : null,
      currency: p.currency || null, direction: p.direction || null,
      status: p.status || null, type: p.type || null, accountId: p.accountId || null,
      fromName: p.fromName || null, fromCBU: p.fromCBU || null, fromCUIT: p.fromCUIT || null,
      toName: p.toName || null, toCBU: p.toCBU || null, toCUIT: p.toCUIT || null,
      date: p.date ? new Date(p.date) : null, timezone: p.timezone || null,
      topic: p.topic || null, eventType: p.eventType || null, raw: p
    };

    let isNew = false, statusChanged = false;
    try {
      await BankMovement.create({
        ...doc,
        matchStatus: (doc.direction === 'Inbound') ? 'pending' : 'ignored',
        createdAt: new Date()
      });
      isNew = true;
    } catch (e) {
      if (e && e.code === 11000) {
        // Reentrega / created+status_change: actualizar datos sin pisar el matchStatus.
        await BankMovement.updateOne({ movementId: doc.movementId }, { $set: { status: doc.status, eventType: doc.eventType, raw: doc.raw } });
        statusChanged = true;
      } else { throw e; }
    }

    // Responder 2xx YA (el banco reintenta si no; el matcheo corre aparte).
    res.status(200).json({ ok: true });

    if (isNew) _emitHgcashUpdate('movimiento'); // panel en vivo (entrantes y salientes)
    // #820: también cuando el banco avisa DESPUÉS que el movimiento quedó acreditado (primero 'pending', luego 'done'): antes sólo se
    // matcheaba en el primer aviso y esa carga caía a manual.
    if ((isNew || statusChanged) && doc.direction === 'Inbound') {
      BankMovement.findOne({ movementId: doc.movementId }).lean()
        .then(fresh => { if (fresh) return hgcashMatchFromMovement(fresh); })
        .catch(() => {});
    }
  } catch (error) {
    logger.error(`[hgcash] webhook error: ${error.message}`);
    if (!res.headersSent) res.status(500).json({ error: 'error interno' });
  }
});

// Comprobante PDF de un pago (link PERMANENTE que se le manda al cliente). En cada
// visita resuelve un signedUrl FRESCO de hgcash (la URL firmada vence en 1h) y redirige.
// Público (sin auth): la clave es el payout.id (UUID inadivinable) y muestra el recibo
// del propio pago del cliente. NO requiere authMiddleware (como el webhook).
app.get('/api/payout-receipt/:payoutId', async (req, res) => {
  try {
    if (!hgcashPay.isEnabled()) return res.status(503).send('Comprobante no disponible en este momento.');
    const payout = await PendingPayout.findOne({ id: String(req.params.payoutId || '') }).lean();
    if (!payout) return res.status(404).send('Comprobante no encontrado.');
    let txId = payout.hgTxId;
    if (!txId && payout.hgTransactionId) {
      const r = await hgcashPay.getTransactionIdForRequest(payout.hgTransactionId);
      if (r.ok && r.transactionId) {
        txId = String(r.transactionId);
        try { await PendingPayout.updateOne({ id: payout.id }, { $set: { hgTxId: txId } }); } catch (_) {}
      }
    }
    if (!txId) return res.status(404).send('El comprobante todavía no está disponible. Probá de nuevo en unos minutos.');
    const rec = await hgcashPay.getReceiptUrl(txId);
    if (!rec.ok || !rec.signedUrl) return res.status(404).send('No se pudo obtener el comprobante. Probá más tarde.');
    return res.redirect(302, rec.signedUrl);
  } catch (e) {
    logger.warn(`[hgcash-pay] endpoint payout-receipt falló: ${e.message}`);
    return res.status(500).send('Error al obtener el comprobante.');
  }
});

// ============================================
// CONTROL DE DEMORAS DE RESPUESTA EN CHATS (SLA de atención)
// ============================================
// El "reloj" de espera vive en ChatStatus (pendingSince/pendingPreview/pendingType),
// en MongoDB → funciona en multi-instancia sin estado en memoria. Cuando un agente
// responde (o se cierra el chat) se calcula la demora y, si supera el umbral, se
// guarda un registro permanente en ChatDelay (snapshot que sobrevive al TTL de
// Message). TODO va envuelto en try/catch: una falla acá NUNCA debe romper la
// entrega de un mensaje.
const DEFAULT_CHAT_DELAY_THRESHOLD = 120;        // cargas: 2 minutos
const DEFAULT_CHAT_DELAY_THRESHOLD_PAGOS = 1800; // pagos: 30 minutos

// Umbral según la cola. Pagos tolera demoras mucho mayores (el pago tarda), cargas no.
async function getChatDelayThreshold(category) {
  const isPagos = category === 'pagos';
  const key = isPagos ? 'chatDelayThresholdPagosSeconds' : 'chatDelayThresholdSeconds';
  const def = isPagos ? DEFAULT_CHAT_DELAY_THRESHOLD_PAGOS : DEFAULT_CHAT_DELAY_THRESHOLD;
  try {
    const v = await getConfig(key);
    const n = parseInt(v, 10);
    return Number.isFinite(n) && n > 0 ? n : def;
  } catch (_) {
    return def;
  }
}

// Deriva la cola (cargas/pagos) del estado del chat.
function deriveChatQueue(cs) {
  return (cs && (cs.status === 'payments' || cs.category === 'pagos')) ? 'pagos' : 'cargas';
}

// Cola según el rol del agente que respondió: el withdrawer solo atiende pagos y el
// depositor solo cargas. El admin general atiende ambas → null (se deriva del chat).
function roleQueueHint(role) {
  if (role === 'withdrawer') return 'pagos';
  if (role === 'depositor') return 'cargas';
  return null;
}

function buildDelayPreview(content, type) {
  if (type === 'image') return '📸 Imagen';
  if (type === 'video') return '🎥 Video';
  const s = (content == null ? '' : String(content)).replace(/\s+/g, ' ').trim();
  return s.length > 200 ? s.slice(0, 200) + '…' : s;
}

// Cliente manda un mensaje → arrancar el reloj SI no hay una espera en curso
// (la demora se mide desde el PRIMER mensaje sin responder, no desde el último).
async function delayClockOnUserMessage(userId, content, type) {
  if (!userId) return;
  try {
    await ChatStatus.updateOne(
      { userId, $or: [{ pendingSince: null }, { pendingSince: { $exists: false } }] },
      { $set: {
        pendingSince: new Date(),
        pendingPreview: buildDelayPreview(content, type),
        pendingType: type || 'text'
      } }
    );
  } catch (e) {
    logger.error(`[chatDelay] start failed (${userId}): ${e.message}`);
  }
}

// Resolver el reloj. responded=true → un agente respondió; responded=false → el
// chat se cerró sin responder. Registra ChatDelay sólo si la demora ≥ umbral.
// Siempre limpia el reloj.
async function delayClockResolve(userId, { responded, agentId = null, agentUsername = null, via = null, queueHint = null } = {}) {
  if (!userId) return;
  try {
    // Limpiar el reloj de forma ATÓMICA y quedarse con el valor previo. Si dos
    // agentes responden a la vez, sólo el que efectivamente "tomó" el pendingSince
    // (filtro pendingSince != null) registra la demora → sin doble conteo.
    const cs = await ChatStatus.findOneAndUpdate(
      { userId, pendingSince: { $ne: null } },
      { $set: { pendingSince: null, pendingPreview: null, pendingType: null } },
      { new: false }
    ).select('username assignedTo pendingSince pendingPreview pendingType category status').lean();

    if (!cs || !cs.pendingSince) return; // no había espera en curso (o ya la tomó otro)

    const now = new Date();
    const delaySeconds = Math.round((now - new Date(cs.pendingSince)) / 1000);
    // Gana "pagos" si hay CUALQUIER señal de pagos: el chat está en la pestaña Pagos
    // (status:'payments'), o la operación fue un retiro, o respondió un withdrawer.
    // Si no hay ninguna señal de pagos → cargas. Esto matchea el flujo real: una vez
    // que el chat pasa a Pagos, toda demora ahí es de la cola de pagos.
    const queue = (queueHint === 'pagos' || deriveChatQueue(cs) === 'pagos') ? 'pagos' : 'cargas';
    const threshold = await getChatDelayThreshold(queue);

    if (delaySeconds >= threshold) {
      await ChatDelay.create({
        id: uuidv4(),
        userId,
        username: cs.username || null,
        userMessageAt: cs.pendingSince,
        userMessagePreview: cs.pendingPreview || '',
        userMessageType: cs.pendingType || 'text',
        respondedAt: responded ? now : null,
        delaySeconds,
        respondedById: responded ? agentId : null,
        respondedByUsername: responded ? agentUsername : null,
        respondedVia: responded ? (via || 'message') : null,
        assignedTo: cs.assignedTo || null,
        status: responded ? 'responded' : 'unanswered',
        category: queue
      });
    }
  } catch (e) {
    logger.error(`[chatDelay] resolve failed (${userId}): ${e.message}`);
  }
}

// Limpiar el reloj sin registrar nada (cuando el chat sale del estado "esperando
// agente" por un motivo que no es ni respuesta ni cierre, ej: pasa a pagos).
async function delayClockClear(userId) {
  if (!userId) return;
  try {
    await ChatStatus.updateOne(
      { userId },
      { $set: { pendingSince: null, pendingPreview: null, pendingType: null } }
    );
  } catch (e) {
    logger.error(`[chatDelay] clear failed (${userId}): ${e.message}`);
  }
}

// Comunidad: cuando un cliente cuyo chat está en estado 'comunidad' vuelve a
// escribir, re-avisar a los agentes de Comunidad (badge + sonido en el panel)
// aunque ya no estén mirando esa pestaña. Sin esto, un cliente derivado que
// responde después de ser atendido quedaba sin aviso y se generaban demoras.
// Fire-and-forget: NUNCA frena la entrega del mensaje.
async function maybeNotifyComunidadActivity(userId, username) {
  if (!userId) return;
  try {
    const cs = await ChatStatus.findOne({ userId }).select('status username').lean();
    if (cs && cs.status === 'comunidad') {
      notifyAdmins('comunidad_activity', { userId, username: username || cs.username || null });
    }
  } catch (_) { /* nunca rompe la entrega del mensaje */ }
}

// ============================================
// MIDDLEWARE DE AUTENTICACIÓN
// ============================================
const authMiddleware = async (req, res, next) => {
  // Accept token from Authorization header first; fall back to admin_api_session
  // httpOnly cookie (sent automatically by the browser for same-origin requests
  // to /api/*).  This allows the admin panel to work purely via cookie without
  // storing the JWT in localStorage.
  let token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    token = getAdminApiSessionCookie(req) || null;
  }
  
  if (!token) {
    return res.status(401).json({ error: 'Token no proporcionado' });
  }
  
  try {
    const decoded = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] });
    if (decoded && (decoded.purpose || (decoded.type && decoded.type !== 'access'))) return res.status(401).json({ error: 'Token inválido' }); // #956: un token de reset/propósito no es sesión

    // Buscar usuario por 'id' primero, luego por '_id' como fallback.
    // Solo los campos que este middleware usa (corre en CADA request; hidratar
    // el doc completo con fcmTokens/tagHistory/etc. era costo puro).
    // ⚠️ Si un chequeo futuro necesita otro campo del user: agregarlo acá.
    const AUTH_USER_FIELDS = 'id username role isActive isBlocked blockReason tokenVersion mustChangePassword';
    let user = await User.findOne({ id: decoded.userId }).select(AUTH_USER_FIELDS);

    if (!user) {
      // Intentar buscar por _id (para usuarios migrados)
      try {
        user = await User.findById(decoded.userId).select(AUTH_USER_FIELDS);
      } catch (e) {
        // _id inválido, ignorar
      }
    }
    
    if (!user) {
      return res.status(401).json({ error: 'Usuario no encontrado' });
    }

    if (!user.isActive) {
      return res.status(401).json({ error: 'Usuario desactivado' });
    }

    if (user.isBlocked === true) {
      return res.status(403).json({
        error: 'Tu cuenta está bloqueada. Contactá a soporte.',
        code: 'USER_BLOCKED',
        reason: user.blockReason || null
      });
    }
    
    // Revocación de sesión: comparar siempre, normalizando ausentes a 0.
    // Antes la condición usaba `user.tokenVersion &&`, que con tokenVersion 0
    // (falsy) salteaba la verificación.
    if ((decoded.tokenVersion ?? 0) !== (user.tokenVersion ?? 0)) {
      return res.status(401).json({ error: 'Sesión expirada. Por favor, vuelve a iniciar sesión.' });
    }
    
    req.user = decoded;

    // Lockdown del rol publisher_admin: sólo puede tocar las rutas listadas en
    // PUBLISHER_ADMIN_ALLOWED_PATHS. Cualquier otra ruta devuelve 403, así no
    // puede llegar a endpoints de cargas/retiros/chats/usuarios aunque el JWT
    // sea válido. Match exacto o por prefijo (con "/" final) para soportar
    // sub-rutas (/api/admin/publisher-admin/create-user, /api/admin/publisher-admin/my-stats).
    if (user.role === 'publisher_admin') {
      const reqPath = req.path || '';
      const allowed = PUBLISHER_ADMIN_ALLOWED_PATHS.some(p =>
        reqPath === p || reqPath.startsWith(p + '/')
      );
      if (!allowed) {
        return res.status(403).json({
          error: 'Acceso denegado para tu rol.',
          code: 'PUBLISHER_ADMIN_FORBIDDEN'
        });
      }
    }

    // Enforce mandatory password change server-side.
    // If the user has `mustChangePassword: true` (set by JUGAYGANA import,
    // login default-password detection, or admin reset), only the allow-listed
    // endpoints are reachable. Any other authenticated request returns 403 so
    // the SPA can re-open the mandatory change modal — even after a reload.
    if (user.mustChangePassword === true) {
      if (isAdminRole(user.role)) {
        // Self-heal: admins must NEVER carry the mustChangePassword flag.
        // Clean it on the fly so the request proceeds normally. This handles
        // admins that were marked before the role-isolation fix (PR #286)
        // and would otherwise be permanently blocked by this middleware.
        try {
          user.mustChangePassword = false;
          await User.updateOne({ _id: user._id }, { $set: { mustChangePassword: false } });
          logger.info(`[authMiddleware] Auto-cleared mustChangePassword for admin ${user.username}`);
        } catch (e) {
          logger.warn(`[authMiddleware] Failed to auto-clear mustChangePassword for ${user.username}: ${e.message}`);
        }
      } else {
        const path = req.path || '';
        const allowed = MUST_CHANGE_PASSWORD_ALLOWED_PATHS.some(p => path === p || path.startsWith(p + '/'));
        if (!allowed) {
          return res.status(403).json({
            error: 'Debés cambiar tu contraseña antes de continuar',
            code: 'MUST_CHANGE_PASSWORD'
          });
        }
      }
    }

    next();
  } catch (error) {
    return res.status(401).json({ error: 'Token inválido' });
  }
};

// #956 (seguridad): adminMiddleware deja pasar a TODO el staff (admin, depositor, withdrawer, comunidad) y muchas rutas confiaban en un
// chequeo interno que no siempre estaba. Acá va la lista de prefijos que SÓLO el admin general puede MUTAR (POST/PUT/PATCH/DELETE):
// acreditar fichas, historias y notificaciones masivas, bonos y estrategias, configuración, claves, clientes (editar/borrar/login sin clave).
// Los agentes siguen pudiendo lo suyo: cargas (deposit, deposit-reviews), pagos (payouts), soporte/chats, lecturas (GET).
const STAFF_DENY_MUTATIONS = [
  /^\/api\/admin\/(roulette|stories|stories-autopilot|bonus-strategy|send-notification|notification-rules|notif-batches|notif-templates|cronograma|encuesta|inactividad|community-code|promo-bonus|strategy|strategy-plans|vip-levels|fire|refund-tiers|refund-config|platforms|campaigns|publisher-admins|webhooks|cierres|config|commands|sorteos|inicio\/(notif-center|weekly-review)|newbie-offers|fraud|datos-ia|datos|inicio-pin|datos-pin|bank|hgcash\/(config|credentials|fanout)|girox|gastos|expenses|menus|registration|install-gift|missions|referral|referrals|users\/[^/]+\/(login-without-password|role|reset-password|block|unblock|fraud|force-logout|reset-test|change-influencer))/i,
  /^\/api\/users\/[^/]+$/i // PUT/DELETE /api/users/:id (editar saldo / borrar cliente)
];
const adminMiddleware = (req, res, next) => {
  if (req.user.role !== 'admin' && req.user.role !== 'depositor' && req.user.role !== 'withdrawer' && req.user.role !== 'comunidad') {
    return res.status(403).json({ error: 'Acceso denegado. Solo administradores.' });
  }
  if (req.user.role !== 'admin' && req.method !== 'GET' && req.method !== 'HEAD') {
    const p = String(req.originalUrl || req.url || '').split('?')[0];
    if (STAFF_DENY_MUTATIONS.some((re) => re.test(p))) { logger.warn(`[authz] ${req.user.username} (${req.user.role}) intentó ${req.method} ${p}`); return res.status(403).json({ error: 'Solo el administrador general puede hacer esto.' }); }
  }
  next();
};

const depositorMiddleware = (req, res, next) => {
  // 'comunidad' funciona como un depositor (mismas funciones de carga) + ve la sección Comunidad.
  if (req.user.role !== 'admin' && req.user.role !== 'depositor' && req.user.role !== 'comunidad') {
    return res.status(403).json({ error: 'Acceso denegado. Solo agentes de carga.' });
  }
  next();
};

const withdrawerMiddleware = (req, res, next) => {
  if (req.user.role !== 'admin' && req.user.role !== 'withdrawer') {
    return res.status(403).json({ error: 'Acceso denegado. Solo agentes de retiro.' });
  }
  next();
};

// Sólo cuentas con role='publisher_admin' pueden tocar los endpoints
// /api/admin/publisher-admin/*. El admin general usa otros endpoints (CRUD
// /api/admin/publisher-admins) para gestionar a estos publisher_admins.
const publisherAdminMiddleware = (req, res, next) => {
  if (req.user.role !== 'publisher_admin') {
    return res.status(403).json({ error: 'Acceso denegado. Sólo cuentas publisher_admin.' });
  }
  next();
};

