// Sincroniza la contraseña con la plataforma reintentando hasta 3 veces.
// Si tras los 3 intentos no se puede sincronizar, crea un mensaje interno
// (adminOnly) en el chat del usuario para que los admins sepan que la
// contraseña quedó desincronizada y puedan corregirla manualmente.
//
// NOTA: en 1girox esto NO necesita la contraseña vieja ni la sesión del jugador
// (PUT /players/{username}/password va con la API key). Además cierra todas las
// sesiones abiertas de ese jugador en la plataforma, que es lo deseable al cambiar
// una clave.
// MULTI-PLATAFORMA (#226, owner 2026-10-16): "si se edita la clave arriba que se cambie en Ganamos,
// en Girox y en la página de cargas, así la gente no se marea". Girox lo hace
// syncPasswordToJugaygana (abajo); las DEMÁS plataformas habilitadas con API conectada se
// actualizan acá con la MISMA clave. Nunca frena el flujo: un fallo queda en
// User.platforms.<id>.passwordError y se reintenta en el próximo cambio/login.
async function _syncPasswordOtherPlatforms(user, newPassword, context) {
  const out = {};
  try {
    if (!user || isAdminRole(user.role)) return out;
    const enabled = await platforms.listEnabled();
    for (const p of enabled) {
      if (p.id === 'girox' || !p.connected) continue;
      const ad = platforms.getAdapter(p.id);
      if (!ad || typeof ad.changeUserPassword !== 'function') continue;
      try {
        let r = await ad.changeUserPassword(user.username, newPassword);
        if (!r.success && r.code === 'player_not_found') {
          // Todavía no existe ahí (se creó antes de conectar la API): se crea con la clave nueva.
          const c = await ad.syncUserToPlatform({ username: user.username, password: newPassword });
          r = c && c.success ? { success: true, created: true } : r;
        }
        if (r && r.success) {
          out[p.id] = true;
          await User.updateOne({ id: user.id }, { $set: { [`platforms.${p.id}.status`]: 'synced', [`platforms.${p.id}.username`]: user.username, [`platforms.${p.id}.passwordSyncedAt`]: new Date(), [`platforms.${p.id}.passwordError`]: null } }).catch(() => {});
          logger.info(`[pwd-sync] clave sincronizada en ${p.id} (${context}) para ${user.username}`);
        } else {
          out[p.id] = false;
          await User.updateOne({ id: user.id }, { $set: { [`platforms.${p.id}.passwordError`]: String((r && r.error) || 'fallo').slice(0, 300) } }).catch(() => {});
          logger.warn(`[pwd-sync] ${p.id}: no se pudo sincronizar la clave de ${user.username}: ${r && r.error}`);
        }
      } catch (e) {
        out[p.id] = false;
        logger.warn(`[pwd-sync] ${p.id}: excepción para ${user.username}: ${e.message}`);
      }
    }
  } catch (e) { logger.warn(`[pwd-sync] otras plataformas: ${e.message}`); }
  return out;
}

async function syncPasswordToJugaygana(user, newPassword, context) {
  if (isAdminRole(user.role)) {
    return { success: true, skipped: true };
  }
  // Las demás plataformas (Ganamos cuando tenga API) se actualizan en paralelo con la misma clave.
  _syncPasswordOtherPlatforms(user, newPassword, context).catch(() => {});

  const MAX_ATTEMPTS = 3;
  let lastError = null;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const jgResult = await girox.changeUserPassword(user.username, newPassword);
      if (jgResult.success) {
        logger.info(`[pwd-sync] Sincronizada con 1girox (${context}) para ${user.username} en intento ${attempt}/${MAX_ATTEMPTS}`);
        // La clave ya está igual en los dos lados: no hace falta el sync diferido
        // del próximo login.
        await User.updateOne({ id: user.id }, { $set: { giroxPasswordSynced: true } }).catch(() => {});
        return { success: true, attempts: attempt };
      }
      lastError = jgResult.error || 'Error desconocido';
      logger.warn(`[pwd-sync] Intento ${attempt}/${MAX_ATTEMPTS} falló para ${user.username}: ${lastError}`);
    } catch (err) {
      lastError = err.message;
      logger.error(`[pwd-sync] Intento ${attempt}/${MAX_ATTEMPTS} con excepción para ${user.username}: ${lastError}`);
    }

    if (attempt < MAX_ATTEMPTS) {
      await new Promise(r => setTimeout(r, 500 * Math.pow(2, attempt - 1)));
    }
  }

  logger.error(`[pwd-sync] Falló sync con 1girox para ${user.username} tras ${MAX_ATTEMPTS} intentos. Último error: ${lastError}`);
  // #573 (owner): "mismo acceso en la app y en Girox". Si no se pudo sincronizar ahora, queda marcado para que el PRÓXIMO login
  // vuelva a mandar la clave a 1girox (el login re-sincroniza cuando giroxPasswordSynced !== true).
  await User.updateOne({ id: user.id }, { $set: { giroxPasswordSynced: false } }).catch(() => {});

  try {
    await Message.create({
      id: uuidv4(),
      senderId: 'system',
      senderUsername: 'SYSTEM',
      senderRole: 'system',
      receiverId: user.id,
      receiverRole: 'user',
      content: `⚠️ SYNC FALLIDO: el usuario cambió su contraseña en VIPCARGAS pero no se pudo sincronizar con 1girox.com tras ${MAX_ATTEMPTS} intentos. Último error: "${lastError}". Revisar y actualizar la contraseña manualmente en la plataforma. Contexto: ${context}.`,
      type: 'system',
      adminOnly: true,
      read: true,
      timestamp: new Date()
    });
    logger.info(`[pwd-sync] Mensaje interno creado para admins en chat de ${user.username}`);
  } catch (msgErr) {
    logger.error(`[pwd-sync] No se pudo crear mensaje interno para ${user.username}: ${msgErr.message}`);
  }

  return { success: false, attempts: MAX_ATTEMPTS, error: lastError };
}

// Cambiar contraseña
app.post('/api/auth/change-password', authMiddleware, authLimiter, async (req, res) => {
  try {
    const { newPassword, whatsapp, phone, otpCode, closeAllSessions } = req.body;

    // Buscar por 'id' primero, luego por '_id' como fallback
    let user = await User.findOne({ id: req.user.userId });
    
    if (!user) {
      try {
        user = await User.findById(req.user.userId);
      } catch (e) {
        // _id inválido, ignorar
      }
    }
    
    if (!user) {
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }

    if (!newPassword || newPassword.length < 6) {
      return res.status(400).json({ error: 'La contraseña debe tener al menos 6 caracteres' });
    }

    // Determinar si el usuario YA tiene un teléfono verificado vía OTP.
    // Solo en ese caso se permite cambiar la contraseña sin volver a verificar nada.
    const hasVerifiedPhone = !!(user.phone && user.phoneVerified === true);

    // Resolver el "nuevo teléfono" propuesto: priorizar `phone` (formato internacional),
    // y como fallback aceptar `whatsapp` por compatibilidad con el cliente actual.
    const requestedPhoneRaw = (typeof phone === 'string' && phone.trim())
      || (typeof whatsapp === 'string' && whatsapp.trim())
      || null;
    const requestedPhone = requestedPhoneRaw ? requestedPhoneRaw.trim() : null;

    // ¿Se está intentando agregar/cambiar el teléfono?
    // - Si el usuario NO tiene teléfono verificado y se envió un teléfono → exigir OTP.
    // - Si el usuario YA tiene teléfono verificado y se envió un teléfono distinto → exigir OTP.
    // - Si el usuario YA tiene teléfono verificado y NO se envió teléfono (o coincide) → no se exige OTP,
    //   solo se valida la contraseña actual del usuario (esto cubre el caso "cambio de contraseña sin tocar teléfono").
    let isPhoneChange = false;
    if (requestedPhone) {
      if (!hasVerifiedPhone) {
        isPhoneChange = true;
      } else if (requestedPhone !== user.phone) {
        isPhoneChange = true;
      }
    } else if (!hasVerifiedPhone) {
      // No tiene teléfono verificado y no envió uno → no podemos guardar phoneVerified=true,
      // pero permitimos cambiar la contraseña. (No debería ocurrir desde el flujo forzado,
      // ya que el front exige el teléfono cuando no hay uno verificado.)
      isPhoneChange = false;
    }

    if (isPhoneChange) {
      // Validar formato del teléfono propuesto.
      if (!validateInternationalPhone(requestedPhone)) {
        return res.status(400).json({
          error: 'Número de teléfono inválido. Usá formato internacional con código de país (ej: +5491155551234)'
        });
      }
      // Exigir código OTP previamente enviado vía /api/auth/change-password/send-otp.
      if (!otpCode || String(otpCode).trim().length < 6) {
        return res.status(400).json({ error: 'Se requiere el código de verificación SMS' });
      }
      // Verificar que el teléfono no esté ya registrado y verificado por otro usuario
      // (por clave normalizada: detecta el mismo número en distinto formato).
      const _reqPhoneKey = normalizePhoneKey(requestedPhone);
      const otherUser = await User.findOne({
        phoneKey: _reqPhoneKey,
        phoneVerified: true,
        id: { $ne: user.id }
      }).lean();
      if (otherUser) {
        return res.status(400).json({ error: 'Este número de teléfono ya está registrado por otra cuenta' });
      }
      const otpResult = await verifyOTP(requestedPhone, String(otpCode).trim(), 'change-password');
      if (!otpResult.valid) {
        return res.status(400).json({ error: otpResult.error || 'Código de verificación incorrecto o expirado' });
      }
      // OTP válido: persistir teléfono verificado.
      user.phone = requestedPhone;
      user.phoneKey = _reqPhoneKey;
      user.phoneVerified = true;
      user.smsConsent = true;
      // Mantener `whatsapp` sincronizado para compatibilidad con vistas que lo siguen leyendo.
      user.whatsapp = requestedPhone;
    }

    // Defensa contra robo de token: si NO es un cambio de teléfono (donde el
    // OTP ya prueba identidad) y NO es el cambio obligatorio de primer ingreso,
    // exigir la contraseña actual antes de permitir el cambio.
    if (!isPhoneChange && user.mustChangePassword !== true) {
      const currentPassword = req.body && req.body.currentPassword;
      let currentOk = false;
      if (currentPassword) {
        try {
          currentOk = await bcrypt.compare(String(currentPassword), user.password);
        } catch (e) {
          currentOk = false;
        }
      }
      if (!currentOk) {
        return res.status(401).json({ error: 'La contraseña actual es incorrecta', code: 'BAD_CURRENT_PASSWORD' });
      }
    }

    // Asignar contraseña en texto plano; el middleware pre-save del modelo la hasheará
    user.password = newPassword;
    user.passwordChangedAt = new Date();
    // The user just changed their password (and verified the OTP for any new
    // phone, if applicable). Lift the mandatory-change flag so the rest of the
    // API stops returning 403 MUST_CHANGE_PASSWORD on subsequent requests.
    user.mustChangePassword = false;
    
    if (closeAllSessions) {
      user.tokenVersion = (user.tokenVersion || 0) + 1;
    }

    await user.save();

    await syncPasswordToJugaygana(user, newPassword, 'change-password');

    // "Cerrar todas las sesiones" sube tokenVersion y mata TODOS los JWT —
    // incluido el de ESTA request. Para que el que tildó el checkbox no quede
    // deslogueado (fix 2026-08-07), se le emite un token FRESCO con la versión
    // nueva: se cierran los DEMÁS dispositivos, el suyo sigue adentro.
    let freshToken = null;
    if (closeAllSessions) {
      freshToken = jwt.sign(
        { userId: user.id, username: user.username, role: user.role, tokenVersion: user.tokenVersion ?? 0 },
        JWT_SECRET,
        { expiresIn: '30d' }
      );
    }

    res.json({
      message: 'Contraseña cambiada exitosamente',
      sessionsClosed: closeAllSessions || false,
      token: freshToken,
      phoneVerified: !!user.phoneVerified,
      phone: user.phone || null
    });
  } catch (error) {
    logger.error(`Error en change-password: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Enviar OTP para verificar el teléfono nuevo durante un cambio de contraseña
// (aplica tanto al cambio obligatorio del primer login como al cambio desde el perfil).
// Reutiliza generateAndSendOTP/verifyOTP del PR #260 con un nuevo `purpose`.
app.post('/api/auth/change-password/send-otp', authMiddleware, sensitiveLimiter, smsIpLimiter, async (req, res) => {
  try {
    const { phone } = req.body;

    if (!phone || typeof phone !== 'string') {
      return res.status(400).json({ error: 'Número de teléfono requerido' });
    }

    const normalizedPhone = String(phone || '').trim(); /* #956 */
    if (!validateInternationalPhone(normalizedPhone)) {
      return res.status(400).json({
        error: 'Número de teléfono inválido. Usá formato internacional con código de país (ej: +5491155551234)'
      });
    }

    // Buscar el usuario autenticado.
    let user = await User.findOne({ id: req.user.userId }).lean();
    if (!user) {
      try {
        user = await User.findById(req.user.userId).lean();
      } catch (e) { /* ignorar id inválido */ }
    }
    if (!user) {
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }

    // Si otro usuario distinto ya tiene este teléfono verificado, rechazar (por clave normalizada).
    const _normPhoneKey = normalizePhoneKey(normalizedPhone);
    const otherUser = await User.findOne({
      phoneKey: _normPhoneKey,
      phoneVerified: true,
      id: { $ne: user.id }
    }).lean();
    if (otherUser) {
      return res.status(400).json({ error: 'Este número de teléfono ya está registrado por otra cuenta' });
    }

    const result = await generateAndSendOTP(normalizedPhone, 'change-password');
    if (!result.success) {
      return res.status(429).json({ error: result.error });
    }

    const maskedPhone = normalizedPhone.replace(/(\+\d{1,4})\d+(\d{4})$/, '$1****$2');
    res.json({
      success: true,
      pendingVerification: true,
      phone: maskedPhone,
      message: 'Te enviamos un código SMS al número indicado'
    });
  } catch (error) {
    logger.error(`Error en change-password/send-otp: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Cambio de contraseña en "modo temporal": cuando al usuario no le llega el SMS
// o el OTP le da error repetido, puede entrar igual. Cambia la contraseña SIN
// verificar el teléfono, lo guarda como NO verificado y deja al usuario en
// estado `phoneVerificationPending: true`. Genera un `pendingAccessCode` al azar
// (6 dígitos). El usuario puede usar la app pero NO puede retirar hasta verificar
// el teléfono por SMS (lo exige /api/withdrawal/request).
app.post('/api/auth/change-password/pending', authMiddleware, authLimiter, async (req, res) => {
  try {
    const { newPassword, whatsapp, phone, closeAllSessions } = req.body;

    let user = await User.findOne({ id: req.user.userId });
    if (!user) {
      try { user = await User.findById(req.user.userId); } catch (e) { /* _id inválido */ }
    }
    if (!user) {
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }

    if (!newPassword || newPassword.length < 6) {
      return res.status(400).json({ error: 'La contraseña debe tener al menos 6 caracteres' });
    }

    const requestedPhoneRaw = (typeof phone === 'string' && phone.trim())
      || (typeof whatsapp === 'string' && whatsapp.trim())
      || null;
    const requestedPhone = requestedPhoneRaw ? requestedPhoneRaw.trim() : null;

    if (requestedPhone && !validateInternationalPhone(requestedPhone)) {
      return res.status(400).json({
        error: 'Número de teléfono inválido. Usá formato internacional con código de país (ej: +5491155551234)'
      });
    }

    // Código de acceso temporal al azar (6 dígitos).
    const pendingCode = String(crypto.randomInt(0, 1000000)).padStart(6, '0');

    user.password = newPassword;
    user.passwordChangedAt = new Date();
    user.mustChangePassword = false;
    user.pendingAccessCode = pendingCode; user.pendingAccessCodeAt = new Date(); // #965: vence a los 7 días
    // El usuario entra, pero queda con verificación de teléfono pendiente:
    // no podrá retirar hasta verificar por SMS.
    user.phoneVerificationPending = true;
    user.phoneVerified = false;
    if (requestedPhone) {
      // Guardar el teléfono como NO verificado.
      user.phone = requestedPhone;
      user.whatsapp = requestedPhone;
    }

    if (closeAllSessions) {
      user.tokenVersion = (user.tokenVersion || 0) + 1;
    }

    await user.save();

    await syncPasswordToJugaygana(user, newPassword, 'change-password');

    // Igual que en /change-password: token fresco para que el que cerró las
    // sesiones no se desloguee a sí mismo (solo caen los DEMÁS dispositivos).
    let freshToken = null;
    if (closeAllSessions) {
      freshToken = jwt.sign(
        { userId: user.id, username: user.username, role: user.role, tokenVersion: user.tokenVersion ?? 0 },
        JWT_SECRET,
        { expiresIn: '30d' }
      );
    }

    res.json({
      message: 'Contraseña cambiada. Entraste en modo temporal.',
      temporaryAccess: true,
      pendingAccessCode: pendingCode,
      phoneVerificationPending: true,
      sessionsClosed: closeAllSessions || false,
      token: freshToken
    });
  } catch (error) {
    logger.error(`Error en change-password/pending: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// ============================================
// LOGIN ÚNICO (SSO) A LA PLATAFORMA — botón "CASINO"
// ============================================
//
// El usuario ya está autenticado en VIPCARGAS (JWT), así que la plataforma sólo
// necesita nuestra API key + el username para emitir un link de acceso directo.
// NO se le pide la contraseña: con 1girox el cliente nunca más necesita conocer
// su clave del casino (antes el modal se la mostraba para copiar y pegar).
//
// El `redirect_url` lleva un código de UN SOLO USO que vence a los 60 segundos →
// el front tiene que redirigir apenas lo recibe. No se cachea ni se persiste.
//
// Cupo propio POR USUARIO (no por IP): con CGNAT de las telefónicas argentinas,
// limitar por IP dejaría a barrios enteros compartiendo cupo. Además protege el
// presupuesto de 60 req/min de la Partner API contra un cliente que spamee el botón.
const platformSessionLimiter = rateLimit({
  windowMs: 5 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => (req.user && req.user.userId) ? ('u:' + req.user.userId) : req.ip,
  validate: { keyGeneratorIpFallback: false },
  skipFailedRequests: true, // #696: los intentos que fallan (5xx, plataforma caída) no gastan el cupo: sólo cuentan los links emitidos
  message: { error: 'Demasiados intentos de entrar al casino. Esperá un momento.' }
});

async function platformSessionHandler(req, res) {
  const _t0 = Date.now(); // #696
  res.on('finish', () => { const ms = Date.now() - _t0; if (res.statusCode >= 400 || ms > 15000) { try { _diagPush('girox-sso', new Error(`HTTP ${res.statusCode} en ${ms} ms (${req.user && req.user.username})`)); } catch (_) {} } });
  res.on('close', () => { if (!res.writableFinished) { try { _diagPush('girox-sso', new Error(`conexión cerrada sin respuesta a los ${Date.now() - _t0} ms (${req.user && req.user.username})`)); } catch (_) {} } });
  try {
    // MULTI-PLATAFORMA (2026-10-16): `body.platform` elige a qué casino entrar. Sin
    // el campo (PWA vieja) → girox, como siempre. Una plataforma habilitada SIN API
    // conectada (Ganamos hoy) devuelve su link externo (`external:true`) en vez de
    // un SSO; una con API usa su adaptador con la misma lógica que girox.
    const _reqPlatform = platforms.normalizeId(req.body && req.body.platform) || platforms.DEFAULT_ID;
    if (_reqPlatform !== platforms.DEFAULT_ID) {
      const _plist = await platforms.listEnabled();
      const _p = _plist.find((x) => x.id === _reqPlatform);
      if (!_p) return res.status(400).json({ error: 'Esa plataforma no está disponible.' });
      const _ad = platforms.getAdapter(_reqPlatform);
      if (!_p.connected) {
        // #577 (owner): sin API conectada (entorno de prueba) "Jugar" abre igual el sitio público de la plataforma (sin login
        // único). Girox no tiene externalUrl: usa el sitio de juego del adaptador (GIROX_PLAY_URL, default 1girox.com).
        const _pub = _p.externalUrl || (_ad && typeof _ad.getPlayUrl === 'function' && _ad.getPlayUrl()) || null;
        if (!_pub) return res.status(503).json({ error: `${_p.name} todavía no está disponible. Escribinos por chat.` });
        return res.json({ success: true, external: true, noSso: true, platform: _reqPlatform, redirectUrl: _pub, platformUrl: _pub });
      }
      const _u = await User.findOne({ id: req.user.userId }).select('id username isBlocked isActive');
      if (!_u) return res.status(404).json({ error: 'Usuario no encontrado' });
      if (_u.isBlocked) return res.status(403).json({ error: 'Tu cuenta está bloqueada. Contactá al soporte.' });
      if (_u.isActive === false) return res.status(403).json({ error: 'Tu cuenta está inactiva. Contactá al soporte.' });
      let _s = await _ad.createSession(_u.username);
      if (!_s.success && _s.code === 'player_not_found') {
        const _sync = await _ad.syncUserToPlatform({ username: _u.username, password: crypto.randomBytes(12).toString('base64url') });
        if (_sync.success) {
          try { await User.updateOne({ id: _u.id }, { $set: { [`platforms.${_reqPlatform}`]: { status: _sync.alreadyExists ? 'linked' : 'synced', username: _u.username, syncedAt: new Date() } } }); } catch (_) {}
          _s = await _ad.createSession(_u.username);
        }
      }
      if (!_s.success) {
        logger.error(`[${_reqPlatform}-sso] falló para ${_u.username}: ${_s.error} (${_s.code})`);
        return res.status(503).json({ error: `${_p.name} no está respondiendo. Reintentá en un momento.` });
      }
      return res.json({ success: true, platform: _reqPlatform, redirectUrl: _s.redirectUrl, platformUrl: (_ad.getPlayUrl && _ad.getPlayUrl()) || _p.externalUrl || null });
    }

    // Si falta la config, se corta acá con un log EXPLÍCITO. Sin esto, el fallo se ve
    // como "el botón CASINO no abre" y hay que ir a adivinar por qué.
    if (!girox.isEnabled()) {
      logger.error('[girox-sso] IMPOSIBLE: la Partner API no está configurada — ' +
        `GIROX_API_URL=${process.env.GIROX_API_URL ? 'ok' : 'FALTA'} ` +
        `GIROX_API_KEY=${process.env.GIROX_API_KEY ? 'ok' : 'FALTA'}. ` +
        'Revisar GET /api/admin/girox/health.');
      // #577 (owner): sin API (entorno de prueba) "Jugar" abre igual el sitio público de Girox, sin login único.
      try { const _pub = girox.getPlayUrl && girox.getPlayUrl(); if (_pub) return res.json({ success: true, external: true, noSso: true, platform: 'girox', redirectUrl: _pub, platformUrl: _pub }); } catch (_) {}
      return res.status(503).json({ error: 'El casino no está disponible en este momento. Escribinos por chat.' });
    }

    const user = await User.findOne({ id: req.user.userId }).select('id username isBlocked isActive giroxSyncStatus');
    if (!user) {
      return res.status(404).json({ error: 'Usuario no encontrado' });
    }
    if (user.isBlocked) {
      return res.status(403).json({ error: 'Tu cuenta está bloqueada. Contactá al soporte.' });
    }
    if (user.isActive === false) {
      return res.status(403).json({ error: 'Tu cuenta está inactiva. Contactá al soporte.' });
    }

    let session = await girox.createSession(user.username);

    // AUTO-REPARACIÓN: si el jugador todavía no existe en la plataforma (usuario que
    // el script de migración no alcanzó, o creado mientras la migración corría), se
    // crea al vuelo y se reintenta UNA vez. La contraseña es random a propósito: el
    // acceso al casino es por SSO, y la clave real se sincroniza en el próximo login
    // o cambio de contraseña del usuario (ver syncPasswordToPlatform).
    if (!session.success && session.code === 'player_not_found') {
      logger.warn(`[girox-sso] ${user.username} no existe en la plataforma — creando al vuelo`);
      const provisional = crypto.randomBytes(12).toString('base64url');
      const sync = await girox.syncUserToPlatform({ username: user.username, password: provisional });
      if (!sync.success) {
        if (sync.code === 'username_taken_foreign') {
          // El username pertenece a un jugador de OTRA estructura de 1girox: esta
          // cuenta local nunca va a poder operar. Se marca para que el panel lo vea.
          await User.updateOne({ id: user.id }, { $set: { giroxSyncStatus: 'error', giroxSyncError: String(sync.error).slice(0, 500) } }).catch(() => {});
        }
        logger.error(`[girox-sso] no se pudo crear a ${user.username}: ${sync.error}`);
        return res.status(503).json({ error: 'No pudimos abrir tu cuenta en el casino. Escribinos por chat y lo resolvemos.' });
      }
      await User.updateOne({ id: user.id }, { $set: { giroxSyncStatus: sync.alreadyExists ? 'linked' : 'synced' } }).catch(() => {});
      session = await girox.createSession(user.username);
    }

    if (!session.success) {
      logger.error(`[girox-sso] falló para ${user.username}: ${session.error} (${session.code})`);
      try { _diagPush('girox-sso', new Error(`createSession ${user.username}: ${session.error} (${session.code}, http ${session.httpStatus || '-'})`)); } catch (_) {}
      return res.status(503).json({ error: 'El casino no está respondiendo. Reintentá en un momento.' });
    }

    // #848 (owner: "esos juegos quiero que entren logueados como si entraras del menú de Girox"): para abrir un JUEGO puntual (favoritos,
    // historias) el /auth/sso de 1girox va con `?token=` (lo acepta su página: guarda la sesión al instante) en vez del código de un solo
    // uso, que necesita dos consultas más antes de quedar logueado. Con el código, navegar al juego a los pocos segundos podía cortar el
    // login a mitad (el juego abría deslogueado en celulares lentos). Mismo origen y `embed` que el redirect_url que dio la API.
    let _redir = session.redirectUrl, _gameReady = false, _directGame = false, _gameStep = 'sin juego'; // #859: qué paso falló (se muestra en la app)
    // #861 (owner: "hace 1 h con lo mismo: que use el ingreso de autologin del menú de Girox"). BUG de #855/#857: el canje consumía el código de
    // ESTE ingreso y, si no salía el juego directo, se le pasaba al recuadro ese MISMO código ya usado ⇒ 1girox lo rechazaba y dejaba el
    // navegador DESLOGUEADO (manual 2.7). Ahora el intento del juego directo usa un ingreso APARTE; el recuadro, si no hay juego directo, abre
    // con el ingreso intacto = exactamente lo mismo que el botón de Girox (que sí entra logueado). Nada de `?token=` (no probado).
    try {
      const game = String((req.body && req.body.game) || '');
      // #863 (owner: "abre pero pantalla negra"): el `launch_url` del proveedor NO se deja mostrar dentro de otra página que no sea la de 1girox
      // ⇒ el juego directo queda APAGADO: el favorito abre Girox LOGUEADO (un solo ingreso, como el registro) + aviso "buscá X con la lupa".
      // `GIROX_DIRECT_GAME=1` lo vuelve a probar.
      // #866: la app pide el juego directo (`direct:true`) para abrirlo en PANTALLA COMPLETA (fuera del recuadro, donde el proveedor sí se ve).
      const mm = (process.env.GIROX_DIRECT_GAME === '1' || (req.body && req.body.direct === true)) ? /^\/play\/(\d{1,3})\/([\w.\-]{1,80})$/.exec(game) : null;
      if (!mm && /^\/play\//.test(game)) _gameStep = 'abrí el juego desde Girox';
      if (mm) {
        _gameStep = 'canje';
        // #862: el ORDEN importa — cada /session nuevo ANULA el anterior (manual 2.7). Se canjea el ingreso que ya se pidió (para pedir el juego)
        // y, si no sale directo, se pide UNO NUEVO al final para el recuadro: el último ingreso es siempre el que abre Girox (como el botón).
        const code = new URL(session.redirectUrl).searchParams.get('code');
        if (!code) _gameStep = 'sin código en el ingreso';
        else {
          const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 8000);
          let siteToken = null;
          try {
            const rx = await fetch(girox.getBaseUrl() + '/sso/exchange', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify({ code }), signal: ctrl.signal });
            const jx = await rx.json().catch(() => null);
            siteToken = (jx && (jx.token || (jx.data && jx.data.token))) || null;
            _gameStep = rx.ok && siteToken ? 'canje ok' : `canje rechazado (HTTP ${rx.status}${jx && jx.error ? ': ' + String(jx.error.code || jx.error.message || '').slice(0, 40) : ''})`;
          } catch (e) { _gameStep = 'canje: ' + e.message.slice(0, 60); } finally { clearTimeout(t); }
          if (siteToken) {
            const meta = await _gameLaunchMeta(mm[1], mm[2], String((req.body && req.body.gameName) || ''));
            if (!meta) _gameStep = 'juego no encontrado en el catálogo';
            else {
              const site = String(process.env.GIROX_SITE_API_URL || 'https://admin.1girox.com/api').replace(/\/$/, '');
              const q = new URLSearchParams({ id: String(meta.gid), launcher_key: meta.lk, aggregator_id: mm[1] });
              const c2 = new AbortController(); const t2 = setTimeout(() => c2.abort(), 10000);
              try {
                const rg = await fetch(`${site}/games/${encodeURIComponent(mm[2])}?${q}`, { headers: { Authorization: 'Bearer ' + siteToken, Accept: 'application/json' }, signal: c2.signal });
                const jg = await rg.json().catch(() => null); const lu = jg && (jg.launch_url || jg.url || (jg.data && (jg.data.launch_url || jg.data.url)));
                if (rg.ok && lu && /^https:\/\//.test(lu)) { _redir = lu; _directGame = true; _gameStep = 'directo'; }
                else _gameStep = `1girox no dio el juego (HTTP ${rg.status}${jg && (jg.message || jg.code) ? ': ' + String(jg.message || jg.code).slice(0, 60) : ''})`;
              } catch (e) { _gameStep = 'pedir el juego: ' + e.message.slice(0, 60); } finally { clearTimeout(t2); }
            }
          }
        }
        if (!_directGame) {
          // El código de `session` ya se canjeó (o se intentó) ⇒ ingreso NUEVO para el recuadro = exactamente el del botón de Girox.
          const fresh = await girox.createSession(user.username);
          _redir = fresh && fresh.success && fresh.redirectUrl ? fresh.redirectUrl : session.redirectUrl;
          logger.warn(`[girox-sso] ${user.username} ${game}: sin juego directo (${_gameStep}) ⇒ Girox logueado con un ingreso nuevo`);
        }
      }
    } catch (e) { _directGame = false; _redir = session.redirectUrl; _gameStep = 'error: ' + String(e.message).slice(0, 60); }
    res.json({
      success: true,
      redirectUrl: _redir,
      gameReady: _gameReady, // #855: la sesión de la web ya viene canjeada ⇒ el salto al juego puede ser corto
      directGame: _directGame, // #857: redirectUrl ES el juego (launch_url del proveedor): no hay que saltar a nada
      gameStep: _gameStep, // #859: diagnóstico visible
      platformUrl: girox.getPlayUrl()
    });
  } catch (error) {
    logger.error(`Error en platform session (SSO): ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
}

app.post('/api/platform/session', authMiddleware, platformSessionLimiter, platformSessionHandler);

// ════════════════════════════════════════════════════════════════════════════
// MULTI-PLATAFORMA — endpoints (2026-10-16). Ver src/platforms/ y docs/PLATFORMS.md.
// ════════════════════════════════════════════════════════════════════════════

// Plataformas HABILITADAS (lo que ve el cliente en la PWA: botones de la pregunta,
// botón del casino). Cualquier usuario logueado.
app.get('/api/platforms', authMiddleware, async (req, res) => {
  try {
    const list = await platforms.listEnabled();
    const s = await platforms.getSettings();
    let lastPlatform = null, preferredPlatform = null;
    try {
      const u = await User.findOne({ id: req.user.userId }).select('lastPlatform preferredPlatform').lean();
      lastPlatform = (u && u.lastPlatform) || null;
      preferredPlatform = (u && platforms.normalizeId(u.preferredPlatform)) || null;
      if (preferredPlatform && !list.some((p) => p.id === preferredPlatform)) preferredPlatform = null; // fijó una que ya no está habilitada
      if (!preferredPlatform && list.some((p) => p.id === s.defaultPlatform)) preferredPlatform = s.defaultPlatform; // #781: Girox con el tilde por defecto
    } catch (_) {}
    // #773 (velocidad): antes eran ~20 consultas a Mongo UNA DETRÁS DE OTRA (cada await esperaba al anterior) ⇒ 1,5-2 s por
    // pedido. Ahora van en 2 tandas en paralelo y los textos de COMANDOS salen de la caché de renderSystemCommand.
    const [choiceEnabled, minDep, wdMin, withdrawOtp, autoPct, dailyPct, supportName] = await Promise.all([
      platforms.isChoiceEnabled().catch(() => false), getMinDepositArs(), getWithdrawMinArs(), getWithdrawOtpRequired().catch(() => false),
      getAutoLoadBonusPct().catch(() => 0), getDailyRefundPct(), getSupportAgentName().catch(() => SUPPORT_NAME_DEFAULT)
    ]);
    const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('es-AR');
    const btnVars = { min: money(minDep), retiro_min: money(wdMin) };
    const rc = (name, def, vars) => renderSystemCommand(name, def, vars).catch(() => def);
    const [load, loadSub, withdraw, withdrawSub, homeText, newsText, refundPromo, supText, supSla] = await Promise.all([
      rc('/sys_load_btn', LOAD_BTN_DEFAULT, btnVars), rc('/sys_load_btn_sub', LOAD_BTN_SUB_DEFAULT, btnVars),
      rc('/sys_withdraw_btn', WITHDRAW_BTN_DEFAULT, btnVars), rc('/sys_withdraw_btn_sub', WITHDRAW_BTN_SUB_DEFAULT, btnVars),
      rc('/sys_home_banner', HOME_BANNER_DEFAULT, { pct: autoPct }),
      dailyPct > 0 ? rc('/sys_entry_news', ENTRY_NEWS_DEFAULT, { pct: dailyPct }) : Promise.resolve(null),
      rc('/sys_refund_promo', REFUND_PROMO_DEFAULT, { pct: dailyPct }),
      rc('/sys_support_intro', SUPPORT_INTRO_DEFAULT, { nombre: supportName }), rc('/sys_support_sla', SUPPORT_SLA_DEFAULT, {})
    ]);
    res.json({
      platforms: list.map((p) => { const ad = platforms.getAdapter(p.id); const play = (ad && typeof ad.getPlayUrl === 'function' && ad.getPlayUrl()) || p.externalUrl || null;
        return { id: p.id, name: p.name, emoji: p.emoji, connected: p.connected, externalUrl: p.externalUrl || null, playUrl: play, logoUrl: p.logoUrl || '', isDefault: p.isDefault }; }),
      askMode: s.askMode, askTimeoutMin: s.askTimeoutMin, defaultPlatform: s.defaultPlatform, lastPlatform, preferredPlatform,
      choiceEnabled, minDeposit: minDep, withdrawMinArs: wdMin, withdrawOtp, // #299 / #379 / #382
      depositRolloverX: await getDepositRolloverX().catch(() => 1), bonusRolloverX: await _giftRolloverX().catch(() => 5), // #885: avisos de rollover en la app
      // #385: textos de los botones de abajo de la carga automática (COMANDOS). #266 homeBanner · #349 entryNews · #372 refundPromo ·
      // #373 supportIntro (nombre de turno #377). text === null ⇒ el comando se vació en COMANDOS → la app no lo muestra.
      actionBtns: { load, loadSub, withdraw, withdrawSub },
      homeBanner: { pct: autoPct, text: homeText },
      entryNews: { pct: dailyPct, text: dailyPct > 0 ? newsText : null },
      refundPromo,
      supportIntro: { name: supportName, text: supText || '', sla: supSla || '' }
    });
  } catch (e) {
    logger.warn(`[platforms] GET /api/platforms: ${e.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// El cliente FIJA su plataforma (#225): las cargas van directo ahí sin preguntar.
// body { platform: '<id>' | null }  (null = volver a que se le pregunte en cada carga)
app.post('/api/platforms/preferred', authMiddleware, async (req, res) => {
  try {
    const raw = req.body ? req.body.platform : null;
    let pid = null;
    if (raw != null && raw !== '') {
      pid = platforms.normalizeId(raw);
      if (!pid) return res.status(400).json({ error: 'Plataforma inválida.' });
      const enabled = await platforms.listEnabled();
      if (!enabled.some((p) => p.id === pid)) return res.status(400).json({ error: 'Esa plataforma no está disponible.' });
      const adp = platforms.getAdapter(pid); // #298/#301: "Próximamente" (sin API) no se puede fijar — Girox SIEMPRE se puede
      if (pid !== platforms.DEFAULT_ID && (!adp || typeof adp.isConnected !== 'function' || !adp.isConnected())) return res.status(400).json({ error: 'Pronto: esta plataforma todavía no está disponible.' });
    }
    await User.updateOne({ id: req.user.userId }, { $set: { preferredPlatform: pid } });
    logger.info(`[platforms] ${req.user.username} fijó plataforma: ${pid || '(ninguna, pregunta en cada carga)'}`);
    res.json({ success: true, preferredPlatform: pid, label: pid ? platforms.labelOf(pid) : null });
  } catch (e) {
    logger.warn(`[platforms] preferred: ${e.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// El CLIENTE elige dónde cargar su transferencia (botones del mensaje
// kind='platform_choice'). Sólo puede resolver movimientos matcheados a ÉL.
app.post('/api/platform-choice', authMiddleware, authLimiter, async (req, res) => {
  try {
    const { movementId, platform } = req.body || {};
    if (!movementId || !platform) return res.status(400).json({ error: 'Faltan datos.' });
    const r = await _resolvePlatformChoice({ movementId: String(movementId), platformId: String(platform), by: 'user', requireUserId: req.user.userId });
    if (!r.ok) {
      const msgs = {
        invalid_platform: 'Esa plataforma no está disponible.',
        not_yours: 'Esa transferencia no es tuya.',
        not_pending: r.platform ? `Esa transferencia ya se cargó en ${platforms.labelOf(r.platform)}.` : 'Esa transferencia ya fue procesada.',
        error: 'No pudimos procesar tu elección. Escribinos por chat.'
      };
      return res.status(r.code === 'error' ? 500 : 409).json({ error: msgs[r.code] || msgs.error, code: r.code, platform: r.platform || null, status: r.status || null });
    }
    res.json({ success: true, platform: r.platform, label: platforms.labelOf(r.platform), redirected: r.redirected, url: r.url, status: r.status });
  } catch (e) {
    logger.error(`[platforms] POST /api/platform-choice: ${e.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// El AGENTE elige por el cliente (banner del chat del panel) — roles con permiso de carga.
// #693 (owner): DEVOLVER una transferencia MENOR a la carga mínima: rebota la plata al CBU de origen por hgcash (cash-out) y le avisa
// al cliente por Soporte ("tu devolución ya fue hecha con éxito; recordá que la carga mínima es $5.000"). Idempotente por externalID
// `refund-<movementId>`. Sólo movimientos entrantes no cargados (needs_review / no_match / pending) con monto < carga mínima.
const BELOW_MIN_REFUNDED_DEFAULT = '✅ Tu devolución de ${monto} ya fue hecha con éxito a tu cuenta de origen (puede demorar unos minutos en verse en tu banco).\n\n💵 Recordá que la carga mínima es de ${min}: con ese monto o más se acredita sola.';
app.get('/api/admin/support/:userId/below-min', authMiddleware, async (req, res) => {
  try {
    if (!SUPPORT_ROLES.includes(req.user.role)) return res.status(403).json({ error: 'Acceso denegado' });
    let minDep = MIN_DEPOSIT_ARS_DEFAULT; try { minDep = Number(await getMinDepositArs()) || MIN_DEPOSIT_ARS_DEFAULT; } catch (_) {}
    const since = new Date(Date.now() - 15 * 86400000);
    const items = await BankMovement.find({ matchedUserId: req.params.userId, direction: /inbound/i, createdAt: { $gte: since }, amount: { $gt: 0, $lt: minDep }, matchStatus: { $in: ['needs_review', 'no_match', 'pending', 'refunded', 'error'] } })
      .sort({ createdAt: -1 }).limit(10).select('movementId amount fromName fromCBU matchStatus chargeError refundedAt refundHgId createdAt').lean();
    res.json({ success: true, minDepositArs: minDep, items });
  } catch (e) { logger.warn(`[below-min] list: ${e.message}`); res.status(500).json({ error: 'Error del servidor' }); }
});
// #803: núcleo de la DEVOLUCIÓN de una transferencia menor al mínimo (lo usan el botón del panel y la devolución AUTOMÁTICA).
// Idempotente: externalID 'refund-<movementId>' (hgcash responde duplicate) + reserva atómica del movimiento ('refunding').
async function _refundBelowMinMovement(mv, { by, amount, minDep, toCBU }) {
  const lock = await BankMovement.findOneAndUpdate({ movementId: mv.movementId, matchStatus: { $in: ['needs_review', 'no_match', 'pending', 'error'] } }, { $set: { matchStatus: 'refunding' } }, { new: true }).lean();
  if (!lock) return { ok: false, error: 'El movimiento ya está siendo devuelto o fue procesado.' };
  const release = (err) => BankMovement.updateOne({ movementId: mv.movementId, matchStatus: 'refunding' }, { $set: { matchStatus: mv.matchStatus || 'needs_review', refundError: String(err || '').slice(0, 300) } }).catch(() => {});
  let accountId = await resolveHgcashAccountId();
  if (!accountId) { await release('sin accountId'); return { ok: false, error: 'No se pudo determinar la cuenta hgcash a debitar (accountId).' }; }
  const baseUrl = getPublicBaseUrl();
  const build = (acct) => hgcashPay.createCashOut({ accountId: acct, amount, toCBU, toName: mv.fromName || undefined, toCUIT: mv.fromCUIT || undefined, concept: 'Devolucion carga menor al minimo - PICA ROJA', externalID: ('refund-' + mv.movementId).slice(0, 100), webhookUrl: `${baseUrl}/api/hgcash/webhook` });
  let result = await build(accountId);
  if (!result.ok && result.httpStatus === 403) { const fresh = await resolveHgcashAccountId({ force: true }); if (fresh && String(fresh) !== String(accountId)) { accountId = fresh; result = await build(accountId); } }
  const dup = !result.ok && result.httpStatus === 409 && /duplicate/i.test(String(result.error));
  if (!result.ok && !dup) { await release(result.error); _bankPayoutFailed(result.error, null).catch(() => {}); return { ok: false, error: 'hgcash rechazó la devolución: ' + result.error }; }
  _bankPayoutOk().catch(() => {});
  const hgId = dup ? null : (result.data && result.data.id) || null;
  await BankMovement.updateOne({ movementId: mv.movementId }, { $set: { matchStatus: 'refunded', refundedAt: new Date(), refundHgId: hgId, refundBy: by, refundError: null, chargeError: `devuelta al origen ($${amount.toLocaleString('es-AR')} < mínimo $${minDep.toLocaleString('es-AR')})` } });
  // #803 (owner): "notificalo donde siempre, como rechazado / pago rebotado" ⇒ en Cargas pendientes (pestaña resueltas) figura como
  // REBOTADA y devuelta, y el panel se entera en vivo (deposit_review).
  if (mv.matchedComprobanteId) { try { await Comprobante.updateOne({ id: mv.matchedComprobanteId }, { $set: { reviewStatus: 'rejected', reviewResolution: 'below_min_refund', reviewedBy: by, reviewedAt: new Date(), reviewNote: `Rebotada: $${amount.toLocaleString('es-AR')} es menor a la carga mínima de $${minDep.toLocaleString('es-AR')}. Devuelta al CBU de origen.` } }); } catch (_) {} }
  try { if (mv.matchedUserId) _emitDepositReviewUpdate(mv.matchedUserId, { action: 'rejected', id: mv.matchedComprobanteId || null, reason: 'below_min_refund', amount }); } catch (_) {}
  let user = null; if (mv.matchedUserId) user = await User.findOne({ id: mv.matchedUserId }).select('id username').lean();
  if (user) {
    try {
      const txt = await renderSystemCommand('/sys_below_min_refunded', BELOW_MIN_REFUNDED_DEFAULT, { monto: amount.toLocaleString('es-AR'), min: minDep.toLocaleString('es-AR') });
      if (txt) await _sendUserSystemMessage(user, txt, { metadata: { kind: 'below_min_refunded', movementId: mv.movementId, amount }, push: { title: '↩️ Te devolvimos tu transferencia', body: `Te devolvimos $${amount.toLocaleString('es-AR')}. La carga mínima es de $${minDep.toLocaleString('es-AR')}.` } });
    } catch (e) { logger.warn(`[below-min] aviso al cliente falló: ${e.message}`); }
    await _emitAdminOnlyChatNote(user.id, user.username, `↩️ DEVOLUCIÓN ${by === 'auto' ? 'AUTOMÁTICA' : 'hecha por ' + by}: $${amount.toLocaleString('es-AR')} al CBU de origen ${toCBU} (transferencia menor al mínimo de $${minDep.toLocaleString('es-AR')}). NO se cargó. hgcash id: ${hgId || 'ya existía'}.`);
  }
  logger.info(`[below-min] devuelta mov=${mv.movementId} $${amount} → ${toCBU} por ${by} hg=${hgId || 'dup'}`);
  return { ok: true, hgId, dup };
}
app.post('/api/admin/hgcash/movements/:movementId/refund', authMiddleware, async (req, res) => {
  try {
    if (!['admin', 'depositor', 'withdrawer'].includes(req.user.role)) return res.status(403).json({ error: 'Acceso denegado' });
    if (!hgcashPay.isEnabled()) return res.status(503).json({ error: 'hgcash no está configurado (token de API).' });
    const mv = await BankMovement.findOne({ movementId: req.params.movementId }).lean();
    if (!mv) return res.status(404).json({ error: 'Movimiento no encontrado' });
    if (mv.matchStatus === 'refunded') return res.json({ success: true, already: true, message: 'Esta transferencia ya fue devuelta.' });
    if (!/inbound/i.test(String(mv.direction || ''))) return res.status(400).json({ error: 'Sólo se devuelven transferencias ENTRANTES.' });
    if (!['needs_review', 'no_match', 'pending', 'error'].includes(mv.matchStatus)) return res.status(400).json({ error: `No se puede devolver: el movimiento está "${mv.matchStatus}" (ya cargado o en proceso).` });
    const amount = Number(mv.amount) || 0;
    let minDep = MIN_DEPOSIT_ARS_DEFAULT; try { minDep = Number(await getMinDepositArs()) || MIN_DEPOSIT_ARS_DEFAULT; } catch (_) {}
    if (!(amount > 0) || amount >= minDep) return res.status(400).json({ error: `Sólo se devuelven transferencias menores a la carga mínima ($${minDep.toLocaleString('es-AR')}). Esta es de $${amount.toLocaleString('es-AR')}.` });
    const toCBU = String(mv.fromCBU || '').replace(/\D/g, '');
    if (toCBU.length !== 22) return res.status(400).json({ error: 'El movimiento no tiene el CBU/CVU de origen (22 dígitos): hay que devolverlo a mano.' });
    const r = await _refundBelowMinMovement(mv, { by: req.user.username, amount, minDep, toCBU });
    if (!r.ok) return res.status(400).json({ error: r.error });
    res.json({ success: true, amount, hgId: r.hgId, dup: r.dup });
  } catch (e) { logger.error(`[below-min] refund: ${e.message}`); res.status(500).json({ error: 'Error del servidor' }); }
});
