// ============================================
// RUTAS DE MENSAJES
// ============================================

// OPTIMIZADO: Sin logs, con proyección mínima
app.get('/api/messages/:userId', authMiddleware, async (req, res) => {
  try {
    const { userId } = req.params;
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    const before = req.query.before ? new Date(req.query.before) : null;

    const allowedRoles = ['admin', 'depositor', 'withdrawer', 'comunidad'];
    const isAdminRole = allowedRoles.includes(req.user.role);
    if (!isAdminRole && req.user.userId !== userId) {
      return res.status(403).json({ error: 'Acceso denegado' });
    }

    const matchStage = {
      $or: [
        { senderId: userId },
        { receiverId: userId }
      ]
    };
    if (!isAdminRole) {
      matchStage.adminOnly = { $ne: true };
    }
    if (before) {
      matchStage.timestamp = { $lt: before };
    }
    // #377: el cliente sólo ve el chat NUEVO de Soporte (desde Config['supportChannelSince']); el panel ve todo.
    // #380: y SOLO el canal de soporte (lo suyo, las respuestas de la columna Soporte y los mensajes de sistema): lo que
    // un agente escribe desde la sección Chats (chat viejo) no le llega. El panel pide lo mismo con ?channel=support.
    if (!isAdminRole || req.query.channel === 'support') {
      // #602 (owner): SOPORTE DE PROBLEMAS: sólo la charla (lo que escribe el cliente en texto, las respuestas de la columna Soporte y
      // los avisos propios del soporte). Fuera comprobantes (imágenes) y los mensajes de sistema de cargas / regalos / retiros.
      matchStage.$and = [{ $or: [
        { channel: 'support', type: { $ne: 'image' } },
        { 'metadata.channel': 'support' },
        { 'metadata.kind': { $in: ['support_ack', 'support_closed'] } }
      ] }];
    }
    if (!isAdminRole) {
      const since = await getSupportChannelSince();
      // #613 (owner): el cierre (manual #602 o automático #401) YA NO corta el historial: el cliente conserva la charla vieja con
      // fechas y ve el aviso "chat cerrado" (metadata.kind support_closed) fijado abajo de las opciones. `supportSessionSince`
      // sigue marcando el último cierre para el panel / cron, pero no filtra acá.
      if (since) matchStage.timestamp = Object.assign({}, matchStage.timestamp || {}, { $gte: since });
    }

    const messages = await Message.aggregate([
      { $match: matchStage },
      { $sort: { timestamp: -1 } },
      { $limit: limit },
      { $sort: { timestamp: 1 } },
      {
        $project: {
          _id: 0, id: 1, senderId: 1, senderUsername: 1, senderRole: 1,
          receiverId: 1, receiverRole: 1, content: 1, type: 1, read: 1,
          adminOnly: 1, timestamp: 1, channel: 1,
          // metadata: botones de la PWA (multi-plataforma: kind platform_choice / platform_link)
          metadata: 1
        }
      }
    ]);

    const hasMore = messages.length === limit;
    const oldestTimestamp = messages.length > 0 ? messages[0].timestamp : null;

    res.json({ messages, hasMore, oldestTimestamp });
  } catch (error) {
    logger.error(`Error obteniendo mensajes: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

app.get('/api/conversations', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    // Agregación en Mongo: agrupa por el usuario de la conversación, toma el
    // último mensaje y cuenta los no leídos. Evita traer TODA la colección de
    // mensajes y usuarios a Node y el loop O(mensajes × usuarios) anterior.
    const rows = await Message.aggregate([
      { $match: { timestamp: { $gte: new Date(Date.now() - 3 * 86400000) } } }, // #957: acota por índice (antes barría toda la colección)
      { $sort: { timestamp: -1 } },
      { $addFields: {
        convUserId: {
          $cond: [
            { $eq: ['$senderRole', 'user'] },
            '$senderId',
            { $cond: [{ $eq: ['$receiverRole', 'user'] }, '$receiverId', null] }
          ]
        }
      }},
      { $match: { convUserId: { $ne: null } } },
      { $group: {
        _id: '$convUserId',
        lastMessage: { $first: '$$ROOT' },
        unreadCount: {
          $sum: { $cond: [
            { $and: [{ $eq: ['$receiverRole', 'admin'] }, { $ne: ['$read', true] }] },
            1, 0
          ] }
        }
      }},
      { $sort: { 'lastMessage.timestamp': -1 } }
    ]);

    const userIds = rows.map(r => r._id);
    const users = await User.find({ id: { $in: userIds } }, { id: 1, username: 1, accountNumber: 1 }).lean();
    const userMap = {};
    users.forEach(u => { userMap[u.id] = u; });

    const conversations = rows.map(r => {
      const u = userMap[r._id] || {};
      const lm = r.lastMessage || {};
      delete lm.convUserId;
      return {
        userId: r._id,
        username: u.username || 'Desconocido',
        accountNumber: u.accountNumber || '',
        lastMessage: lm,
        unreadCount: r.unreadCount || 0
      };
    });

    res.json(conversations);
  } catch (error) {
    console.error('Error obteniendo conversaciones:', error);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

