  // página (el CBU vive en la tarjeta de carga). Idempotente: sólo si todavía están.
  try {
    const w = await Command.findOne({ name: '/sys_welcome' }).lean();
    if (w && w.response && /CBU activo:|Link de pagina:|Escribe aquí para hablar con un agente/.test(w.response)) {
      const cleaned = String(w.response)
        .replace(/\n*CBU activo:[^\n]*\{cbu\}[^\n]*/g, '')
        .replace(/\n*Link de pagina:[^\n]*/g, '')
        .replace(/💬 Escribe aquí para hablar con un agente\./, 'Este es tu SOPORTE EN VIVO: acá te explicamos cómo funciona el servicio y respondemos cualquier duda. Para cargar, tocá "Cargar" arriba.')
        .replace(/\n{3,}/g, '\n\n').trim();
      if (cleaned && cleaned !== w.response) {
        await Command.updateOne({ name: '/sys_welcome' }, { $set: { response: cleaned } });
        console.log('✅ /sys_welcome: CBU/link viejos quitados de la bienvenida');
      }
    }
  } catch (e) { console.warn('[startup-migration] /sys_welcome:', e.message); }

  // #228 (owner 2026-10-16): ruleta diaria con la app instalada, SOLO clientes activos de la semana,
  // premios $5.000 / 100% / 50%. One-shot (flag): después se edita desde el panel → Ruleta diaria.
  try {
    if (!(await getConfig('migration_roulette_v3_done', false))) {
      await Config.set('dailyRoulette', { enabled: true, requireAppInstalled: true, minCargas30d: 0, requireActiveWeek: true, prizes: ROULETTE_PRIZES_2026_10 }, 'startup-migration');
      await Config.set('migration_roulette_v3_done', true, 'startup-migration');
      console.log('✅ Ruleta diaria configurada (#228): app instalada + activo de la semana · $5.000 / 100% / 50%');
    }
    // #374 (owner 2026-10-18): premios 20% / 50% / 100% / $5.000 / $100.000 (1 cada 1.000) + sin premio; se desbloquea
    // con una carga mínima en la semana. One-shot: después se edita en el panel → Ruleta diaria.
    // #377: el cliente deja de ver el chat viejo de cargas: sólo ve lo posterior a esta fecha (soporte nuevo).
    if (!(await getConfig('supportChannelSince', null))) {
      await Config.set('supportChannelSince', new Date().toISOString(), 'startup-migration');
      console.log('✅ Soporte paralelo (#377): el cliente ve el chat desde ahora; el panel ve todo');
    }
    if (!(await getConfig('migration_roulette_v4_done', false))) {
      await Config.set('dailyRoulette', { enabled: true, requireAppInstalled: true, minCargas30d: 0, requireActiveWeek: true, prizes: ROULETTE_PRIZES_2026_10_18 }, 'startup-migration');
      await Config.set('migration_roulette_v4_done', true, 'startup-migration');
      console.log('✅ Ruleta diaria (#374): 20% 45% · 50% 22% · 100% 8% · $5.000 4,9% · $100.000 0,1% · sin premio 20%');
    }
  } catch (e) { console.warn('[startup-migration] ruleta v3:', e.message); }

  // #235 (owner): "en el soporte borrá todo lo que es servicio y resumí". Si la bienvenida guardada es
  // la larga (de #221/#222) se reemplaza por la corta; /sys_como_funciona largo → vacío (no se manda).
