// Devuelve los datos bancarios guardados del usuario (para autocompletar el
// modal de retiro) junto con el estado de verificación de su teléfono.
app.get('/api/withdrawal/account', authMiddleware, async (req, res) => {
  try {
    const user = await User.findOne({ id: req.user.userId }).lean();
    if (!user) return res.status(404).json({ error: 'Usuario no encontrado' });
    const acc = user.withdrawalAccount || {};
    res.json({
      account: {
        titular: acc.titular || '',
        cbu: acc.cbu || '',
        alias: acc.alias || '',
        savedAt: acc.savedAt || null
      },
      phoneVerified: user.phoneVerified === true,
      phone: user.phone || user.whatsapp || null
    });
  } catch (error) {
    logger.error(`Error en withdrawal/account: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// Solicitud de retiro autogestionada. Requiere teléfono verificado por SMS.
// Verifica el saldo real en JugaYGana, ejecuta el retiro, guarda los datos
// bancarios (opcional) y manda un mensaje automático al chat para que el agente
// procese la transferencia bancaria.
// #382: código SMS para confirmar el retiro. Va SIEMPRE al teléfono verificado de la cuenta (no se puede elegir otro).
app.post('/api/withdrawal/send-otp', authMiddleware, sensitiveLimiter, smsIpLimiter, async (req, res) => {
  try {
    if (!(await getWithdrawOtpRequired())) return res.json({ success: true, required: false });
    const user = await User.findOne({ id: req.user.userId }).select('phone phoneVerified').lean();
    if (!user || user.phoneVerified !== true || !user.phone) {
      return res.status(400).json({ error: 'Para retirar tu premio necesitás verificar tu teléfono por SMS.', code: 'PHONE_VERIFICATION_REQUIRED' });
    }
    const result = await generateAndSendOTP(user.phone, 'withdraw');
    if (!result.success) return res.status(429).json({ error: result.error || 'No se pudo enviar el SMS. Esperá un momento y probá de nuevo.' });
    const maskedPhone = String(user.phone).replace(/(\+\d{1,4})\d+(\d{4})$/, '$1****$2');
    res.json({ success: true, required: true, phone: maskedPhone });
  } catch (e) { logger.error(`/api/withdrawal/send-otp: ${e.message}`); res.status(500).json({ error: 'Error del servidor' }); }
});

// #442: estado del banco para la app (al abrir el modal de retiro). Si está con fallas, anota al cliente para avisarle.
app.get('/api/withdrawal/bank-status', authMiddleware, async (req, res) => {
  try {
    const o = await getBankOutage();
    if (o.active) _addBankOutageWaiter(req.user.userId).catch(() => {});
    res.json({ outage: !!o.active, since: o.since, pause: (await getBankSettings()).pauseWithdrawals, message: o.active ? await renderSystemCommand('/sys_bank_down', BANK_DOWN_DEFAULT, {}) : null });
  } catch (e) { res.json({ outage: false }); }
});
app.get('/api/admin/bank-outage', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const o = await getBankOutage(); const w = (await getConfig('bankOutageWaiters', [])) || [];
    const history = await BankOutageEvent.find({}).sort({ startedAt: -1 }).limit(30).lean(); // #444
    const texts = {};
    for (const [k, name, def] of [['down', '/sys_bank_down', BANK_DOWN_DEFAULT], ['failClient', '/sys_bank_fail_client', BANK_FAIL_CLIENT_DEFAULT], ['up', '/sys_bank_up', BANK_UP_DEFAULT], ['upPending', '/sys_bank_up_pending', BANK_UP_PENDING_DEFAULT]]) {
      try { const c = await Command.findOne({ name }).select('response').lean(); texts[k] = (c && c.response) || def; } catch (_) { texts[k] = def; }
    }
    res.json({ success: true, ...o, waiters: w.length, failedWaiters: w.filter((x) => x && x.kind === 'failed').length, failStreak: _bankFailStreak, settings: await getBankSettings(), texts, history, canEdit: ['admin', 'withdrawer'].includes(req.user.role) });
  } catch (e) { res.status(500).json({ error: 'Error del servidor' }); }
});
app.post('/api/admin/bank-outage', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!['admin', 'withdrawer'].includes(req.user.role)) return res.status(403).json({ error: 'Solo admin general o pagos.' });
    // #443: settings editables (auto on/off, umbral, pausar retiros, avisar al que le falló) — se guardan si vienen.
    if (req.body && req.body.settings && typeof req.body.settings === 'object') {
      const s = req.body.settings; const cur = await getBankSettings();
      const next = {
        autoEnabled: typeof s.autoEnabled === 'boolean' ? s.autoEnabled : cur.autoEnabled,
        failThreshold: Math.max(1, Math.min(10, parseInt(s.failThreshold, 10) || cur.failThreshold)),
        pauseWithdrawals: typeof s.pauseWithdrawals === 'boolean' ? s.pauseWithdrawals : cur.pauseWithdrawals,
        notifyFailedClient: typeof s.notifyFailedClient === 'boolean' ? s.notifyFailedClient : cur.notifyFailedClient
      };
      await Config.set('bankOutageSettings', next, req.user.username);
    }
    // #444: los 4 mensajes editables desde la misma tarjeta (son los comandos /sys_bank_*).
    if (req.body && req.body.texts && typeof req.body.texts === 'object') {
      const map = { down: '/sys_bank_down', failClient: '/sys_bank_fail_client', up: '/sys_bank_up', upPending: '/sys_bank_up_pending' };
      for (const k of Object.keys(map)) {
        const v = req.body.texts[k];
        if (typeof v === 'string' && v.trim()) await Command.updateOne({ name: map[k] }, { $set: { response: v.trim().slice(0, 1500) } });
      }
    }
    let r = { changed: false };
    if (req.body && typeof req.body.active === 'boolean') {
      r = await setBankOutage(req.body.active, { mode: 'manual', reason: req.body.reason, by: req.user.username });
      if (req.body.active) _bankFailStreak = 0;
    }
    res.json({ success: true, changed: r.changed, state: await getBankOutage(), settings: await getBankSettings() });
  } catch (e) { res.status(500).json({ error: 'Error del servidor' }); }
});
// #714: handler nombrado para que la ruta de prueba (/api/test/withdraw) pueda reusarlo con req._testBypass (sin teléfono ni SMS).
async function _withdrawalRequestHandler(req, res) {
  let withdrawLockAcquired = false;
  try {
    const { titular, cbu, alias, amount, saveData } = req.body || {};
    const username = req.user.username;
    // MULTI-PLATAFORMA (2026-10-16): de qué plataforma salen las fichas. Sin el campo
    // (PWA vieja) → girox. Sólo plataformas con API conectada (sin API no hay saldo que leer).
    const _wdPlatform = platforms.normalizeId(req.body && req.body.platform) || platforms.DEFAULT_ID;
    const _wdAdapter = platforms.getAdapter(_wdPlatform) || girox;
    if (typeof _wdAdapter.isConnected === 'function' && !_wdAdapter.isConnected()) {
      return res.status(400).json({ error: `Los retiros de ${platforms.labelOf(_wdPlatform, { emoji: false })} no se hacen desde acá todavía.`, code: 'PLATFORM_NOT_CONNECTED' });
    }

    // #442: banco con fallas → no se toma el retiro; se avisa y se anota al cliente para avisarle cuando se normalice.
    const _outage = await getBankOutage();
    if (_outage.active) {
      _addBankOutageWaiter(req.user.userId, 'waiter').catch(() => {});
      // #814 (owner: "es un sistema automático, no podemos estar trabando a la gente"): la alerta AUTOMÁTICA (pagos que fallaron) ya
      // no frena las solicitudes: se toman igual y el reintento automático (_payoutAutoRetryTick) las paga cuando el banco responde.
      // Sólo la alerta puesta A MANO por un agente pausa los retiros.
      if (_outage.mode !== 'auto' && (await getBankSettings()).pauseWithdrawals) return res.status(503).json({ error: await renderSystemCommand('/sys_bank_down', BANK_DOWN_DEFAULT, {}), code: 'BANK_OUTAGE' });
    }

    const amountNum = Number(amount);
    const _wMin = await getWithdrawMinArs(); // #379
    if (!amountNum || amountNum < _wMin) {
      return res.status(400).json({ error: 'El monto mínimo de retiro es $' + _wMin.toLocaleString('es-AR') });
    }

    const titularT = (typeof titular === 'string' ? titular : '').trim();
    const cbuT = (typeof cbu === 'string' ? cbu : '').trim();
    const aliasT = (typeof alias === 'string' ? alias : '').trim();
    if (!titularT || !cbuT || !aliasT) {
      return res.status(400).json({ error: 'Completá titular, CVU/CBU y alias' });
    }

    const user = await User.findOne({ id: req.user.userId });
    if (!user) return res.status(404).json({ error: 'Usuario no encontrado' });

    // Para retirar, la cuenta debe tener el teléfono verificado por SMS.
    // El registro es sin SMS, pero el retiro siempre exige verificación.
    if (user.isBlocked === true || user.isActive === false) return res.status(403).json({ error: 'Tu cuenta no puede retirar en este momento. Escribinos por Soporte.', code: 'ACCOUNT_BLOCKED' }); // #954
    if (user.phoneVerified !== true && !req._testBypass) { // #714: la prueba del tester no exige teléfono
      return res.status(400).json({
        error: 'Para retirar tu premio necesitás verificar tu teléfono por SMS.',
        code: 'PHONE_VERIFICATION_REQUIRED'
      });
    }
    // #382: código SMS de ESTE retiro (anti-estafa). Se valida antes del lock y del saldo.
    if (await getWithdrawOtpRequired() && !req._testBypass) { // #714: ni SMS
      const otpCode = String((req.body && req.body.otpCode) || '').trim();
      if (!/^\d{6}$/.test(otpCode)) return res.status(400).json({ error: 'Ingresá el código SMS de 6 dígitos para confirmar el retiro.', code: 'WITHDRAW_OTP_REQUIRED' });
      const v = await verifyOTP(user.phone, otpCode, 'withdraw');
      if (!v.valid) return res.status(400).json({ error: v.error || 'Código incorrecto o expirado.', code: 'WITHDRAW_OTP_INVALID' });
    }

    // Lock anti-doble-retiro: serializa los retiros concurrentes del mismo
    // usuario para que dos requests no pasen ambos el chequeo de saldo y
    // ejecuten un retiro doble. Se libera en el finally del handler.
    if (!await acquireRefundLock(req.user.userId, 'withdraw')) {
      return res.status(429).json({ error: 'Ya tenés un retiro en proceso. Esperá unos segundos.' });
    }
    withdrawLockAcquired = true;

    // Chequear saldo real en JugaYGana (sólo validación de UX al solicitar: el cliente
    // no puede pedir más de lo que tiene EN ESTE MOMENTO). El DESCUENTO REAL de las
    // fichas ocurre recién cuando el AGENTE confirma el pago (/api/admin/payouts/:id/pay),
    // NO acá. Así, si el cliente se juega las fichas en el mientras, al confirmar el
    // descuento falla y no se paga — y al rechazar no hay que devolver nada.
    // CON retry (2 intentos): JUGAYGANA es flaky y a veces el lookup de saldo tarda/falla;
    // el reintento entra la mayoría de las veces. Cada intento ya falla rápido (timeout 12s).
    const balanceResult = await _wdAdapter.getUserBalanceWithRetry(username, { maxAttempts: 2, baseDelayMs: 400 });
    if (!balanceResult.success) {
      return res.status(503).json({
        error: 'La plataforma está demorada en este momento. Esperá unos segundos y volvé a intentar el retiro.',
        code: 'PLATFORM_SLOW'
      });
    }
    // ⚠️ Se valida contra `available`, NO contra `balance`. Con el rollover activo en
    // 1girox el jugador puede tener saldo que todavía no puede retirar. Si validáramos
    // contra el total, la solicitud se aceptaría, el agente la trabajaría, y recién al
    // confirmar la plataforma la rechazaría con `rollover_locked` — un retiro colgado
    // en el panel y un cliente esperando plata que nunca iba a poder sacar.
    const available = Number(balanceResult.available != null ? balanceResult.available : balanceResult.balance) || 0;
    if (available < amountNum) {
      // #881: si la diferencia es por rollover, se explica cuánto es bono y cuánto falta apostar.
      const _rs = _rolloverSummary(balanceResult);
      const _rt = _rs.locked > 0 ? _rolloverText(_rs, amountNum) : null;
      return res.status(400).json({
        error: _rt ? `🔒 ${_rt}`
          : available <= 0
          ? 'No tenés saldo disponible para retirar.'
          : `Saldo insuficiente. Tu saldo disponible es $${available.toLocaleString('es-AR')}.`,
        code: _rt ? 'ROLLOVER_LOCKED' : 'INSUFFICIENT_BALANCE',
        balance: available, rollover: _rs
      });
    }

    // Dedup anti-doble-solicitud: si ya hay un retiro pendiente del MISMO monto creado
    // hace pocos minutos, NO creamos otro (evita duplicados si el cliente reintenta por
    // un error de red/timeout). Devolvemos éxito idempotente.
    const recentDup = await PendingPayout.findOne({
      userId: user.id, amount: amountNum, status: 'pending_review',
      createdAt: { $gte: new Date(Date.now() - 10 * 60 * 1000) }
    }).lean();
    if (recentDup) {
      return res.json({
        success: true, duplicate: true,
        message: `Ya recibimos tu solicitud de retiro de $${amountNum.toLocaleString('es-AR')}. Un agente la está procesando.`
      });
    }

    // Crear el "pago pendiente" SIN descontar fichas (deductAtPay:true). El agente lo
    // verifica y, al CONFIRMAR el pago, recién ahí se descuentan las fichas (con
    // verificación anti-fantasma) y, si el descuento sale OK, se paga automático por
    // hgcash. El saldo del cliente NO baja todavía.
    let _newPayoutId = null;
    try {
      _newPayoutId = uuidv4();
      await PendingPayout.create({
        id: _newPayoutId, userId: user.id, username: user.username,
        platform: _wdPlatform,
        amount: amountNum, titular: titularT, cbu: cbuT, alias: aliasT,
        status: 'pending_review',
        deductAtPay: true,         // ← flujo nuevo: descontar al confirmar, no al solicitar
        balanceBefore: available,  // saldo al solicitar (referencia para el agente)
        createdAt: new Date()
      });
    } catch (ppErr) {
      logger.error(`[withdrawal/request] no se pudo crear PendingPayout para ${user.username}: ${ppErr.message}`);
      return res.status(500).json({ error: 'No pudimos registrar tu solicitud de retiro. Probá de nuevo en un momento.' }); // #413
    }

    // Guardar datos bancarios para la próxima vez (si el usuario lo pidió).
    if (saveData) {
      user.withdrawalAccount = { titular: titularT, cbu: cbuT, alias: aliasT, savedAt: new Date() };
      await user.save();
    }

    const amountFmt = '$' + amountNum.toLocaleString('es-AR');

    // 1. Mensaje del usuario hacia el agente con los datos del retiro.
    const withdrawMsg = await Message.create({
      id: uuidv4(),
      senderId: req.user.userId,
      senderUsername: req.user.username,
      senderRole: 'user',
      receiverId: 'admin',
      receiverRole: 'admin',
      content:
        `💸 *SOLICITUD DE RETIRO*\n\n` +
        `👤 Titular: ${titularT}\n` +
        `🔢 CVU/CBU: ${cbuT}\n` +
        `📱 Alias: ${aliasT}\n` +
        `💵 Monto: ${amountFmt}`,
      type: 'text',
      timestamp: new Date(),
      read: false
    });

    // 2. Confirmación automática del sistema hacia el usuario (editable /sys_withdrawal_request).
    // El template usa "${amount}" y reemplazamos {amount} por el monto ya
    // formateado con separador de miles, SIN el signo $ (el $ va en el template).
    const withdrawConfirmContent = await renderSystemCommand(
      '/sys_withdrawal_request',
      '⏳ Recibimos tu solicitud de retiro de ${amount}.\nUn agente la está procesando y te confirma la transferencia en breve. ¡Gracias!',
      { amount: amountNum.toLocaleString('es-AR') }
    );
    // null = /sys_withdrawal_request vaciado a propósito → no se manda la confirmación.
    const withdrawConfirmMsg = withdrawConfirmContent ? await Message.create({
      id: uuidv4(),
      senderId: 'system',
      senderUsername: 'Sistema',
      senderRole: 'admin',
      receiverId: req.user.userId,
      receiverRole: 'user',
      content: withdrawConfirmContent,
      type: 'text',
      timestamp: new Date(),
      read: false
    }) : null;

    // 3. Mover el chat a "Pagos" automáticamente: el retiro lo gestiona el área
    //    de pagos. Antes el ChatStatus no se tocaba, así que si el chat estaba
    //    cerrado (o sin abrir) la solicitud de retiro podía pasar desapercibida.
    try {
      await ChatStatus.findOneAndUpdate(
        { userId: req.user.userId },
        {
          userId: req.user.userId,
          username: req.user.username,
          status: 'payments',
          category: 'payments',
          assignedTo: null,
          closedAt: null,
          closedBy: null,
          lastMessageAt: new Date()
        },
        { upsert: true, setDefaultsOnInsert: true }
      );
      // Avisar a los paneles admin para que muevan el chat a Pagos en vivo.
      notifyAdmins('chat_moved', { userId: req.user.userId, to: 'payments', by: 'sistema' });
      // Entregar los mensajes en tiempo real (al panel admin y al usuario).
      io.to('admins').emit('new_message', { message: withdrawMsg, userId: req.user.userId, username: req.user.username });
      io.to(`chat_${req.user.userId}`).emit('new_message', withdrawMsg);
      io.to(`user_${req.user.userId}`).emit('new_message', withdrawMsg);
      if (withdrawConfirmMsg) {
        io.to('admins').emit('new_message', { message: withdrawConfirmMsg, userId: req.user.userId, username: req.user.username });
        io.to(`chat_${req.user.userId}`).emit('new_message', withdrawConfirmMsg);
        io.to(`user_${req.user.userId}`).emit('new_message', withdrawConfirmMsg);
      }
    } catch (chatErr) {
      logger.error(`[withdrawal/request] No se pudo mover el chat a pagos: ${chatErr.message}`);
    }

    // #566: ≥ umbral → queda en CONFIRMACIÓN DE PAGOS (una persona revisa); por debajo → se paga SOLO por hgcash, ya mismo.
    try {
      const prCfg = await getPayoutReviewConfig();
      // #814 (owner 2026-10-22): "pagos y retiros automáticos, excepto mayores a $100.000" ⇒ revisión sólo si SUPERA el umbral.
      let needsReview = amountNum > prCfg.minArs || !prCfg.autoBelow || !hgcashPay.isEnabled();
      // #881: además, sólo clientes de CONFIANZA cobran solos (se puede apagar en Confirmación de pagos → Regla).
      let trustWhy = null;
      if (!needsReview && prCfg.trustedOnly) { const t = await _payoutTrust(user.id, prCfg); if (!t.trusted) { needsReview = true; trustWhy = t.why; } }
      // #820: por id (antes por usuario+monto: podía marcar un retiro VIEJO del mismo monto).
      await PendingPayout.updateOne({ id: _newPayoutId }, { $set: Object.assign({ reviewRequired: needsReview, autoPay: !needsReview }, trustWhy ? { reviewReason: 'no es cliente de confianza: ' + trustWhy.join(' · ') } : {}) });
      if (needsReview) {
        await _emitAdminOnlyChatNote(user.id, user.username, trustWhy
          ? `🔎 RETIRO EN REVISIÓN: $${amountNum.toLocaleString('es-AR')} — no sale solo porque todavía no es cliente de confianza (${trustWhy.join(' · ')}). Confirmalo o rechazalo en Panel → Confirmación de pagos.`
          : `🔎 RETIRO EN REVISIÓN: $${amountNum.toLocaleString('es-AR')} (umbral $${prCfg.minArs.toLocaleString('es-AR')}). Confirmalo o rechazalo en Panel → Confirmación de pagos.`).catch(() => {});
      } else {
        const pp = { id: _newPayoutId };
        if (pp) setImmediate(() => { _payPendingPayout(pp.id, PAYOUT_AUTO_ACTOR, getPublicBaseUrl()).then((o) => { logger.info(`[pay-review] pago AUTOMÁTICO $${amountNum} ${user.username} → ${o.code} ${JSON.stringify(o.body).slice(0, 160)}`); _payoutAutoFailNote(pp.id, o).catch(() => {}); }).catch((e) => logger.warn(`[pay-review] pago automático falló: ${e.message}`)); });
      }
    } catch (e) { logger.warn(`[pay-review] no se pudo clasificar el retiro: ${e.message}`); }

    // Meta CAPI — WithdrawRequest (señal de usuario activo / ganador).
    try {
      metaCapi.track(
        'WithdrawRequest',
        { email: user.email, phone: user.phone, externalId: req.user.userId, fbc: user.metaFbc, fbp: user.metaFbp },
        { value: amountNum, currency: 'ARS', content_name: 'withdraw_self_service' },
        { eventId: req.body && req.body.metaEventId, req }
      );
    } catch (e) { /* tracking nunca bloquea la respuesta */ }

    // FIX (regresión #68): antes esta respuesta referenciaba `result.data` (el viejo
    // withdrawFromUser que se eliminó al pasar a descontar-al-confirmar). Como `result`
    // ya no existe, tiraba ReferenceError → 500 "Error del servidor" DESPUÉS de haber
    // creado el PendingPayout y mandado el mensaje → el cliente reintentaba y duplicaba.
    res.json({
      success: true,
      message: `Retiro de ${amountFmt} solicitado correctamente`
    });
    // #728 (owner): el usuario de prueba vuelve a "primer cliente" solo, 8 s después de pedir el retiro (sólo entorno de prueba).
    try { if (_isTestEnv() && AUTO_RESET_USERNAMES.includes(String(user.username))) setTimeout(() => { _resetTestUser({ id: user.id, username: user.username }, 'auto tras retiro').catch(() => {}); }, 8000); } catch (_) {}
  } catch (error) {
    logger.error(`Error en withdrawal/request: ${error.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  } finally {
    if (withdrawLockAcquired) releaseRefundLock(req.user.userId, 'withdraw');
  }
}
app.post('/api/withdrawal/request', authMiddleware, _withdrawalRequestHandler);

// ============================================
// BONO POR INSTALAR LA APP (one-time)
// ============================================
const INSTALL_BONUS_AMOUNT = 5000;

// % del bono por instalar la app (owner 2026-09-17: era un 100% fijo en el
// código; va variando según el mes/día → Config['installBonusPct'], editable
// desde COMANDOS → "Bono por instalar la app", solo admin general). Sin cache
// a propósito (multi-instancia). Todos los textos lo leen por la variable {pct}.
const INSTALL_BONUS_PCT_DEFAULT = 25;
async function getInstallBonusPct() {
  try {
    const n = Number(await getConfig('installBonusPct', null));
    if (Number.isFinite(n) && n >= 0 && n <= 500) return Math.round(n);
  } catch (_) { /* fallback */ }
  return INSTALL_BONUS_PCT_DEFAULT;
}
// ON/OFF del bono por instalar la app (owner 2026-10-16, #221): APAGADO por default. Con
// el flag en false el status dice eligible:false/disabled:true (la PWA no muestra nada),
// el claim rebota (DISABLED) y la carga NO manda el cartel de "instalá la app" con regalo.
// Los clientes que YA reclamaron conservan su % pendiente (resolveAutoBonus lo honra).
async function getInstallBonusEnabled() {
  try { const v = await getConfig('installBonusEnabled', null); if (v === true || v === false) return v; } catch (_) {}
  return false;
}
// #266 (owner 2026-10-17): % que anuncia el cartel "SERVICIO COMPLETO" del chat principal de la
// PWA ("cargando de forma automática tenés un {pct}% en todas tus cargas"). Desde #274 es además el
// bono REAL de toda carga hgcash sin otro bono pendiente (resolveAutoBonus, con tope). Config
// ['autoLoadBonusPct'], editable en COMANDOS → Bonos automáticos.
const AUTO_LOAD_BONUS_PCT_DEFAULT = 10;
async function getAutoLoadBonusPct() {
  try {
    const n = Number(await getConfig('autoLoadBonusPct', null));
    if (Number.isFinite(n) && n >= 0 && n <= 500) return Math.round(n);
  } catch (_) { /* fallback */ }
  return AUTO_LOAD_BONUS_PCT_DEFAULT;
}
// #290 (owner 2026-10-17): "la publi va a venir con un 50% automático en la primera carga". % que lleva la
// PRIMERA carga real de cada cliente (manual o hgcash) cuando no tiene otro bono pendiente, con el tope de
// siempre. Config['firstDepositBonusPct'] (default 50), editable en COMANDOS → Bonos automáticos. 0 = apagado.
// #974 (owner 2026-10-24): el 100% de la primera carga vuelve a tener TOPE propio (Config['firstDepositCapArs'], $15.000; 0 = sin tope) y nada sobre
// el resto. Antes era libre (#812): una carga de $500.000 regalaba $500.000. Al cliente típico ($5.000–$10.000) no le cambia nada.
const FIRST_DEPOSIT_CAP_DEFAULT = 15000;
async function getFirstDepositCapArs() { try { const n = Number(await getConfig('firstDepositCapArs', null)); if (Number.isFinite(n) && n >= 0) return Math.round(n); } catch (_) {} return FIRST_DEPOSIT_CAP_DEFAULT; }
const FIRST_DEPOSIT_BONUS_PCT_DEFAULT = 100; // #810 (owner 2026-10-22): 100% en la primera carga
async function getFirstDepositBonusPct() {
  try {
    const n = Number(await getConfig('firstDepositBonusPct', null));
    if (Number.isFinite(n) && n >= 0 && n <= 500) return Math.round(n);
  } catch (_) { /* fallback */ }
  return FIRST_DEPOSIT_BONUS_PCT_DEFAULT;
}
// ¿Es la primera carga real del cliente? Se evalúa ANTES de persistir la Transaction de la carga en curso
// (así lo hacen /api/admin/deposit y _hgcashCreditToPlatform) ⇒ 0 cargas previas = primera.
async function _isFirstRealDeposit(user) {
  try {
    const n = await Transaction.countDocuments({
      $or: [{ userId: user.id }, { username: user.username }],
      type: 'deposit',
      'metadata.source': { $nin: ['install_bonus', 'welcome_gift', 'payout_refund'] }
    });
    return n === 0;
  } catch (_) { return false; } // ante duda, no regalar
}
// #299 (owner 2026-10-17): CARGA MÍNIMA informativa ($5.000 default): la app la muestra en "Adjuntar comprobante aquí"
// y en el paso 1 de la carga automática. Config['minDepositArs'], editable en COMANDOS → Bonos automáticos.
// Es un AVISO al cliente: no bloquea acreditaciones (una transferencia menor igual se acredita).
const MIN_DEPOSIT_ARS_DEFAULT = 2000; // #897 (owner): carga mínima $2.000 en toda la página
// #379 (owner 2026-10-18): RETIRO MÍNIMO (antes $4.999 fijo). Config['withdrawMinArs'], editable en COMANDOS → Bonos automáticos.
const WITHDRAW_MIN_ARS_DEFAULT = 5000; // #976 (owner 2026-10-24): antes $10.000
// #385: textos de los botones "Adjuntar comprobante aquí" / "Retirar premio" (editables en COMANDOS).
// #442 (owner 2026-10-18): BANCO CON FALLAS (retiros). Config['bankOutage'] = { active, mode:'manual'|'auto', since, reason }.
// Manual: tilde en Configuración → "Banco con fallas". Automático: 2 pagos hgcash fallidos seguidos la ACTIVAN; el primer pago
// OK la DESACTIVA (sólo si la activó el automático). Mientras está activa, POST /api/withdrawal/request responde 503 con
// /sys_bank_down y anota al cliente en Config['bankOutageWaiters']; al normalizarse se les manda /sys_bank_up por chat + push.
const BANK_DOWN_DEFAULT = '⚠️ El banco está con fallas en este momento y no podemos procesar retiros. Apenas se normalice te avisamos por acá para que vuelvas a intentarlo. Disculpá las molestias.';
const BANK_UP_DEFAULT = '✅ El banco ya se normalizó: podés volver a pedir tu retiro cuando quieras. Disculpá las molestias.';
// #443: mensaje al cliente cuyo PAGO falló (sus fichas ya pueden estar descontadas → no se le pide que vuelva a pedirlo) y
// aviso a ese mismo cliente cuando el banco vuelve.
const BANK_FAIL_CLIENT_DEFAULT = '⚠️ El banco está con fallas y tu retiro no pudo procesarse todavía. Quedó pendiente: apenas se normalice lo procesamos y te avisamos por acá. Disculpá las molestias.';
const BANK_UP_PENDING_DEFAULT = '✅ El banco volvió a funcionar. Tu retiro pendiente se procesa ahora; si en un rato no lo ves acreditado, escribinos por Soporte. Disculpá las molestias.';
// Config['bankOutageSettings']: todo editable desde Configuración → Banco con fallas.
const BANK_SETTINGS_DEFAULT = { autoEnabled: true, failThreshold: 3, pauseWithdrawals: true, notifyFailedClient: false }; // #890: al cliente no se le avisa la falla
async function getBankSettings() {
  try {
    const v = await getConfig('bankOutageSettings', null);
    if (v && typeof v === 'object') return {
      autoEnabled: v.autoEnabled !== false,
      failThreshold: Math.max(1, Math.min(10, parseInt(v.failThreshold, 10) || 1)),
      pauseWithdrawals: v.pauseWithdrawals !== false,
      notifyFailedClient: v.notifyFailedClient !== false
    };
  } catch (_) {}
  return { ...BANK_SETTINGS_DEFAULT };
}
async function getBankOutage() {
  try { const v = await getConfig('bankOutage', null); if (v && typeof v === 'object') return { active: !!v.active, mode: v.mode || 'manual', since: v.since || null, reason: v.reason || null, updatedBy: v.updatedBy || null, eventId: v.eventId || null }; } catch (_) {}
  return { active: false, mode: 'manual', since: null, reason: null, updatedBy: null };
}
const BankOutageEvent = require('./src/models/BankOutageEvent'); // #444: historial
async function setBankOutage(active, opts = {}) {
  const mode = opts.mode || 'manual', by = opts.by || 'sistema', reason = opts.reason || null;
  const cur = await getBankOutage();
  if (!!cur.active === !!active) return { changed: false, state: cur };
  const next = { active: !!active, mode, since: active ? new Date().toISOString() : cur.since, reason: active ? String(reason || '').slice(0, 160) || null : cur.reason, updatedBy: by, updatedAt: new Date().toISOString(), eventId: active ? uuidv4() : (cur.eventId || null) };
  if (!active) { next.since = null; next.reason = null; }
  await Config.set('bankOutage', next, by);
  logger.warn(`[bank-outage] ${active ? 'ACTIVADA' : 'DESACTIVADA'} (${mode}) por ${by}${reason ? ' — ' + reason : ''}`);
  if (active) {
    try { await BankOutageEvent.create({ id: next.eventId, startedAt: new Date(), mode, reason: next.reason, openedBy: by, failedPayouts: mode === 'auto' ? _bankFailStreak : 0 }); } catch (e) { logger.warn('[bank-outage] historial: ' + e.message); }
  } else {
    // #444: cierre → avisar a los anotados y dejar el evento en el historial con hora y cantidades.
    let n = { total: 0, waiters: 0, failed: 0 };
    try { n = await _notifyBankOutageWaiters(); } catch (e) { logger.warn('[bank-outage] aviso: ' + e.message); }
    try {
      const evId = cur.eventId || null;
      const set = { endedAt: new Date(), closedBy: by, notifiedTotal: n.total, notifiedWaiters: n.waiters, notifiedFailed: n.failed };
      let r = evId ? await BankOutageEvent.updateOne({ id: evId }, { $set: set }) : null;
      if (!r || !(r.modifiedCount || r.nModified)) await BankOutageEvent.create({ id: uuidv4(), startedAt: cur.since ? new Date(cur.since) : new Date(), mode: cur.mode || mode, reason: cur.reason || null, openedBy: cur.updatedBy || null, ...set });
    } catch (e) { logger.warn('[bank-outage] historial cierre: ' + e.message); }
  }
  return { changed: true, state: next };
}
// #443: la lista guarda { userId, kind: 'waiter' (quiso retirar durante la falla) | 'failed' (su pago falló) }.
async function _addBankOutageWaiter(userId, kind = 'waiter') {
  try {
    const arr = ((await getConfig('bankOutageWaiters', [])) || []).map((x) => (typeof x === 'string' ? { userId: x, kind: 'waiter' } : x));
    const i = arr.findIndex((x) => x && x.userId === userId);
    if (i >= 0) { if (kind === 'failed') arr[i].kind = 'failed'; } else arr.push({ userId, kind });
    await Config.set('bankOutageWaiters', arr.slice(-3000), 'sistema');
  } catch (_) {}
}
async function _notifyBankOutageWaiters() {
  const arr = ((await getConfig('bankOutageWaiters', [])) || []).map((x) => (typeof x === 'string' ? { userId: x, kind: 'waiter' } : x)).filter((x) => x && x.userId);
  if (!arr.length) return { total: 0, waiters: 0, failed: 0 };
  await Config.set('bankOutageWaiters', [], 'sistema');
  const textUp = await renderSystemCommand('/sys_bank_up', BANK_UP_DEFAULT, {});
  const textPend = await renderSystemCommand('/sys_bank_up_pending', BANK_UP_PENDING_DEFAULT, {});
  const kinds = Object.fromEntries(arr.map((x) => [x.userId, x.kind]));
  const users = await User.find({ id: { $in: arr.map((x) => x.userId) } }).select('id username fcmTokens fcmTokenContext').lean();
  for (const u of users) {
    const failed = kinds[u.id] === 'failed';
    try { await _sendUserSystemMessage(u, failed ? textPend : textUp, { push: { title: 'Banco normalizado ✅', body: failed ? 'Tu retiro pendiente se procesa ahora.' : 'Ya podés volver a pedir tu retiro.' } }); } catch (_) {}
  }
  const failedN = users.filter((u) => kinds[u.id] === 'failed').length;
  logger.info(`[bank-outage] avisados ${users.length} clientes (${failedN} con pago fallido)`);
  return { total: users.length, waiters: users.length - failedN, failed: failedN };
}
let _bankFailStreak = 0;
// #443: pago fallido → (1) aviso al cliente afectado y queda anotado como 'failed'; (2) al llegar al umbral (default 1) se
// activa la alerta automática. `payout` = PendingPayout (userId, username, amount).
async function _bankPayoutFailed(reason, payout) {
  _bankFailStreak++;
  try {
    const st = await getBankSettings();
    // #890 (owner): "no generar fricción: si falla, que un agente confirme y listo, no pasó nada" ⇒ por defecto el cliente NO se entera
    // de la falla (ni el aviso de banco con fallas ni, después, el de "banco normalizado"); sólo recibe el aviso normal cuando se paga.
    if (payout && payout.userId && st.notifyFailedClient) {
      _addBankOutageWaiter(payout.userId, 'failed').catch(() => {});
      if (!(Number(payout.autoRetries) > 0)) { // #814: en los reintentos automáticos no se le vuelve a avisar
        try {
          const u = await User.findOne({ id: payout.userId }).select('id username fcmTokens fcmTokenContext').lean();
          if (u) await _sendUserSystemMessage(u, await renderSystemCommand('/sys_bank_fail_client', BANK_FAIL_CLIENT_DEFAULT, { monto: '$' + Number(payout.amount || 0).toLocaleString('es-AR') }), { push: { title: 'Retiro demorado ⚠️', body: 'El banco está con fallas. Te avisamos apenas se normalice.' } });
        } catch (_) {}
      }
    }
    const cur = await getBankOutage();
    if (st.autoEnabled && !cur.active && _bankFailStreak >= st.failThreshold) await setBankOutage(true, { mode: 'auto', reason: 'pagos fallidos: ' + String(reason || '').slice(0, 80), by: 'auto' });
  } catch (_) {}
}
async function _bankPayoutOk() {
  _bankFailStreak = 0;
  try {
    const cur = await getBankOutage();
    if (cur.active && cur.mode === 'auto') { await setBankOutage(false, { mode: 'auto', by: 'auto' }); return; }
    // #444: aunque la alerta no esté activa (o sea manual), si hay clientes avisados de la falla se les manda el mensaje de
    // salida con el primer pago que sale bien, y queda en el historial como "aviso".
    if (!cur.active) {
      const n = await _notifyBankOutageWaiters();
      if (n.total > 0) { try { await BankOutageEvent.create({ id: uuidv4(), startedAt: new Date(), endedAt: new Date(), mode: 'aviso', reason: 'pago OK: aviso de salida', openedBy: 'auto', closedBy: 'auto', notifiedTotal: n.total, notifiedWaiters: n.waiters, notifiedFailed: n.failed }); } catch (_) {} }
    }
  } catch (_) {}
}
