const SUPPORT_TERMS_BTN = { kind: 'go_section', target: 'terms', label: '📄 Bases y condiciones', channel: 'support', small: true }; // #878: botón chico
function _supportTopicFromText(text) {
  const t = String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (!t || t.length < 4) return null;
  if (/\bbono|rollover|apost|desbloq|bloquead|objetivo de apuestas/.test(t)) return 'bono'; // #715
  if (/reembols|devoluc|cashback|rakeback/.test(t)) return 'reembolso';
  if (/retir|cobr|me pag|no me pag|pago pendiente|premio/.test(t)) return 'retiro';
  if (/carg|transfer|deposit|comprobante|acredit|cbu|alias/.test(t)) return 'carga';
  return null;
}
async function _supportQuickReply(userId, username, quick, text) {
  try {
    const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('es-AR');
    const u = { id: userId, username };
    if (quick === 'cargar' || quick === 'retirar') {
      const vars = { min: money(await getMinDepositArs()), retiro_min: money(await getWithdrawMinArs()) };
      const txt = quick === 'cargar'
        ? await renderSystemCommand('/sys_support_quick_cargar', SUPPORT_QUICK_CARGAR_DEFAULT, vars)
        : await renderSystemCommand('/sys_support_quick_retirar', SUPPORT_QUICK_RETIRAR_DEFAULT, vars);
      if (!txt) return;
      const meta = quick === 'cargar'
        ? { kind: 'go_section', target: 'full', label: '⚡ Ir a Carga automática', channel: 'support' }
        : { kind: 'go_section', target: 'withdraw', label: '💸 Ir a Retirar premio', channel: 'support' };
      await _sendUserSystemMessage(u, txt, { metadata: meta });
      return;
    }
    // #702: tema por chip (carga / retiro / reembolso / otro) o por palabras clave del texto libre
    const explicit = ['carga', 'retiro', 'reembolso', 'otro', 'bono'].includes(quick);
    let topic = explicit ? quick : _supportTopicFromText(text);
    if (!topic) return _supportAutoReply(userId, username);
    // #784 (owner: "se rompió, no contesta automático; cada botón tiene que tener su respuesta"): el botón de TEMA tocado por el
    // cliente responde SIEMPRE. Antes se callaba si un agente había respondido hace < 10 min (aunque ya hubiera cerrado el chat) o si
    // ese tema ya se había contestado en las últimas 2 h. Esos frenos quedan SÓLO para la detección por palabras del texto libre, y el
    // de "agente reciente" no cuenta si después el agente cerró el chat.
    if (!explicit) {
      const closed = await Message.findOne({ receiverId: userId, type: 'system', 'metadata.kind': 'support_closed' }).sort({ timestamp: -1 }).select('timestamp').lean();
      const since = new Date(Math.max(Date.now() - 10 * 60 * 1000, closed ? new Date(closed.timestamp).getTime() : 0));
      const agentRecent = await Message.findOne({ receiverId: userId, senderRole: { $in: SUPPORT_ROLES }, channel: 'support', timestamp: { $gte: since } }).select('_id').lean();
      if (agentRecent) return;
      const recent = await Message.findOne({ receiverId: userId, type: 'system', 'metadata.topic': topic, timestamp: { $gte: new Date(Date.now() - 2 * 3600 * 1000) } }).select('_id').lean();
      if (recent) return;
    }
    const vars = { min: money(await getMinDepositArs()), retiro_min: money(await getWithdrawMinArs()), rollover: String(await _giftRolloverX()), carga: String(await getDepositRolloverX()) }; // #883: {carga}
    try { const _fd = await getFirstDepositBonusPct(), _cap = await getFirstDepositCapArs(), _ig = await getInstallGiftConfig(); Object.assign(vars, { fd_pct: String(_fd), fd_tope: _cap > 0 ? money(_cap) : 'sin tope', ig_txt: _ig.enabled ? ' y ' + (_ig.fixedArs > 0 ? money(_ig.fixedArs) : _ig.pct + '%') + ' extra instalando la app y activando las notificaciones' : '' }); } catch (_) {} // #974
    if (topic === 'otro') {
      const t = await renderSystemCommand('/sys_support_topic_otro', SUPPORT_TOPIC_OTRO_DEFAULT, vars);
      if (t) await _sendUserSystemMessage(u, t, { metadata: Object.assign({}, SUPPORT_TERMS_BTN, { topic }) });
      return;
    }
    const first = topic === 'carga' ? await renderSystemCommand('/sys_support_topic_carga', SUPPORT_TOPIC_CARGA_DEFAULT, vars)
      : topic === 'retiro' ? await renderSystemCommand('/sys_support_topic_retiro', SUPPORT_TOPIC_RETIRO_DEFAULT, vars)
      : topic === 'bono' ? await renderSystemCommand('/sys_support_topic_bono', SUPPORT_TOPIC_BONO_DEFAULT, vars) // #715
      : await renderSystemCommand('/sys_support_topic_reembolso', SUPPORT_TOPIC_REEMBOLSO_DEFAULT, vars);
    if (first) {
      const meta = topic === 'reembolso' ? { kind: 'go_section', target: 'refund', label: '🎁 Ver info de reembolso', channel: 'support', topic } : { channel: 'support', topic };
      await _sendUserSystemMessage(u, first, { metadata: meta });
    }
    const second = await renderSystemCommand('/sys_support_detail', SUPPORT_DETAIL_DEFAULT, vars);
    if (second) await _sendUserSystemMessage(u, second, { metadata: Object.assign({}, SUPPORT_TERMS_BTN, { topic: 'detail', of: topic }) });
  } catch (e) { logger.warn(`[support] quick-reply: ${e.message}`); }
}
async function _supportAutoReply(userId, username) {
  try {
    const txt = await renderSystemCommand('/sys_support_autoreply', SUPPORT_AUTOREPLY_DEFAULT, { nombre: await getSupportAgentName() });
    if (!txt) return;
    const recent = await Message.findOne({ receiverId: userId, type: 'system', 'metadata.kind': 'support_ack', timestamp: { $gte: new Date(Date.now() - 2 * 3600 * 1000) } }).select('_id').lean();
    if (recent) return;
    const agentRecent = await Message.findOne({ receiverId: userId, senderRole: { $in: ['admin', 'depositor', 'withdrawer', 'comunidad'] }, channel: 'support', timestamp: { $gte: new Date(Date.now() - 10 * 60 * 1000) } }).select('_id').lean();
    if (agentRecent) return;
    await _sendUserSystemMessage({ id: userId, username }, txt, { metadata: { kind: 'support_ack', channel: 'support', target: 'terms', label: '📄 Bases y condiciones' } }); // #702: + botón
  } catch (e) { logger.warn(`[support] auto-respuesta: ${e.message}`); }
}
// El cliente sólo ve el chat desde esta fecha (el chat viejo de cargas queda oculto para él; el panel lo ve entero).
let _supportSinceCache = { at: 0, value: null };
async function getSupportChannelSince() {
  if (Date.now() - _supportSinceCache.at < 60 * 1000) return _supportSinceCache.value;
  let v = null;
  try { const raw = await getConfig('supportChannelSince', null); if (raw) { const d = new Date(raw); if (!isNaN(d.getTime())) v = d; } } catch (_) {}
  _supportSinceCache = { at: Date.now(), value: v };
  return v;
}


// #375: bienvenida automática del chat de SOPORTE (/sys_welcome). Variables: {username}, {plataformas}, {escalera}, {cbu}.
const SUPPORT_WELCOME_TEXT = "👋 ¡Hola, {username}! Ya te respondemos en breve.\n\nMientras tanto, elegí con los botones de abajo qué necesitás (cargar, retirar, reembolso, referidos u otra consulta)."; // #599 (owner): primer mensaje "ya te responden en breve" + botones
async function getDailyRefundPct() { try { const t = (await getRefundTiersByPeriod()).daily || []; return t.reduce((m, x) => Math.max(m, Number(x.pct) || 0), 0); } catch (_) { return 0; } }
const INSTALL_BONUS_BANNER_DEFAULT = '¡{pct}% de bono en tu próxima carga!';
const INSTALL_BONUS_BANNER_NOTE_DEFAULT = '⚠️ Es por única vez. Se aplica automáticamente en tu próxima carga: el {pct}% extra entra junto con la carga.';

