    const d = await _gameCatalog(q, page);
    if (!d) return res.status(503).json({ error: 'No pudimos traer los juegos de Girox. Probá de nuevo en un momento.' });
    res.set('Cache-Control', 'private, max-age=300'); res.json(d);
