    const time = String(it.time || '').trim();
    if (!(day >= 1 && day <= 31)) return { error: `Campaña ${i + 1}: el día tiene que estar entre 1 y 31.` };
    if (!/^\d{2}:\d{2}$/.test(time)) return { error: `Campaña ${i + 1}: la hora tiene que ser HH:mm.` };
