    hours: num(r.hours, AUTOPILOT_DEFAULT.hours, 1, 48), cap: num(r.cap, AUTOPILOT_DEFAULT.cap, 2, 60),
    parts: num(r.parts, AUTOPILOT_DEFAULT.parts, 1, 12), gapMin: num(r.gapMin, AUTOPILOT_DEFAULT.gapMin, 5, 180),
