// Arma un plan con lo YA programado/enviado en un mes ("guardar este mes como plan").
app.post('/api/admin/cronograma-plans/from-month', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!_schedCanManage(req.user.role)) return res.status(403).json({ error: 'Sin permiso.' });
    const b = req.body || {};
    const m = /^\d{4}-\d{2}$/.test(String(b.month || '')) ? String(b.month) : _schedArtKey(new Date()).slice(0, 7);
    const name = String(b.name || '').trim().slice(0, 80) || `Plan ${m}`;
    const from = new Date(new Date(m + '-01T00:00:00Z').getTime() + SCHED_ART_OFFSET_MS);
    const [y, mo] = m.split('-').map(Number);
    const nextM = `${mo === 12 ? y + 1 : y}-${String(mo === 12 ? 1 : mo + 1).padStart(2, '0')}`;
    const to = new Date(new Date(nextM + '-01T00:00:00Z').getTime() + SCHED_ART_OFFSET_MS);
    const camps = await ScheduledCampaign.find({ cancelled: { $ne: true }, 'parts.runAt': { $gte: from, $lt: to } }).sort({ runAt: 1 }).lean();
    if (!camps.length) return res.status(400).json({ error: `No hay campañas programadas en ${m} para armar el plan.` });
    const items = camps.map(c => {
      const parts = (c.parts || []).slice().sort((a, b2) => new Date(a.runAt) - new Date(b2.runAt));
      const first = new Date(parts[0].runAt);
      const art = new Date(first.getTime() - SCHED_ART_OFFSET_MS);
      const gap = parts.length > 1 ? Math.max(0.05, Math.min(48, Math.round((new Date(parts[1].runAt) - first) / 60000) / 60)) : 0.5; // #297 en horas (fraccional)
      return { day: art.getUTCDate(), time: `${String(art.getUTCHours()).padStart(2, '0')}:${String(art.getUTCMinutes()).padStart(2, '0')}`, parts: parts.length, gapHours: gap, name: c.name || '', payload: c.payload };
    });
    const n = _planNormalizeItems(items);
    if (n.error) return res.status(400).json({ error: n.error });
    const p = await StrategyPlan.create({ id: uuidv4(), name, notes: String(b.notes || `Armado desde el mes ${m}`).slice(0, 500), items: n.items, createdBy: req.user.username });
    logger.info(`[plan] ${req.user.username} guardó el mes ${m} como plan "${name}" (${n.items.length} campañas)`);
    res.json({ success: true, plan: _planPublic(p.toObject()) });
  } catch (err) { logger.error(`POST /api/admin/cronograma-plans/from-month: ${err.message}`); res.status(500).json({ error: 'Error del servidor' }); }
});
app.put('/api/admin/cronograma-plans/:id', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!_schedCanManage(req.user.role)) return res.status(403).json({ error: 'Sin permiso.' });
    const p = await StrategyPlan.findOne({ id: String(req.params.id || '') });
    if (!p) return res.status(404).json({ error: 'Plan no encontrado' });
    const b = req.body || {};
    if (typeof b.name === 'string' && b.name.trim()) p.name = b.name.trim().slice(0, 80);
    if (typeof b.notes === 'string') p.notes = b.notes.slice(0, 500);
    if (Array.isArray(b.items)) { const n = _planNormalizeItems(b.items); if (n.error) return res.status(400).json({ error: n.error }); p.items = n.items; p.markModified('items'); }
    p.updatedBy = req.user.username;
    await p.save();
    res.json({ success: true, plan: _planPublic(p.toObject()) });
  } catch (err) { res.status(500).json({ error: 'Error del servidor' }); }
});
app.delete('/api/admin/cronograma-plans/:id', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!_schedCanManage(req.user.role)) return res.status(403).json({ error: 'Sin permiso.' });
    const r = await StrategyPlan.deleteOne({ id: String(req.params.id || '') });
    res.json({ success: true, deleted: r.deletedCount > 0 });
  } catch (err) { res.status(500).json({ error: 'Error del servidor' }); }
});
// #295: agregar UNA campaña al plan desde el formulario del lote ("🧭 Guardar en el plan") / quitar una.
app.post('/api/admin/cronograma-plans/:id/items', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!_schedCanManage(req.user.role)) return res.status(403).json({ error: 'Sin permiso.' });
    const p = await StrategyPlan.findOne({ id: String(req.params.id || '') });
    if (!p) return res.status(404).json({ error: 'Plan no encontrado' });
    const n = _planNormalizeItems([(req.body || {}).item || req.body]);
    if (n.error) return res.status(400).json({ error: n.error });
    if ((p.items || []).length >= 60) return res.status(400).json({ error: 'El plan ya tiene 60 campañas (máximo).' });
    p.items.push(n.items[0]);
    p.items.sort((a, b) => a.day - b.day || String(a.time).localeCompare(String(b.time)));
    p.markModified('items'); p.updatedBy = req.user.username;
    await p.save();
    res.json({ success: true, plan: _planPublic(p.toObject()) });
  } catch (err) { logger.error(`POST /api/admin/cronograma-plans/:id/items: ${err.message}`); res.status(500).json({ error: 'Error del servidor' }); }
});
app.delete('/api/admin/cronograma-plans/:id/items/:idx', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!_schedCanManage(req.user.role)) return res.status(403).json({ error: 'Sin permiso.' });
    const p = await StrategyPlan.findOne({ id: String(req.params.id || '') });
    if (!p) return res.status(404).json({ error: 'Plan no encontrado' });
    const i = parseInt(req.params.idx, 10);
    if (!(i >= 0 && i < (p.items || []).length)) return res.status(400).json({ error: 'Campaña inexistente en el plan.' });
    p.items.splice(i, 1); p.markModified('items'); p.updatedBy = req.user.username;
    await p.save();
    res.json({ success: true, plan: _planPublic(p.toObject()) });
  } catch (err) { res.status(500).json({ error: 'Error del servidor' }); }
});
// Aplica el plan a un mes: una ScheduledCampaign por ítem (fechas pasadas → salteadas; audiencia vacía → salteada).
app.post('/api/admin/cronograma-plans/:id/apply', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    if (!_schedCanManage(req.user.role)) return res.status(403).json({ error: 'Sin permiso.' });
    const p = await StrategyPlan.findOne({ id: String(req.params.id || '') });
    if (!p) return res.status(404).json({ error: 'Plan no encontrado' });
    const m = /^\d{4}-\d{2}$/.test(String((req.body || {}).month || '')) ? String(req.body.month) : _schedArtKey(new Date()).slice(0, 7);
    const [y, mo] = m.split('-').map(Number);
    const daysIn = new Date(Date.UTC(y, mo, 0)).getUTCDate();
    const created = [], skipped = [];
    for (const it of p.items || []) {
      const dd = Math.min(it.day, daysIn);
      const label = `día ${it.day} ${it.time} · ${it.name || (it.payload.giftType === 'percent' ? '+' + it.payload.amount + '%' : '$' + it.payload.amount)}`;
      const first = _schedParseRunAt(`${m}-${String(dd).padStart(2, '0')}T${it.time}`);
      if (!first) { skipped.push({ label, reason: 'fecha inválida' }); continue; }
      if (first.getTime() < Date.now() - 60 * 1000) { skipped.push({ label, reason: 'la fecha ya pasó' }); continue; }
      const partsIn = Array.from({ length: it.parts || 1 }, (_, i) => ({ runAt: new Date(first.getTime() + i * (it.gapHours || 5) * 3600000).toISOString() }));
      const pr = _schedBuildParts({ parts: partsIn });
      if (pr.error) { skipped.push({ label, reason: pr.error }); continue; }
      const est = await _schedEstimate(it.payload);
      if (est.error) { skipped.push({ label, reason: 'audiencia: ' + est.error }); continue; }
      if (it.payload.audienceType !== 'public' && !(est.count > 0)) { skipped.push({ label, reason: 'la audiencia quedó vacía hoy (se vuelve a evaluar si la programás a mano)' }); continue; }
      const c = await ScheduledCampaign.create({
        id: uuidv4(), name: (it.name || `${p.name} · día ${it.day}`).slice(0, 80), payload: it.payload, audienceLabel: est.label, estimatedCount: est.count,
        parts: pr.parts, runAt: pr.parts[0].runAt, createdBy: req.user.username, createdByRole: req.user.role, notes: `Plan "${p.name}" (aplicado a ${m})`.slice(0, 500)
      });
      created.push({ id: c.id, label, runAt: c.runAt, estimated: est.count });
    }
    p.lastAppliedMonth = m; p.lastAppliedAt = new Date(); p.appliedCount = (p.appliedCount || 0) + 1; p.updatedBy = req.user.username;
    await p.save();
    logger.info(`[plan] ${req.user.username} aplicó "${p.name}" a ${m}: ${created.length} programadas, ${skipped.length} salteadas`);
    res.json({ success: true, month: m, created, skipped, plan: _planPublic(p.toObject()) });
  } catch (err) { logger.error(`POST /api/admin/cronograma-plans/:id/apply: ${err.message}`); res.status(500).json({ error: 'Error del servidor' }); }
});


const BonusStrategyConfig = require('./src/models/BonusStrategyConfig');
const StrategyEnrollment = require('./src/models/StrategyEnrollment');

async function _getBonusStrategyConfig() {
  let cfg = await BonusStrategyConfig.findOne({ key: 'default' });
  if (!cfg) cfg = await BonusStrategyConfig.create({ key: 'default' });
  return cfg;
}

// Envia el push del paso + activa el PromoBonus + marca el paso en las
// inscripciones recibidas.
async function _strategySendStep(cfg, step, enrollments) {
  const stepCfg = step === 1 ? cfg.step1 : cfg.step2;
  const usernames = enrollments.map(e => e.username).filter(Boolean);
  if (usernames.length === 0) return;
  const data = { source: 'bonus-strategy', tag: 'bonus-strategy-step' + step };
  try {
    await sendNotificationToAllUsers(User, stepCfg.title, stepCfg.body, data, { username: { $in: usernames } });
  } catch (e) {
    logger.warn(`[bonus-strategy] push paso ${step} fallo: ${e.message}`);
  }
  // Bono vigente: reutiliza la logica de activateChargeBonuses con una regla
  // sintetica que lleva el % y la duracion del paso.
  const synthRule = {
    id: 'bonus-strategy-step' + step,
    code: 'ESTRATEGIA-' + stepCfg.percent + '%',
    name: 'Estrategia de bonos — paso ' + step,
    chargeBonus: { percent: stepCfg.percent, durationMinutes: stepCfg.durationMinutes }
  };
  try {
    await notificationRulesService.activateChargeBonuses(synthRule, usernames, _notifRulesModels, logger);
  } catch (e) {
    logger.warn(`[bonus-strategy] activar bonos paso ${step} fallo: ${e.message}`);
  }
  const ids = enrollments.map(e => e.id);
  const upd = step === 1
    ? { $set: { step: 1, step1At: new Date() } }
    : { $set: { step: 2, step2At: new Date() } };
  await StrategyEnrollment.updateMany({ id: { $in: ids } }, upd);
  logger.info(`[bonus-strategy] paso ${step}: enviado a ${usernames.length} usuario(s)`);
}

// REACTIVADA (owner 2026-06-22): la "estrategia de bonos por voto" (escalonada
// 15%→30%) vuelve a estar disponible, pero con TOPE de 30% y vigencia ≤2h. El tope
// lo refuerzan la validación del POST de config y activateChargeBonuses. Sólo corre
// si el owner la activa (isActive). Para apagarla del todo, poné el flag en true.
// APAGADA (owner 2026-06-24): se sacaron TODOS los bonos automáticos. Para reactivarla, false.
const BONUS_STRATEGY_DISABLED = true;
async function _runBonusStrategy() {
  if (BONUS_STRATEGY_DISABLED) return;
  try {
    const cfg = await BonusStrategyConfig.findOne({ key: 'default' }).lean();
    if (!cfg || !cfg.isActive) return;
    const now = Date.now();
    for (const plan of ['suave', 'normal', 'activo']) {
      const pd = (cfg.planDelays && cfg.planDelays[plan]) || { step1Hours: 24, step2Hours: 96 };
      // Paso 1: inscripciones en step 0 que cumplieron el retraso del paso 1.
      const cut1 = new Date(now - (Number(pd.step1Hours) || 0) * 3600 * 1000);
      const due1 = await StrategyEnrollment.find({ plan, step: 0, enrolledAt: { $lte: cut1 } }).limit(2000).lean();
      if (due1.length > 0) await _strategySendStep(cfg, 1, due1);
      // Paso 2: inscripciones en step 1 que cumplieron el retraso del paso 2.
      const cut2 = new Date(now - (Number(pd.step2Hours) || 0) * 3600 * 1000);
      const due2 = await StrategyEnrollment.find({ plan, step: 1, enrolledAt: { $lte: cut2 } }).limit(2000).lean();
      if (due2.length > 0) await _strategySendStep(cfg, 2, due2);
    }
  } catch (err) {
    logger.error(`[bonus-strategy] cron error: ${err.message}`);
  }
}
setTimeout(() => { _runBonusStrategy(); }, 4 * 60 * 1000);
setInterval(() => { _runBonusStrategy(); }, 10 * 60 * 1000);

// GET — config actual + contadores por paso.
app.get('/api/admin/bonus-strategy', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const cfg = await _getBonusStrategyConfig();
    const agg = await StrategyEnrollment.aggregate([
      { $group: { _id: '$step', count: { $sum: 1 } } }
    ]);
    const byStep = { 0: 0, 1: 0, 2: 0 };
    for (const g of agg) byStep[g._id] = g.count;
    const cfgObj = cfg.toObject();
    // Clamp de display: si quedó un singleton viejo (50%/100%), lo mostramos
    // capeado a 30% / 120min para que el panel refleje el tope real que se aplica.
    for (const s of ['step1', 'step2']) {
      if (cfgObj[s]) {
        cfgObj[s].percent = Math.min(30, Number(cfgObj[s].percent) || 0);
        cfgObj[s].durationMinutes = Math.min(120, Number(cfgObj[s].durationMinutes) || 120);
      }
    }
    res.json({
      success: true,
      config: cfgObj,
      stats: {
        inscriptos: byStep[0] + byStep[1] + byStep[2],
        sinPasos: byStep[0],
        recibieron50: byStep[1],
        completaron: byStep[2]
      }
    });
  } catch (err) {
    logger.error(`GET /api/admin/bonus-strategy: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// POST — guardar config (pasos + retrasos por plan).
app.post('/api/admin/bonus-strategy', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const b = req.body || {};
    const cfg = await _getBonusStrategyConfig();
    const _step = (src, dst) => {
      if (!src) return;
      // Tope de negocio: bono ≤30% y vigencia ≤120min (2h).
      if (src.percent != null) dst.percent = Math.max(1, Math.min(30, Number(src.percent) || 0));
      if (src.durationMinutes != null) dst.durationMinutes = Math.max(5, Math.min(120, Number(src.durationMinutes) || 120));
      if (typeof src.title === 'string') dst.title = src.title.slice(0, 120);
      if (typeof src.body === 'string') dst.body = src.body.slice(0, 300);
    };
    _step(b.step1, cfg.step1);
    _step(b.step2, cfg.step2);
    if (b.planDelays) {
      for (const plan of ['suave', 'normal', 'activo']) {
        const pd = b.planDelays[plan];
        if (!pd) continue;
        if (pd.step1Hours != null) cfg.planDelays[plan].step1Hours = Math.max(0, Number(pd.step1Hours) || 0);
        if (pd.step2Hours != null) cfg.planDelays[plan].step2Hours = Math.max(0, Number(pd.step2Hours) || 0);
      }
    }
    cfg.updatedAt = new Date();
    cfg.updatedBy = (req.user && req.user.username) || null;
    cfg.markModified('step1'); cfg.markModified('step2'); cfg.markModified('planDelays');
    await cfg.save();
    res.json({ success: true, config: cfg.toObject() });
  } catch (err) {
    logger.error(`POST /api/admin/bonus-strategy: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});

// POST — lanzar o pausar la estrategia. Al lanzar, inscribe a los que ya
// votaron la encuesta y todavia no tienen inscripcion (backfill).
app.post('/api/admin/bonus-strategy/activate', authMiddleware, adminMiddleware, async (req, res) => {
  try {
    const active = !(req.body && req.body.active === false);
    const cfg = await _getBonusStrategyConfig();
    cfg.isActive = active;
    if (active) {
      cfg.activatedAt = new Date();
      cfg.activatedBy = (req.user && req.user.username) || null;
    }
    await cfg.save();

    let backfilled = 0;
    if (active) {
      const voters = await User.find(
        { notificationPlan: { $in: ['suave', 'normal', 'activo'] } },
        { id: 1, username: 1, notificationPlan: 1, _id: 0 }
      ).lean();
      const existing = new Set(
        (await StrategyEnrollment.find({}, { username: 1, _id: 0 }).lean()).map(e => e.username)
      );
      const toInsert = [];
      for (const v of voters) {
        const uname = String(v.username || '').toLowerCase();
        if (!uname || existing.has(uname)) continue;
        toInsert.push({
          id: uuidv4(), userId: v.id, username: uname,
          plan: v.notificationPlan, enrolledAt: new Date(), step: 0
        });
      }
      if (toInsert.length > 0) {
        await StrategyEnrollment.insertMany(toInsert, { ordered: false }).catch(() => {});
        backfilled = toInsert.length;
      }
    }
    logger.info(`[bonus-strategy] ${active ? 'LANZADA' : 'PAUSADA'} por ${(req.user && req.user.username) || '?'} (backfill ${backfilled})`);
    res.json({ success: true, isActive: active, backfilled });
  } catch (err) {
    logger.error(`POST /api/admin/bonus-strategy/activate: ${err.message}`);
    res.status(500).json({ error: 'Error del servidor' });
  }
});


